import assert from "node:assert/strict";
import { describe, it } from "node:test";
import type { StaffRole } from "@dental/shared";
import type { WorkspaceFeatureFlags } from "../hooks/useWorkspaceProfile.js";
import {
	applyClinicModeToFlags,
	type ClinicMode,
	clinicCapabilities,
	clinicModes,
	describeHiddenCapabilities,
	hasCapability,
	visibleStaffRoles,
} from "../lib/clinicCapabilities.js";
import {
	appViews,
	getFilteredAppViews,
	getRailViewsHiddenByMode,
	getVisibleRailViews,
	viewLabels,
} from "../workspaceShell.js";

/*
 * ╨а╨╡╨╢╨╕╨╝ ╨║╨╗╨╕╨╜╨╕╨║╨╕ ╨┐╤А╨╛╤В╨╕╨▓ ╤Б╨╛╤Б╤В╨░╨▓╨░ ╤Н╨║╤А╨░╨╜╨░.
 *
 * ╨з╨в╨Ю ╨С╨л╨Ы╨Ю. ╨а╨╡╨╢╨╕╨╝ ╨║╨╗╨╕╨╜╨╕╨║╨╕ ╨╜╨╡ ╨▓╨╗╨╕╤П╨╗ ╨╜╨░ ╨╝╨╡╨╜╤О ╨▓╨╛╨╛╨▒╤Й╨╡: getFilteredAppViews
 * ╤Д╨╕╨╗╤М╤В╤А╨╛╨▓╨░╨╗ ╤А╨░╨╖╨┤╨╡╨╗╤Л ╤В╨╛╨╗╤М╨║╨╛ ╨┐╨╛ ╤А╨╛╨╗╨╕, ╨░ ╨┐╨╡╤А╨╡╨║╨╗╤О╤З╨░╤В╨╡╨╗╤М ╤А╨╛╨╗╨╕ ╨▓ ╤И╨░╨┐╨║╨╡ ╨▓╤Б╨╡╨│╨┤╨░
 * ╨┐╤А╨╡╨┤╨╗╨░╨│╨░╨╗ ╨▓╤Б╨╡ ╨┐╤П╤В╤М ╤А╨╛╨╗╨╡╨╣. ╨Ю╤В╨┤╨╡╨╗╤М╨╜╤Л╨╣ ╨▓╤А╨░╤З ╨┐╨╛╨╗╤Г╤З╨░╨╗ ╤В╤Г ╨╢╨╡ ╤А╨╡╨╗╤М╤Б╤Г ╨╕╨╖ ╨╛╨┤╨╕╨╜╨╜╨░╨┤╤Ж╨░╤В╨╕
 * ╤А╨░╨╖╨┤╨╡╨╗╨╛╨▓ ╨╕ ╤В╨╛╤В ╨╢╨╡ ╨▓╤Л╨▒╨╛╤А ┬л╨Р╤Б╤Б╨╕╤Б╤В╨╡╨╜╤В / ╨Р╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А / ╨г╨┐╤А╨░╨▓╨╗╤П╤О╤Й╨╕╨╣┬╗, ╤З╤В╨╛ ╨╕ ╤Б╨╡╤В╤М
 * ╤Д╨╕╨╗╨╕╨░╨╗╨╛╨▓, тАФ ╨┐╤А╨╕ ╤В╨╛╨╝ ╤З╤В╨╛ ╨╜╨╕ ╨╛╨┤╨╜╨╛╨│╨╛ ╤В╨░╨║╨╛╨│╨╛ ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨░ ╤Г ╨╜╨╡╨│╨╛ ╨╜╨╡╤В.
 *
 * ╨в╨╡╤Б╤В ╨┐╨╡╤З╨░╤В╨░╨╡╤В ╨╛╨▒╨░ ╤Б╨╛╤Б╤В╨░╨▓╨░ ╤Ж╨╡╨╗╨╕╨║╨╛╨╝: ╤Б╨╝╤Л╤Б╨╗ ╨┐╤А╨░╨▓╨║╨╕ ╨▓╨╕╨┤╨╡╨╜ ╤В╨╛╨╗╤М╨║╨╛ ╤Б╤А╨░╨▓╨╜╨╡╨╜╨╕╨╡╨╝
 * ╤Б╨┐╨╕╤Б╨║╨╛╨▓, ╨░ ╨╜╨╡ ╤Д╨░╨║╤В╨╛╨╝ ╨┐╤А╨╛╤Е╨╛╨╢╨┤╨╡╨╜╨╕╤П ╨┐╤А╨╛╨▓╨╡╤А╨║╨╕.
 *
 * ╨Э╨░╨╖╨▓╨░╨╜╨╕╤П ╨┐╤А╨╛╨▓╨╡╤А╨╛╨║ ╨┐╨╛-╤А╤Г╤Б╤Б╨║╨╕ ╨╜╨░╨╝╨╡╤А╨╡╨╜╨╜╨╛: ╨╛╨╜╨╕ ╤З╨╕╤В╨░╤О╤В╤Б╤П ╨║╨░╨║ ╤Г╤В╨▓╨╡╤А╨╢╨┤╨╡╨╜╨╕╤П ╨╛
 * ╨┐╤А╨╛╨┤╤Г╨║╤В╨╡, ╨░ ╨╜╨╡ ╨╛ ╨║╨╛╨┤╨╡.
 */

const roleFocusOrder: StaffRole[] = [
	"doctor",
	"administrator",
	"assistant",
	"manager",
	"owner",
];

/** ╨а╨░╨╖╨┤╨╡╨╗╤Л, ╨▒╨╡╨╖ ╨║╨╛╤В╨╛╤А╤Л╤Е ╨▓╤А╨░╤З ╨╜╨╡ ╨┐╤А╨╛╨▓╨╡╨┤╤С╤В ╨┐╤А╨╕╤С╨╝. ╨Ш╤Е ╤А╨╡╨╢╨╕╨╝ ╤Б╨║╤А╤Л╨▓╨░╤В╤М ╨╜╨╡ ╨▓╨┐╤А╨░╨▓╨╡. */
const clinicalViews = [
	"schedule",
	"patients",
	"imaging",
	"visit",
	"documents",
	"finance",
] as const;

const railFor = (mode: ClinicMode | null): string[] => {
	const seen = new Set<string>();
	for (const role of visibleStaffRoles(roleFocusOrder, mode)) {
		for (const view of getVisibleRailViews(role, mode)) seen.add(view);
	}
	return appViews.filter((view) => seen.has(view));
};

const named = (views: readonly string[]): string =>
	views.map((view) => viewLabels[view as (typeof appViews)[number]]).join(", ");

/*
 * ╨Т╨в╨Ю╨а╨Р╨п ╨б╨Ш╨б╨в╨Х╨Ь╨Р ╨Ь╨Ю╨Ф╨г╨Ы╨м╨Э╨Ю╨б╨в╨Ш тАФ ╨Я╨а╨Ш╨Ч╨Э╨Р╨Ъ╨Ш ╨Ь╨Ю╨Ф╨г╨Ы╨Х╨Щ.
 *
 * ╨б╨╛╤Б╤В╨░╨▓ ╤Н╨║╤А╨░╨╜╨░ ╤А╨╡╤И╨░╤О╤В ╨╜╨╡ ╤В╨╛╨╗╤М╨║╨╛ ╤А╨╡╨╢╨╕╨╝ ╨╕ ╤А╨╛╨╗╤М: ╤З╨░╤Б╤В╤М ╨▓╨║╨╗╨░╨┤╨╛╨║ ╨╜╨░╤Б╤В╤А╨╛╨╡╨║ ╨┐╤А╤П╤З╨╡╤В╤Б╤П ╨┐╨╛
 * ╨┐╤А╨╕╨╖╨╜╨░╨║╨░╨╝ ╨╕╨╖ `hooks/useWorkspaceProfile.ts` (`SettingsView.tsx:1201` ╤Б╤В╤А╨╛╨╕╤В
 * ╤Б╨┐╨╕╤Б╨╛╨║ ╨▓╨║╨╗╨░╨┤╨╛╨║, `:1512` тАФ ╤Б╨░╨╝╨╕ ╨┐╨░╨╜╨╡╨╗╨╕). ╨Я╨╛╤Н╤В╨╛╨╝╤Г ┬л╤З╤В╨╛ ╨▓╨╕╨┤╨╜╨╛ ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╨╝╤Г ╨▓╤А╨░╤З╤Г┬╗
 * ╨▒╨╡╨╖ ╨┐╤А╨╕╨╖╨╜╨░╨║╨╛╨▓ ╨╜╨╡ ╨┐╨╛╤Б╤З╨╕╤В╨░╤В╤М.
 *
 * ╨Ч╨╜╨░╤З╨╡╨╜╨╕╤П ╨╖╨┤╨╡╤Б╤М тАФ ╤Д╨╕╨║╤Б╤В╤Г╤А╨░, ╨░ ╨╜╨╡ ╨▓╤Л╨┤╤Г╨╝╨║╨░ ╨┐╤А╨╛ ╨┐╤А╨╛╨┤╤Г╨║╤В: `GET
 * /api/workspace/profile` (`apps/api/src/routes/workspaceProfile.ts:451`) ╨╛╤В╨┤╨░╤С╤В
 * ╨┐╤А╨╕╨╖╨╜╨░╨║╨╕ ╨║╨╛╨╜╤Б╤В╨░╨╜╤В╨╛╨╣, ╨▓╤Б╨╡ ╨▓╨║╨╗╤О╤З╤С╨╜╨╜╤Л╨╡, ╨╗╤О╨▒╨╛╨╣ ╨╛╤А╨│╨░╨╜╨╕╨╖╨░╤Ж╨╕╨╕. ╨Я╤А╨╛╨▓╨╡╤А╤П╨╡╤В╤Б╤П ╤А╨╛╨▓╨╜╨╛ ╨╛╨┤╨╜╨╛:
 * ╨║╨░╨║╨╕╨╡ ╨╕╨╖ ╨╜╨╕╤Е ╤Б╨╜╨╕╨╝╨░╨╡╤В ╤А╨╡╨╢╨╕╨╝. ╨в╨╕╨┐ ╨▓╨╖╤П╤В ╨╕╨╖ ╨╜╨░╤Б╤В╨╛╤П╤Й╨╡╨│╨╛ ╨╕╨╜╤В╨╡╤А╤Д╨╡╨╣╤Б╨░, ╨┐╨╛╤Н╤В╨╛╨╝╤Г
 * ╨┐╨╡╤А╨╡╨╕╨╝╨╡╨╜╨╛╨▓╨░╨╜╨╕╨╡ ╨┐╤А╨╕╨╖╨╜╨░╨║╨░ ╨╗╨╛╨╝╨░╨╡╤В ╤Д╨╕╨║╤Б╤В╤Г╤А╤Г, ╨░ ╨╜╨╡ ╨┐╤А╨╛╤Е╨╛╨┤╨╕╤В ╨╝╨╛╨╗╤З╨░.
 */
type ModuleFlagFixture = Pick<
	WorkspaceFeatureFlags,
	| "hasMarketingModule"
	| "hasPayrollModule"
	| "hasAnalyticsModule"
	| "hasInventoryModule"
	| "hasOrthodontics"
	| "hasDentalLab"
	| "hasPediatricMode"
	| "aiEnableTreatmentPlan"
	| "aiEnableRecommendations"
	| "aiEnableDocuments"
>;

const serverFlags: ModuleFlagFixture = {
	hasMarketingModule: true,
	hasPayrollModule: true,
	hasAnalyticsModule: true,
	hasInventoryModule: true,
	hasOrthodontics: true,
	hasDentalLab: true,
	hasPediatricMode: true,
	aiEnableTreatmentPlan: true,
	aiEnableRecommendations: true,
	aiEnableDocuments: true,
};

const flagKeys = Object.keys(serverFlags) as Array<keyof ModuleFlagFixture>;

/** ╨Ъ╨╗╨╕╨╜╨╕╤З╨╡╤Б╨║╨╕╨╡ ╨┐╤А╨╕╨╖╨╜╨░╨║╨╕: ╨╗╨╡╤З╨╡╨╜╨╕╨╡ ╤А╨╡╨╢╨╕╨╝╨╛╨╝ ╨╜╨╡ ╤Г╨┐╤А╨╛╤Й╨░╨╡╤В╤Б╤П, ╤Б╨╜╤П╤В╤М ╨╕╤Е ╨╛╨╜ ╨╜╨╡ ╨▓╨┐╤А╨░╨▓╨╡. */
const clinicalFlags: ReadonlyArray<keyof ModuleFlagFixture> = [
	"hasOrthodontics",
	"hasDentalLab",
	"hasPediatricMode",
	"aiEnableTreatmentPlan",
	"aiEnableRecommendations",
	"aiEnableDocuments",
];

/**
 * ╨Т╤Б╤С, ╤З╤В╨╛ ╨║╨╗╨╕╨╜╨╕╨║╨░ ╨┐╤А╨╕ ╤Н╤В╨╛╨╝ ╤А╨╡╨╢╨╕╨╝╨╡ ╨▓╨╕╨┤╨╕╤В, ╨╛╨┤╨╜╨╕╨╝ ╤Б╨┐╨╕╤Б╨║╨╛╨╝: ╤А╨░╨╖╨┤╨╡╨╗╤Л ╨╝╨╡╨╜╤О, ╤А╨╛╨╗╨╕ ╨▓
 * ╨┐╨╡╤А╨╡╨║╨╗╤О╤З╨░╤В╨╡╨╗╤П╤Е, ╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╨╕ ╨▓╨╜╤Г╤В╤А╨╕ ╤А╨░╨╖╨┤╨╡╨╗╨╛╨▓ ╨╕ ╨┐╤А╨╕╨╖╨╜╨░╨║╨╕ ╨╝╨╛╨┤╤Г╨╗╨╡╨╣. ╨б╤А╨░╨▓╨╜╨╡╨╜╨╕╨╡ ╨┤╨▓╤Г╤Е
 * ╤В╨░╨║╨╕╤Е ╤Б╨┐╨╕╤Б╨║╨╛╨▓ ╨╕ ╨╡╤Б╤В╤М ╤Б╨╝╤Л╤Б╨╗ ╤А╨╡╨╢╨╕╨╝╨░ тАФ ╨┐╨╛ ╨╜╨╡╨╝╤Г ╨▓╨╕╨┤╨╜╨╛, ╤З╤В╨╛ ╨╕╨╝╨╡╨╜╨╜╨╛ ╤Г╨▒╤А╨░╨╜╨╛.
 */
const moduleSurface = (mode: ClinicMode | null): string[] => {
	const flags = applyClinicModeToFlags(serverFlags, mode);
	return [
		...railFor(mode).map(
			(view) => `╨╝╨╡╨╜╤О: ${viewLabels[view as (typeof appViews)[number]]}`,
		),
		...visibleStaffRoles(roleFocusOrder, mode).map((role) => `╤А╨╛╨╗╤М: ${role}`),
		...clinicCapabilities(mode).map(
			(capability) => `╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╤М: ${capability}`,
		),
		...flagKeys.filter((key) => flags[key]).map((key) => `╨╝╨╛╨┤╤Г╨╗╤М: ${key}`),
	];
};

describe("╤Б╨╛╤Б╤В╨░╨▓ ╤А╨░╨▒╨╛╤З╨╡╨│╨╛ ╤Н╨║╤А╨░╨╜╨░ ╨┐╨╛ ╤А╨╡╨╢╨╕╨╝╤Г ╨║╨╗╨╕╨╜╨╕╨║╨╕", () => {
	it("╨▓╨╕╨┤╨╕╨╝╨╛╨╡ ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╨╝╤Г ╨▓╤А╨░╤З╤Г тАФ ╤Б╤В╤А╨╛╨│╨╛╨╡ ╨┐╨╛╨┤╨╝╨╜╨╛╨╢╨╡╤Б╤В╨▓╨╛ ╨▓╨╕╨┤╨╕╨╝╨╛╨│╨╛ ╤Б╨╡╤В╨╕, ╨╗╨╡╤З╨╡╨╜╨╕╨╡ ╤Ж╨╡╨╗╨╕╨║╨╛╨╝", () => {
		/*
		 * ╨У╨Ы╨Р╨Т╨Э╨Р╨п ╨Я╨а╨Ю╨Т╨Х╨а╨Ъ╨Р ╨а╨Х╨Ц╨Ш╨Ь╨Р, ╨Ш ╨Ю╨Э╨Р ╨Ч╨Ф╨Х╨б╨м ╨Ш╨Ь╨Х╨Э╨Э╨Ю ╨Я╨Х╨з╨Р╨в╨м╨о ╨б╨Я╨Ш╨б╨Ъ╨Ю╨Т. ╨Ч╨╡╨╗╤С╨╜╨░╤П
		 * ╨┐╤А╨╛╨▓╨╡╤А╨║╨░, ╨║╨╛╤В╨╛╤А╨░╤П ╨╜╨╕╤З╨╡╨│╨╛ ╨╜╨╡ ╨┐╨╡╤З╨░╤В╨░╨╡╤В, ╨╜╨╡ ╨┤╨╛╨║╨░╨╖╤Л╨▓╨░╨╡╤В ╨╜╨╕╤З╨╡╨│╨╛: ┬л╤А╨╡╨╢╨╕╨╝ ╨┐╤А╤П╤З╨╡╤В
		 * ╨╗╨╕╤И╨╜╨╡╨╡┬╗ тАФ ╤Н╤В╨╛ ╤Г╤В╨▓╨╡╤А╨╢╨┤╨╡╨╜╨╕╨╡ ╨╛ ╨┤╨▓╤Г╤Е ╤Б╨╛╤Б╤В╨░╨▓╨░╤Е ╤Н╨║╤А╨░╨╜╨░, ╨╕ ╤Г╨▓╨╕╨┤╨╡╤В╤М ╨╡╨│╨╛ ╨╝╨╛╨╢╨╜╨╛
		 * ╤В╨╛╨╗╤М╨║╨╛ ╨┐╨╛╨╗╨╛╨╢╨╕╨▓ ╨╕╤Е ╤А╤П╨┤╨╛╨╝.
		 *
		 * ╨Ф╨╡╤А╨╢╨╕╤В╤Б╤П ╤А╨╛╨▓╨╜╨╛ ╨┤╨▓╨╡ ╨▓╨╡╤Й╨╕, ╨╛╨▒╨╡ ╨┐╤А╨╛╨┤╤Г╨║╤В╨╛╨▓╤Л╨╡. ╨Я╨╡╤А╨▓╨╛╨╡: ╨╛╤В╨┤╨╡╨╗╤М╨╜╤Л╨╣ ╨▓╤А╨░╤З ╨╜╨╡ ╨▓╨╕╨┤╨╕╤В
		 * ╨Э╨Ш╨з╨Х╨У╨Ю, ╤З╨╡╨│╨╛ ╨╜╨╡ ╨▓╨╕╨┤╨╕╤В ╤Б╨╡╤В╤М, тАФ ╤Г╨┐╤А╨╛╤Й╨╡╨╜╨╕╨╡ ╨╜╨╡ ╨▓╨┐╤А╨░╨▓╨╡ ╨╛╤В╨╜╨╕╨╝╨░╤В╤М ╨┐╤А╨╛╨╕╨╖╨▓╨╛╨╗╤М╨╜╨╛╨╡.
		 * ╨Т╤В╨╛╤А╨╛╨╡: ╨╛╨╜ ╨▓╨╕╨┤╨╕╤В ╨Т╨б╨Б ╨╗╨╡╤З╨╡╨╜╨╕╨╡ тАФ ╤А╨░╨╖╨┤╨╡╨╗╤Л ╨┐╤А╨╕╤С╨╝╨░ ╨╕ ╨║╨╗╨╕╨╜╨╕╤З╨╡╤Б╨║╨╕╨╡ ╨┐╤А╨╕╨╖╨╜╨░╨║╨╕
		 * (╨╛╤А╤В╨╛╨┤╨╛╨╜╤В╨╕╤П, ╨╖╤Г╨▒╨╛╤В╨╡╤Е╨╜╨╕╤З╨╡╤Б╨║╨░╤П ╨╗╨░╨▒╨╛╤А╨░╤В╨╛╤А╨╕╤П, ╨┤╨╡╤В╤Б╨║╨╕╨╣ ╤А╨╡╨╢╨╕╨╝, ╨┐╨╛╨╝╨╛╤Й╤М ╨Ш╨Ш)
