function walk(node: unknown, visit: (node: AstNode) => void): void {
	if (Array.isArray(node)) {
		for (const item of node) walk(item, visit);
		return;
	}
	if (!isNode(node)) return;
	visit(node);
	for (const key of Object.keys(node)) {
		if (
			key === "loc" ||
			key === "leadingComments" ||
			key === "trailingComments"
		)
			continue;
		walk(node[key], visit);
	}
}

