/**
 * ╨б╤Г╨╝╨╝╨░ ╨╕╨╖ ╨┤╨╡╨╜╨╡╨╢╨╜╨╛╨╣ ╨║╨╛╨╗╨╛╨╜╨║╨╕ ╨▒╨░╨╖╤Л.
 *
 * /api/portal/me ╨╛╤В╨┤╨░╤С╤В ╤Б╤В╤А╨╛╨║╨╕ ╤В╨░╨▒╨╗╨╕╤Ж ╨║╨░╨║ ╨╡╤Б╤В╤М, ╨▒╨╡╨╖ ╨╝╨░╨┐╨┐╨╕╨╜╨│╨░ (routes/portal.ts:
 * `select()` ╨╕╨╖ treatment_plans ╨╕ patient_invoices). ╨Ф╨╡╨╜╨╡╨╢╨╜╤Л╨╡ ╨║╨╛╨╗╨╛╨╜╨║╨╕ ╤В╨░╨╝
 * ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜╤Л numeric ╨▒╨╡╨╖ mode "number", ╨░ ╤В╨░╨║╨╕╨╡ ╨╖╨╜╨░╤З╨╡╨╜╨╕╤П ╨┤╤А╨░╨╣╨▓╨╡╤А ╨╛╤В╨┤╨░╤С╤В
 * ╨б╨в╨а╨Ю╨Ъ╨Ю╨Щ тАФ ┬л6800.00┬╗. ╨Я╨╛╤Н╤В╨╛╨╝╤Г ╨╖╨┤╨╡╤Б╤М ╤А╨░╨╖╨▒╨╛╤А ╤Б╤В╤А╨╛╨║╨╕, ╨░ ╨╜╨╡ ╨┐╤А╨╕╨▓╨╡╨┤╨╡╨╜╨╕╨╡ ╤В╨╕╨┐╨░.
 *
 * null ╨╛╨╖╨╜╨░╤З╨░╨╡╤В ┬л╤Ж╨╡╨╜╤Л ╨╜╨╡╤В┬╗, ╨╕ ╤Н╤В╨╛ ╨╜╨╡ ╨╜╨╛╨╗╤М: ╨╜╨╛╨╗╤М ╨╜╨░ ╤Н╨║╤А╨░╨╜╨╡ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░ тАФ ╤Н╤В╨╛
 * ╤Г╤В╨▓╨╡╤А╨╢╨┤╨╡╨╜╨╕╨╡ ┬л╨╗╨╡╤З╨╡╨╜╨╕╨╡ ╨▒╨╡╤Б╨┐╨╗╨░╤В╨╜╨╛┬╗.
 */
function rubFromDbValue(value: unknown): number | null {
	if (typeof value === "number") return Number.isFinite(value) ? value : null;
	if (typeof value === "string" && value.trim() !== "") {
		const parsed = Number(value);
		return Number.isFinite(parsed) ? parsed : null;
	}
	return null;
}

/**
 * ╨б╤В╨╛╨╕╨╝╨╛╤Б╤В╤М ╨┐╨╗╨░╨╜╨░ ╨╗╨╡╤З╨╡╨╜╨╕╤П.
 *
 * ╨С╨л╨Ы╨Ю: `plan.totalAmount`. ╨в╨░╨║╨╛╨│╨╛ ╨┐╨╛╨╗╤П ╨╜╨╡╤В ╨╜╨╕ ╨▓ ╨╛╤В╨▓╨╡╤В╨╡ ╨┐╨╛╤А╤В╨░╨╗╨░, ╨╜╨╕ ╨▓ ╤В╨░╨▒╨╗╨╕╤Ж╨╡
 * treatment_plans: ╤В╨░╨╝ total_price_rub ╨╕ total_price (db/schema.ts), ╨┐╤А╨╕╤З╤С╨╝
 * ╨╖╨░╨┐╨╕╤Б╤Л╨▓╨░╨╡╤В ╨┐╨╗╨░╨╜ ╨╡╨┤╨╕╨╜╤Б╤В╨▓╨╡╨╜╨╜╤Л╨╣ ╨╝╨░╤А╤И╤А╤Г╤В (routes/odontogram.ts) ╨╕ ╤В╨╛╨╗╤М╨║╨╛ ╨▓
 * total_price тАФ ╨┐╨╛╤Н╤В╨╛╨╝╤Г ╨╡╨│╨╛ ╤З╨╕╤В╨░╨╡╨╝ ╨┐╨╡╤А╨▓╤Л╨╝. ╨Ш╨╖-╨╖╨░ ╨╜╨╡╤Б╤Г╤Й╨╡╤Б╤В╨▓╤Г╤О╤Й╨╡╨│╨╛ ╨┐╨╛╨╗╤П ┬л╨Ш╤В╨╛╨│╨╛
 * ╨┐╨╗╨░╨╜┬╗, ┬л╨Ю╨┐╨╗╨░╤З╨╡╨╜╨╛┬╗ ╨╕ ┬л╨Ю╤Б╤В╨░╤В╨╛╨║┬╗ ╨Т╨б╨Х╨У╨Ф╨Р ╨┐╨╡╤З╨░╤В╨░╨╗╨╕╤Б╤М ╨╜╤Г╨╗╤П╨╝╨╕, ╨╕ ╤В╨╛ ╨╢╨╡ ╤Б╨░╨╝╨╛╨╡
 * ╨┐╨╛╨║╨░╨╖╤Л╨▓╨░╨╗╨░ ╤Ж╨╡╨╜╨░ ╨║╨░╨╢╨┤╨╛╨│╨╛ ╨┐╨╗╨░╨╜╨░ ╨▓ ╤Б╨┐╨╕╤Б╨║╨╡.
 */
function planTotalRub(plan: unknown): number | null {
	const row = (plan ?? {}) as Record<string, unknown>;
	return rubFromDbValue(row.totalPrice) ?? rubFromDbValue(row.totalPriceRub);
}

