	const refs = useRef<(HTMLInputElement | null)[]>([]);

	const focus = useCallback((idx: number) => {
		refs.current[idx]?.focus();
	}, []);

	const handleKeyDown = useCallback(
		(e: React.KeyboardEvent<HTMLInputElement>, idx: number) => {
