		(e: React.ChangeEvent<HTMLInputElement>, idx: number) => {
			const raw = e.target.value.replace(/\D/g, "").slice(-1);
			if (!raw) return;

			setDigits((prev) => {
				const next = [...prev];
				next[idx] = raw;
				return next;
			});

