			// ╤В╨╛╨╢╨╡ ╨▓╤Л╨╖╤Л╨▓╨░╨╗ onComplete. ╨Т╨╝╨╡╤Б╤В╨╡ ╤Б ╤Н╤Д╤Д╨╡╨║╤В╨╛╨╝ ╨╜╨╕╨╢╨╡ ╨╕ ╨╛╨▒╤А╨░╨▒╨╛╤В╤З╨╕╨║╨╛╨╝
			// ╨▓╤Б╤В╨░╨▓╨║╨╕ ╨╛╨┤╨╕╨╜ ╨▓╨▓╨╛╨┤ ╨║╨╛╨┤╨░ ╨╛╤В╨┐╤А╨░╨▓╨╗╤П╨╗ ╨╜╨░ ╤Б╨╡╤А╨▓╨╡╤А ╨в╨а╨Ш ╨╖╨░╨┐╤А╨╛╤Б╨░ ╨┐╤А╨╛╨▓╨╡╤А╨║╨╕.
			// ╨Я╨╛╤А╤В╨░╨╗ ╨╛╨│╤А╨░╨╜╨╕╤З╨╡╨╜ 10 ╨╖╨░╨┐╤А╨╛╤Б╨░╨╝╨╕ ╨▓ ╨╝╨╕╨╜╤Г╤В╤Г ╨╜╨░ IP, ╨┐╨╛╤Н╤В╨╛╨╝╤Г ╨▓ ╨║╨╗╨╕╨╜╨╕╨║╨╡
			// ╨╖╨░ ╨╛╨┤╨╜╨╕╨╝ ╨▓╨╜╨╡╤И╨╜╨╕╨╝ ╨░╨┤╤А╨╡╤Б╨╛╨╝ ╤З╨╡╤В╨▓╤С╤А╤В╤Л╨╣ ╨┐╨░╤Ж╨╕╨╡╨╜╤В ╨┐╨╛╨╗╤Г╤З╨░╨╗ 429 ╨╜╨░
			// ╨┐╤А╨░╨▓╨╕╨╗╤М╨╜╤Л╨╣ ╨║╨╛╨┤ ╤Б ╨┐╨╡╤А╨▓╨╛╨╣ ╨┐╨╛╨┐╤Л╤В╨║╨╕. ╨Ю╤В╨┐╤А╨░╨▓╨║╤Г ╨╛╤Б╤В╨░╨▓╨╗╤П╨╡╨╝ ╤В╨╛╨╗╤М╨║╨╛ ╨▓ ╤Н╤Д╤Д╨╡╨║╤В╨╡.
		},
		[focus],
	);

	const handlePaste = useCallback(
		(e: React.ClipboardEvent, startIdx: number) => {
			e.preventDefault();
			const pasted = e.clipboardData
				.getData("text")
				.replace(/\D/g, "")
				.slice(0, OTP_LENGTH);
