import type React from "react";
import { useEffect, useRef, useState } from "react";

interface SignaturePadProps {
	onSign: (signatureBase64: string) => void;
	onCancel: () => void;
}

export function SignaturePad({ onSign, onCancel }: SignaturePadProps) {
	const canvasRef = useRef<HTMLCanvasElement>(null);
	const containerRef = useRef<HTMLDivElement>(null);
	const [isDrawing, setIsDrawing] = useState(false);
	const [isEmpty, setIsEmpty] = useState(true);

	// ╨С╨л╨Ы╨Ю: ╤Г ╤Н╤Д╤Д╨╡╨║╤В╨░ ╨▒╤Л╨╗╨░ ╨╖╨░╨▓╨╕╤Б╨╕╨╝╨╛╤Б╤В╤М [isEmpty]. ╨Я╨╡╤А╨▓╤Л╨╣ ╨╢╨╡ ╤И╤В╤А╨╕╤Е ╨╝╨╡╨╜╤П╨╗ isEmpty
	// ╨╜╨░ false, ╤Н╤Д╤Д╨╡╨║╤В ╨┐╨╡╤А╨╡╨╖╨░╨┐╤Г╤Б╨║╨░╨╗╤Б╤П, ╨┐╤А╨╕╤Б╨▓╨░╨╕╨▓╨░╨╜╨╕╨╡ canvas.width ╨б╨С╨а╨Р╨б╨л╨Т╨Р╨Ы╨Ю canvas
	// ╨╕ ╤Г╨╜╨╕╤З╤В╨╛╨╢╨░╨╗╨╛ ╨╜╨░╤З╨░╤В╤Г╤О ╨╗╨╕╨╜╨╕╤О тАФ ╨║╨╛╤А╨╛╤В╨║╨╛╨╡ ╨║╨░╤Б╨░╨╜╨╕╨╡ ╨╜╨╡ ╨╛╤Б╤В╨░╨▓╨╗╤П╨╗╨╛ ╤Б╨╗╨╡╨┤╨░ ╨▓╨╛╨╛╨▒╤Й╨╡.
	// ╨в╨╡╨┐╨╡╤А╤М ╤А╨░╨╖╨╝╨╡╤А ╨┐╨╡╤А╨╡╤Б╤З╨╕╤В╤Л╨▓╨░╨╡╤В╤Б╤П ╤В╨╛╨╗╤М╨║╨╛ ╨┐╤А╨╕ ╨╝╨╛╨╜╤В╨╕╤А╨╛╨▓╨░╨╜╨╕╨╕ ╨╕ ╨┐╤А╨╕ resize ╨╛╨║╨╜╨░,
	// ╨░ ╨░╨║╤В╤Г╨░╨╗╤М╨╜╨╛╨╡ ┬л╨┐╤Г╤Б╤В╨╛/╨╜╨╡ ╨┐╤Г╤Б╤В╨╛┬╗ ╤З╨╕╤В╨░╨╡╤В╤Б╤П ╨╕╨╖ ref, ╨░ ╨╜╨╡ ╨╕╨╖ ╨╖╨░╨▓╨╕╤Б╨╕╨╝╨╛╤Б╤В╨╡╨╣.
	const isEmptyRef = useRef(true);
	useEffect(() => {
		const handleResize = () => {
			if (containerRef.current && canvasRef.current) {
				const { width, height } = containerRef.current.getBoundingClientRect();
				const canvas = canvasRef.current;
				// Save old content
				const ctx = canvas.getContext("2d");
				let imgData: ImageData | null = null;
				if (!isEmptyRef.current && ctx) {
					try {
						imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
					} catch {
						// getImageData throws on tainted/zero-size canvas; preserve empty signature
					}
				}

				canvas.width = width;
				canvas.height = height;

				if (ctx) {
					ctx.lineCap = "round";
					ctx.lineJoin = "round";
					ctx.lineWidth = 3;
					ctx.strokeStyle = "#0f172a";

					// ╨С╨л╨Ы╨Ю: ╨┐╤А╨╕ ╨▓╨╛╤Б╤Б╤В╨░╨╜╨╛╨▓╨╗╨╡╨╜╨╕╨╕ ╤Б╨╛╨┤╨╡╤А╨╢╨╕╨╝╨╛╨│╨╛ ╨▒╨╡╨╗╤Л╨╣ ╤Д╨╛╨╜ ╨Э╨Х ╨┐╨╡╤А╨╡╨║╤А╨░╤И╨╕╨▓╨░╨╗╤Б╤П.
					// ╨Я╤А╨╕╤Б╨▓╨░╨╕╨▓╨░╨╜╨╕╨╡ canvas.width ╨╛╨▒╨╜╤Г╨╗╤П╨╡╤В ╤Е╨╛╨╗╤Б╤В ╨┤╨╛ ╨┐╤А╨╛╨╖╤А╨░╤З╨╜╨╛╨│╨╛, ╨╕ ╨▓
					// ╤Б╨╛╤Е╤А╨░╨╜╤С╨╜╨╜╨╛╨╝ PNG ╨┐╨╛╨┤╨┐╨╕╤Б╤М ╨╛╤Б╤В╨░╨▓╨░╨╗╨░╤Б╤М ╨╜╨░ ╨┐╤А╨╛╨╖╤А╨░╤З╨╜╨╛╨╝ ╤Д╨╛╨╜╨╡ тАФ ╨╜╨░
					// ╨┐╨╡╤З╨░╤В╨╜╨╛╨╝ ╤Б╨╛╨│╨╗╨░╤Б╨╕╨╕ ╨╛╨╜╨░ ╤А╨╡╨╜╨┤╨╡╤А╨╕╨╗╨░╤Б╤М ╨┐╨╛╨▓╨╡╤А╤Е ╤З╤С╤А╨╜╨╛╨│╨╛ ╨┐╤А╤П╨╝╨╛╤Г╨│╨╛╨╗╤М╨╜╨╕╨║╨░.
					// ╨д╨╛╨╜ ╨╖╨░╨╗╨╕╨▓╨░╨╡╨╝ ╨▓╤Б╨╡╨│╨┤╨░, ╤Б╨╛╨┤╨╡╤А╨╢╨╕╨╝╨╛╨╡ ╨╜╨░╨║╨╗╨░╨┤╤Л╨▓╨░╨╡╨╝ ╤Б╨▓╨╡╤А╤Е╤Г.
					ctx.fillStyle = "#ffffff";
					ctx.fillRect(0, 0, width, height);
					if (imgData) {
						// putImageData ╨╖╨░╤В╨╕╤А╨░╨╡╤В ╨┐╨╕╨║╤Б╨╡╨╗╨╕ ╤Ж╨╡╨╗╨╕╨║╨╛╨╝, ╨┐╨╛╤Н╤В╨╛╨╝╤Г ╨┐╨╡╤А╨╡╨╜╨╛╤Б╨╕╨╝
						// ╤Б╤В╨░╤А╨╛╨╡ ╨╕╨╖╨╛╨▒╤А╨░╨╢╨╡╨╜╨╕╨╡ ╤З╨╡╤А╨╡╨╖ ╨┐╤А╨╛╨╝╨╡╨╢╤Г╤В╨╛╤З╨╜╤Л╨╣ ╤Е╨╛╨╗╤Б╤В ╤Б ╨╜╨░╨╗╨╛╨╢╨╡╨╜╨╕╨╡╨╝.
						const restoreCanvas = document.createElement("canvas");
						restoreCanvas.width = imgData.width;
						restoreCanvas.height = imgData.height;
						const restoreCtx = restoreCanvas.getContext("2d");
						if (restoreCtx) {
							restoreCtx.putImageData(imgData, 0, 0);
							ctx.drawImage(restoreCanvas, 0, 0);
						}
					}
				}
			}
		};

		handleResize();
		window.addEventListener("resize", handleResize);
		return () => window.removeEventListener("resize", handleResize);
	}, []);

	// Clean up references and memory on unmount
	useEffect(() => {
		return () => {
			if (canvasRef.current) {
				const ctx = canvasRef.current.getContext("2d");
				if (ctx) {
					ctx.clearRect(
						0,
						0,
						canvasRef.current.width,
						canvasRef.current.height,
					);
				}
			}
		};
	}, []);

	const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
		const canvas = canvasRef.current;
		if (!canvas) return;
		setIsDrawing(true);
		setIsEmpty(false);
		isEmptyRef.current = false;

		const ctx = canvas.getContext("2d");
		if (!ctx) return;

		const pos = getPos(e, canvas);
		ctx.beginPath();
		ctx.moveTo(pos.x, pos.y);
	};

	const draw = (e: React.MouseEvent | React.TouchEvent) => {
		if (!isDrawing) return;
		const canvas = canvasRef.current;
		if (!canvas) return;

		const ctx = canvas.getContext("2d");
		if (!ctx) return;

		const pos = getPos(e, canvas);
		ctx.lineTo(pos.x, pos.y);
		ctx.stroke();
	};

	const stopDrawing = () => {
		if (!isDrawing) return;
		setIsDrawing(false);
		const canvas = canvasRef.current;
		if (canvas) {
			const ctx = canvas.getContext("2d");
			if (ctx) ctx.closePath();
		}
	};

	const getPos = (
		e: React.MouseEvent | React.TouchEvent,
		canvas: HTMLCanvasElement,
	) => {
		const rect = canvas.getBoundingClientRect();
		if ("touches" in e && e.touches.length > 0 && e.touches[0]) {
			const touch = e.touches[0];
			if (touch) {
				return {
					x: touch.clientX - rect.left,
					y: touch.clientY - rect.top,
				};
			}
		}
		return {
			x: (e as React.MouseEvent).clientX - rect.left,
			y: (e as React.MouseEvent).clientY - rect.top,
		};
	};

	const clear = () => {
		const canvas = canvasRef.current;
		if (!canvas) return;
		const ctx = canvas.getContext("2d");
		if (!ctx) return;
		ctx.fillStyle = "#ffffff";
		ctx.fillRect(0, 0, canvas.width, canvas.height);
		setIsEmpty(true);
		isEmptyRef.current = true;
	};

	const handleSave = () => {
		if (isEmpty || !canvasRef.current) return;
		// ╨Я╨╛╨┤╨┐╨╕╤Б╤М тАФ ╤З╨░╤Б╤В╤М ╤О╤А╨╕╨┤╨╕╤З╨╡╤Б╨║╨╛╨│╨╛ ╨┤╨╛╨║╤Г╨╝╨╡╨╜╤В╨░: ╨│╨░╤А╨░╨╜╤В╨╕╤А╤Г╨╡╨╝ ╨╜╨╡╨┐╤А╨╛╨╖╤А╨░╤З╨╜╤Л╨╣ ╨▒╨╡╨╗╤Л╨╣
		// ╤Д╨╛╨╜ ╨▓ ╨╕╤В╨╛╨│╨╛╨▓╨╛╨╝ ╨╕╨╖╨╛╨▒╤А╨░╨╢╨╡╨╜╨╕╨╕ ╨╜╨╡╨╖╨░╨▓╨╕╤Б╨╕╨╝╨╛ ╨╛╤В ╨╕╤Б╤В╨╛╤А╨╕╨╕ ╨╕╨╖╨╝╨╡╨╜╨╡╨╜╨╕╨╣ ╤А╨░╨╖╨╝╨╡╤А╨░.
		const source = canvasRef.current;
		const flattened = document.createElement("canvas");
		flattened.width = source.width;
		flattened.height = source.height;
		const flatCtx = flattened.getContext("2d");
		if (!flatCtx) {
			onSign(source.toDataURL("image/png"));
			return;
		}
		flatCtx.fillStyle = "#ffffff";
		flatCtx.fillRect(0, 0, flattened.width, flattened.height);
		flatCtx.drawImage(source, 0, 0);
		onSign(flattened.toDataURL("image/png"));
	};

	return (
		<>
			<div className="modal-header">
				<h2 className="modal-title">╨Я╨╛╨┤╨┐╨╕╤Б╤М ╨┤╨╛╨║╤Г╨╝╨╡╨╜╤В╨░</h2>
				<p className="modal-subtitle">
					╨Я╨╛╨╢╨░╨╗╤Г╨╣╤Б╤В╨░, ╤А╨░╤Б╨┐╨╕╤И╨╕╤В╨╡╤Б╤М ╨▓╨╜╤Г╤В╤А╨╕ ╨┐╨╛╨╗╤П ╨╜╨╕╨╢╨╡
				</p>
			</div>

			<div className="modal-body pb-0">
				<div
					ref={containerRef}
					className="relative w-full h-[320px] rounded-xl overflow-hidden border-2 border-dashed border-[var(--odontogram-border)] bg-[var(--paper-soft,#f8fafc)] transition-all hover:border-[var(--teal-500,#14b8a6)]"
					style={{ touchAction: "none" }}
				>
					<canvas
						ref={canvasRef}
						className="w-full h-full cursor-crosshair focus:outline-none focus:ring-2 focus:ring-[var(--focus-ring,rgba(20,184,166,0.5))]"
						tabIndex={0}
						role="img"
						aria-label="╨Я╨╛╨╗╨╡ ╨┤╨╗╤П ╨│╤А╨░╤Д╨╕╤З╨╡╤Б╨║╨╛╨╣ ╨┐╨╛╨┤╨┐╨╕╤Б╨╕ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░"
						onMouseDown={startDrawing}
						onMouseMove={draw}
						onMouseUp={stopDrawing}
						onMouseOut={stopDrawing}
						onBlur={stopDrawing}
						onTouchStart={startDrawing}
						onTouchMove={draw}
						onTouchEnd={stopDrawing}
						onTouchCancel={stopDrawing}
					/>
					{isEmpty && (
						<div className="absolute inset-0 pointer-events-none flex items-center justify-center text-[var(--odontogram-ink-muted,#94a3b8)] text-lg font-medium select-none">
