		assert.equal(journalDirectionLabel(undefined), "╨Э╨░╨┐╤А╨░╨▓╨╗╨╡╨╜╨╕╨╡ ╨╜╨╡ ╤Г╨║╨░╨╖╨░╨╜╨╛");
	});

	it("╤Г ╤Г╨┐╨░╨▓╤И╨╡╨╣ ╨╛╤В╨┐╤А╨░╨▓╨║╨╕ ╨┐╨╛╨┤╨┐╨╕╤Б╤М ╨│╨╛╨▓╨╛╤А╨╕╤В, ╤З╤В╨╛ ╨┤╨╡╨╗╨░╤В╤М ╨┤╨░╨╗╤М╤И╨╡", () => {
