		);
	});

	it("╤Г ╨┤╨╛╤Б╤В╨░╨▓╨╗╨╡╨╜╨╜╨╛╨│╨╛ ╤Б╨╛╨▒╤Л╤В╨╕╤П ╨╗╨╕╤И╨╜╨╡╨╣ ╤Б╤В╤А╨╛╨║╨╕ ╨╜╨╡╤В", () => {
