			implant.startWorld[1],
			implant.startWorld[2],
		),
		endWorld: vec3.fromValues(
			implant.endWorld[0],
			implant.endWorld[1],
			implant.endWorld[2],
		),
		boneDensity: { ...implant.boneDensity },
		distanceToNerve: implant.distanceToNerve,
	}));
}

