	>("idle");
	const [orderId, setOrderId] = useState<string | null>(null);
	const [errorMsg, setErrorMsg] = useState("");
	const { auth } = useAppLogicContext();

	/*
	 * ╨б╨Ш╨Э╨е╨а╨Ю╨Э╨Э╨л╨Щ ╨Ч╨Р╨Ь╨Ю╨Ъ, ╨Р ╨Э╨Х ╨д╨Ы╨Р╨У ╨б╨Ю╨б╨в╨Ю╨п╨Э╨Ш╨п. ╨б╨╛╤Б╤В╨╛╤П╨╜╨╕╨╡ ╨▓ React ╨╛╨▒╨╜╨╛╨▓╨╗╤П╨╡╤В╤Б╤П
	 * ╨░╤Б╨╕╨╜╤Е╤А╨╛╨╜╨╜╨╛: ╨╝╨╡╨╢╨┤╤Г ╤Й╨╡╨╗╤З╨║╨╛╨╝ ╨╕ ╨┐╨╡╤А╨╡╤А╨╕╤Б╨╛╨▓╨║╨╛╨╣ ╤Б `disabled` ╨╡╤Б╤В╤М ╨╛╨║╨╜╨╛, ╨║╤Г╨┤╨░
	 * ╨┐╤А╨╛╤Е╨╛╨┤╨╕╤В ╨▓╤В╨╛╤А╨╛╨╣ ╤Й╨╡╨╗╤З╨╛╨║. ╨Ф╨╗╤П ╨║╨╜╨╛╨┐╨║╨╕, ╨╖╨░╨┐╤Г╤Б╨║╨░╤О╤Й╨╡╨╣ ╤Б╨┐╨╕╤Б╨░╨╜╨╕╨╡ ╤Б ╨║╨░╤А╤В╤Л, ╤Н╤В╨╛╨│╨╛
	 * ╨╛╨║╨╜╨░ ╨┤╨╛╤Б╤В╨░╤В╨╛╤З╨╜╨╛, ╤З╤В╨╛╨▒╤Л ╤Г╨╣╤В╨╕ ╨┤╨▓╤Г╨╝ ╨╖╨░╨┐╤А╨╛╤Б╨░╨╝. `useRef` ╨╝╨╡╨╜╤П╨╡╤В╤Б╤П ╤Б╨╕╨╜╤Е╤А╨╛╨╜╨╜╨╛ ╨╕
	 * ╨╖╨░╨║╤А╤Л╨▓╨░╨╡╤В ╨╛╨║╨╜╨╛; `status` ╨╛╤Б╤В╨░╤С╤В╤Б╤П ╨┤╨╗╤П ╨╛╤В╤А╨╕╤Б╨╛╨▓╨║╨╕.
	 *
	 * ╨Ъ╨╗╨╕╨╡╨╜╤В╤Б╨║╨░╤П ╨╖╨░╤Й╨╕╤В╨░ тАФ ╤В╨╛╨╗╤М╨║╨╛ ╤Г╨┤╨╛╨▒╤Б╤В╨▓╨╛, ╨░ ╨╜╨╡ ╨│╨░╤А╨░╨╜╤В╨╕╤П. ╨Э╨░╤Б╤В╨╛╤П╤Й╨░╤П ╨╖╨░╤Й╨╕╤В╨░ ╨╛╤В
	 * ╨┐╨╛╨▓╤В╨╛╤А╨░ тАФ ╨║╨╗╤О╤З ╨╕╨┤╨╡╨╝╨┐╨╛╤В╨╡╨╜╤В╨╜╨╛╤Б╤В╨╕ ╨╜╨░ ╤Б╤В╨╛╤А╨╛╨╜╨╡ ╤Б╨╡╤А╨▓╨╡╤А╨░; ╨╖╨┤╨╡╤Б╤М ╨╡╨│╨╛ ╨╜╨╡╤В, ╨┐╨╛╤В╨╛╨╝╤Г
	 * ╤З╤В╨╛ ╨╜╨╡╤В ╨╕ ╤Б╨░╨╝╨╛╨╣ ╨╕╨╜╤В╨╡╨│╤А╨░╤Ж╨╕╨╕ (╤Б╨╝. ╨╜╨╕╨╢╨╡).
	 */
	const inFlight = useRef(false);

	const initiatePayment = useCallback(async () => {
		if (!patientId || !amountInRubles) return;
		if (inFlight.current) return;
		inFlight.current = true;
		setStatus("initiating");
		setErrorMsg("");
		try {
			/*
			 * ╨Р╨Ф╨а╨Х╨б ╨Ш╨б╨Я╨а╨Р╨Т╨Ы╨Х╨Э. ╨Ч╨┤╨╡╤Б╤М ╤Б╤В╨╛╤П╨╗ `/api/sberbank/initiate` тАФ ╨╝╨░╤А╤И╤А╤Г╤В╨░ ╤Б
			 * ╤В╨░╨║╨╕╨╝ ╨┐╤Г╤В╤С╨╝ ╨Э╨Х ╨б╨г╨й╨Х╨б╨в╨Т╨г╨Х╨в ╨▓╨╛ ╨▓╤Б╤С╨╝ API (╨┐╤А╨╛╨▓╨╡╤А╨╡╨╜╨╛ ╨┐╨╛╨╕╤Б╨║╨╛╨╝ ╨┐╨╛
			 * apps/api: ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜╤Л ╤В╨╛╨╗╤М╨║╨╛ `/api/sberbank/pay` ╨╕
			 * `/api/sberbank/status/:orderId`). ╨Ъ╨╜╨╛╨┐╨║╨░ ╨╛╨┐╨╗╨░╤В╤Л ╨▓╤Б╨╡╨│╨┤╨░ ╨┐╨╛╨╗╤Г╤З╨░╨╗╨░
			 * 404, ╨░ ╨║╨╜╨╛╨┐╨║╨░ ┬л╨Я╨╛╨▓╤В╨╛╤А╨╕╤В╤М┬╗ ╨┐╨╛╨▓╤В╨╛╤А╤П╨╗╨░ ╤В╨╛╤В ╨╢╨╡ 404.
			 *
			 * ╨Э╨░╤Б╤В╨╛╤П╤Й╨╕╨╣ ╨╝╨░╤А╤И╤А╤Г╤В ╨╛╤В╨▓╨╡╤З╨░╨╡╤В 501: ╨╕╨╜╤В╨╡╨│╤А╨░╤Ж╨╕╨╕ ╤Б╨╛ ╨б╨▒╨╡╤А╨▒╨░╨╜╨║╨╛╨╝ ╨▓ ╤Б╨▒╨╛╤А╨║╨╡
			 * ╨╜╨╡╤В (╨╜╨╕ ╨╛╨┤╨╜╨╛╨│╨╛ ╨╛╨▒╤А╨░╤Й╨╡╨╜╨╕╤П ╨║ API ╨▒╨░╨╜╨║╨░, ╨╜╨╕ ╨┐╨╡╤А╨╡╨╝╨╡╨╜╨╜╤Л╤Е ╨╛╨║╤А╤Г╨╢╨╡╨╜╨╕╤П, ╨╜╨╕
			 * ╤В╨╡╤Б╤В╨╛╨▓). ╨Я╤А╨╡╨╢╨┤╨╡ ╨╛╨╜ ╨╛╤В╨▓╨╡╤З╨░╨╗ ╨▓╤Л╨┤╤Г╨╝╨░╨╜╨╜╤Л╨╝ ╤Г╤Б╨┐╨╡╤Е╨╛╨╝ ╨╕ ╨┐╨╛╨╝╨╡╤З╨░╨╗ ╤Б╤З╤С╤В
			 * ╨╛╨┐╨╗╨░╤З╨╡╨╜╨╜╤Л╨╝ ╨▒╨╡╨╖ ╨┤╨╡╨╜╨╡╨│ тАФ ╤Н╤В╨╛ ╤Г╨▒╤А╨░╨╜╨╛. ╨Ч╨┤╨╡╤Б╤М ╨┐╨╛╨║╨░╨╖╤Л╨▓╨░╨╡╨╝ ╨▓╤А╨░╤З╤Г ╤З╨╡╤Б╤В╨╜╤Г╤О
			 * ╨┐╤А╨╕╤З╨╕╨╜╤Г ╨▓╨╝╨╡╤Б╤В╨╛ ╨▒╨╡╨╖╤Л╨╝╤П╨╜╨╜╨╛╨│╨╛ ╨╛╤В╨║╨░╨╖╨░.
			 */
			const res = await fetch("/api/sberbank/pay", {
				method: "POST",
				headers: {
					"Content-Type": "application/json",
					...(auth && typeof auth.denteClinicalReadHeaders === "function"
						? auth.denteClinicalReadHeaders()
						: {}),
				},
				body: JSON.stringify({
					amount: Math.round(amountInRubles * 100),
					patientId,
					description: `╨Ю╨┐╨╗╨░╤В╨░ ╨┐╨╛ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╤Г ${patientId}`,
				}),
			});
			const data = await res.json().catch(() => ({}));
			if (!res.ok) {
				throw new Error(
					data.message || data.error || "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╖╨░╨┐╤Г╤Б╤В╨╕╤В╤М ╨╛╨┐╨╗╨░╤В╤Г",
				);
			}

			setOrderId(data.orderId);
			setStatus("polling");
		} catch (err) {
			setStatus("error");
			setErrorMsg(
				err instanceof Error ? err.message : "╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╖╨░╨┐╤Г╤Б╤В╨╕╤В╤М ╤В╨╡╤А╨╝╨╕╨╜╨░╨╗",
			);
		} finally {
			// ╨б╨╜╨╕╨╝╨░╤В╤М ╨╖╨░╨╝╨╛╨║ ╨╛╨▒╤П╨╖╨░╤В╨╡╨╗╤М╨╜╨╛ ╨╕ ╨╜╨░ ╨╛╤В╨║╨░╨╖╨╡, ╨╕╨╜╨░╤З╨╡ ┬л╨Я╨╛╨▓╤В╨╛╤А╨╕╤В╤М┬╗ ╨╝╨╡╤А╤В╨▓╨░.
			inFlight.current = false;
		}
	}, [amountInRubles, patientId, auth]);

	useEffect(() => {
		if (isOpen && status === "idle") {
			initiatePayment();
		}
	}, [isOpen, status, initiatePayment]);

	useEffect(() => {
		if (!isOpen) {
			setStatus("idle");
			setOrderId(null);
			setErrorMsg("");
		}
	}, [isOpen]);

	useEffect(() => {
		if (status !== "polling" || !orderId) return;

		const interval = setInterval(async () => {
			try {
				/*
				 * ╨Ч╨Р╨У╨Ю╨Ы╨Ю╨Т╨Ъ╨Ш ╨Ч╨Ф╨Х╨б╨м ╨Ю╨С╨п╨Ч╨Р╨в╨Х╨Ы╨м╨Э╨л. ╨Ч╨░╨┐╤А╨╛╤Б ╤Г╤Е╨╛╨┤╨╕╨╗ ╨│╨╛╨╗╤Л╨╝, ╤В╨╛╨│╨┤╨░ ╨║╨░╨║
				 * ╨╝╨░╤А╤И╤А╤Г╤В ╨╖╨░╨║╤А╤Л╤В `requirePermission(..., "finance.write")`, ╨░
				 * ╤Б╨╛╤Б╨╡╨┤╨╜╨╕╨╣ ╨▓╤Л╨╖╨╛╨▓ ╨▓ ╤Н╤В╨╛╨╝ ╨╢╨╡ ╤Д╨░╨╣╨╗╨╡ ╨╖╨░╨│╨╛╨╗╨╛╨▓╨║╨╕ ╨┐╨╛╨┤╤Б╤В╨░╨▓╨╗╤П╨╡╤В. ╨Ш╤В╨╛╨│ тАФ
				 * 403 ╨╜╨░ ╨║╨░╨╢╨┤╨╛╨╝ ╨╛╨┐╤А╨╛╤Б╨╡, ╨╕ ╨╛╨║╨╜╨╛ ╨▓╨╕╤Б╨╡╨╗╨╛ ╨▓ ┬л╨╛╨╢╨╕╨┤╨░╨╜╨╕╨╕ ╨╛╨┐╨╗╨░╤В╤Л┬╗, ╨┐╨╛╨║╨░
				 * ╨▓╤А╨░╤З ╨╜╨╡ ╨╖╨░╨║╤А╨╛╨╡╤В ╨╡╨│╨╛ ╨▓╤А╤Г╤З╨╜╤Г╤О.
				 *
				 * `res.ok` ╨┐╤А╨╛╨▓╨╡╤А╤П╨╡╤В╤Б╤П ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛: ╨┐╤А╨╛╨╝╨╕╤Б `fetch` ╨╜╨░ 403 ╨╕ 500 ╨╜╨╡
				 * ╨╛╤В╨║╨╗╨╛╨╜╤П╨╡╤В╤Б╤П, ╨┐╨╛╤Н╤В╨╛╨╝╤Г ╨▒╨╡╨╖ ╨┐╤А╨╛╨▓╨╡╤А╨║╨╕ ╤В╨╡╨╗╨╛ ╨╛╤В╨║╨░╨╖╨░ ╤А╨░╨╖╨▒╨╕╤А╨░╨╗╨╛╤Б╤М ╨║╨░╨║
				 * ╤Б╨╛╤Б╤В╨╛╤П╨╜╨╕╨╡ ╨┐╨╗╨░╤В╨╡╨╢╨░, ╨░ `data.status` ╨╛╨║╨░╨╖╤Л╨▓╨░╨╗╤Б╤П undefined тАФ
				 * ╨╜╨╕ ╨▓╨╡╤В╨║╨░ ╤Г╤Б╨┐╨╡╤Е╨░, ╨╜╨╕ ╨▓╨╡╤В╨║╨░ ╨╛╤В╨║╨░╨╖╨░ ╨╜╨╡ ╤Б╤А╨░╨▒╨░╤В╤Л╨▓╨░╨╗╨╕, ╨╕ ╨╛╨┐╤А╨╛╤Б ╤И╤С╨╗
				 * ╨▓╨╡╤З╨╜╨╛.
				 */
				const res = await fetch(`/api/sberbank/status/${orderId}`, {
					headers:
						auth && typeof auth.denteClinicalReadHeaders === "function"
							? auth.denteClinicalReadHeaders()
							: {},
				});
				if (!res.ok) throw new Error(`HTTP ${res.status}`);
				const data = await res.json();
				if (data.status === "success") {
					setStatus("success");
					clearInterval(interval);
					showToast("╨Ю╨┐╨╗╨░╤В╨░ ╤Г╤Б╨┐╨╡╤И╨╜╨╛ ╨╖╨░╨▓╨╡╤А╤И╨╡╨╜╨░ ╨╜╨░ ╤В╨╡╤А╨╝╨╕╨╜╨░╨╗╨╡", "success");
					setTimeout(() => {
						onSuccess();
						onClose();
					}, 1500);
				} else if (data.status === "failed") {
					setStatus("error");
					setErrorMsg("╨Ю╨┐╨╗╨░╤В╨░ ╨╛╤В╨║╨╗╨╛╨╜╨╡╨╜╨░ ╤В╨╡╤А╨╝╨╕╨╜╨░╨╗╨╛╨╝");
					clearInterval(interval);
				}
			} catch (err) {
				showToast(
					actionFailureToast(
						"╨Ю╤И╨╕╨▒╨║╨░ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜╨╕╤П ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╕",
						(err as { status?: number })?.status ?? null,
					),
					"error",
				);
				console.error("Polling error", err);
				setStatus("error");
				setErrorMsg("╨Ю╤И╨╕╨▒╨║╨░ ╤Б╨▓╤П╨╖╨╕ ╤Б ╤В╨╡╤А╨╝╨╕╨╜╨░╨╗╨╛╨╝");
				clearInterval(interval);
			}
		}, 3000);

		return () => clearInterval(interval);
	}, [status, orderId, onSuccess, onClose, auth]);

	const handleClose = () => {
		if (
			status === "polling" &&
			!window.confirm("╨Ю╨┐╨╗╨░╤В╨░ ╨▓ ╨┐╤А╨╛╤Ж╨╡╤Б╤Б╨╡. ╨Т╤Л ╤Г╨▓╨╡╤А╨╡╨╜╤Л, ╤З╤В╨╛ ╤Е╨╛╤В╨╕╤В╨╡ ╨╖╨░╨║╤А╤Л╤В╤М?")
		) {
			return;
		}
		onClose();
	};

	if (!isOpen) return null;

	return (
		<div className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50">
			<div
				className="w-full max-w-md p-6 rounded-xl shadow-xl"
				style={{
					background: "var(--paper)",
					color: "var(--ink)",
				}}
			>
				<h2 style={{ marginTop: 0, marginBottom: "16px", fontSize: "20px" }}>
					╨Ю╨┐╨╗╨░╤В╨░ ╤З╨╡╤А╨╡╨╖ ╤В╨╡╤А╨╝╨╕╨╜╨░╨╗ ╨б╨▒╨╡╤А╨▒╨░╨╜╨║╨░
