/** ╨б╤З╤С╤В╤З╨╕╨║ ╨▓╨╝╨╡╤Б╤В╨╛ ╤Б╨╗╤Г╤З╨░╨╣╨╜╨╛╨│╨╛ uuid: ╨┐╤А╨╛╨▓╨╡╤А╤П╨╡╨╝ ╨╕╨╝╨╡╨╜╨╜╨╛ ┬л╤В╨╛╤В ╨╢╨╡ ╨║╨╗╤О╤З ╨╕╨╗╨╕ ╨╜╨╛╨▓╤Л╨╣┬╗. */
function countingIds(): () => string {
	let issued = 0;
	return () => {
		issued += 1;
		return `id-${issued}`;
	};
}

