function parseReportSections(
	report: string,
): Array<{ title: string; content: string; icon: string }> {
	if (!report) return [];
	const sections: Array<{ title: string; content: string; icon: string }> = [];
	const lines = report.split("\n");
	let currentSection: {
		title: string;
		content: string[];
		icon: string;
	} | null = null;

	for (const line of lines) {
		const isBoldHeading = /^\*\*(.+?):\*\*/.exec(line);
		if (isBoldHeading) {
			if (currentSection) {
				sections.push({
					title: currentSection.title,
					content: currentSection.content.join("\n").trim(),
					icon: currentSection.icon,
				});
			}
			const headingText = (isBoldHeading[1] || "").toLowerCase();
			const found = REPORT_SECTIONS.find((s) => headingText.includes(s.key));
			currentSection = {
				title: isBoldHeading[1] || "",
				icon: found?.icon || "ЁЯУМ",
				content: [line.replace(/^\*\*(.+?):\*\*/, "").trim()],
			};
		} else if (currentSection) {
			currentSection.content.push(line);
		}
	}
	if (currentSection) {
		sections.push({
			title: currentSection.title,
			content: currentSection.content.join("\n").trim(),
			icon: currentSection.icon,
		});
	}

	// Fallback if markdown has no **...: headers тАФ just show raw
	if (!sections.length) {
		sections.push({ title: "╨Ю╤В╤З╤С╤В", icon: "ЁЯУЛ", content: report });
	}

	return sections;
}

