function extractSummary(report: string): string | null {
	if (!report) return null;
	const conclusionMatch = report.match(
		/\*\*╨Ч╨░╨║╨╗╤О╤З╨╡╨╜╨╕╨╡:\*\*\s*\n([\s\S]*?)(?:\n\n|\*\*|$)/i,
	);
	if (conclusionMatch?.[1]) {
		return conclusionMatch[1]
			.replace(/^[-*\s]+/gm, "")
			.trim()
			.substring(0, 400);
	}
	return report.replace(/[*#`]/g, "").substring(0, 200).trim() || null;
}

