function inventoryItemFromServer(raw: unknown): InventoryItem {
	const row = (raw ?? {}) as Record<string, unknown>;
	const asNumber = (value: unknown) => {
		const parsed = typeof value === "number" ? value : Number(value);
		return Number.isFinite(parsed) ? parsed : 0;
	};
	/*
	 * ╨Э╨╡╨╛╨▒╤П╨╖╨░╤В╨╡╨╗╤М╨╜╤Л╨╡ ╨┐╨╛╨╗╤П ╤Б╨╛╨▒╨╕╤А╨░╤О╤В╤Б╤П ╤З╨╡╤А╨╡╨╖ ╨╗╨╛╨║╨░╨╗╤М╨╜╤Л╨╡ ╤Б╤В╤А╨╛╨║╨╕, ╨░ ╨╜╨╡ ╤З╨╡╤А╨╡╨╖ ╤Д╤Г╨╜╨║╤Ж╨╕╤О,
	 * ╨▓╨╛╨╖╨▓╤А╨░╤Й╨░╤О╤Й╤Г╤О `string | undefined`: ╨┐╤А╨╕ exactOptionalPropertyTypes ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╡
	 * `undefined` ╨╜╨╡ ╨┐╨╛╨┤╤Е╨╛╨┤╨╕╤В ╤Б╨▓╨╛╨╣╤Б╤В╨▓╤Г, ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜╨╜╨╛╨╝╤Г ╨║╨░╨║ `sku?: string`.
	 */
	const asText = (value: unknown) =>
		typeof value === "string" ? value.trim() : "";
	const sku = asText(row.sku);
	const barcode = asText(row.barcode);
	const lotNumber = asText(row.lotNumber);
	const expiration = asText(row.expirationDate);
	return {
		id: String(row.id ?? ""),
		name: typeof row.name === "string" ? row.name : "",
		stockQuantity: asNumber(row.stockQuantity),
		criticalThreshold: asNumber(row.criticalThreshold),
		// ╨ж╨╡╨╜╨░ ╨╛╤Б╤В╨░╤С╤В╤Б╤П ╤Б╤В╤А╨╛╨║╨╛╨╣: ╤В╨░╨║ ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜ ╤В╨╕╨┐, ╨╕ ╨╡╤С ╨▓╨╡╨╖╨┤╨╡ ╤З╨╕╤В╨░╤О╤В ╤З╨╡╤А╨╡╨╖ Number().
		unitCostRub:
			row.unitCostRub === null || row.unitCostRub === undefined
				? "0"
				: String(row.unitCostRub),
		updatedAt: typeof row.updatedAt === "string" ? row.updatedAt : "",
		...(sku ? { sku } : {}),
		...(barcode ? { barcode } : {}),
		...(lotNumber ? { lotNumber } : {}),
		/*
		 * ╨б╤А╨╛╨║ ╨│╨╛╨┤╨╜╨╛╤Б╤В╨╕ ╨┐╤А╨╕╨▓╨╛╨┤╨╕╨╝ ╨║ ┬л╨У╨У╨У╨У-╨Ь╨Ь-╨Ф╨Ф┬╗ ╨┐╨╛ ╨╝╨╡╤Б╤В╨╜╨╛╨╝╤Г ╨┤╨╜╤О.
		 *
		 * ╨Ъ╨╛╨╗╨╛╨╜╨║╨░ date ╤З╨░╤Б╨╛╨▓╨╛╨│╨╛ ╨┐╨╛╤П╤Б╨░ ╨╜╨╡ ╨╜╨╡╤Б╤С╤В, ╨╜╨╛ ╤Б╨╡╤А╨▓╨╡╤А ╨╛╤В╨┤╨░╤С╤В ╨╡╤С ╤Б╤В╤А╨╛╨║╨╛╨╣ ISO ╤Б
		 * ╨▓╤А╨╡╨╝╨╡╨╜╨╡╨╝; ╨▓╨╖╤П╤В╤М ╨┐╨╡╤А╨▓╤Л╨╡ ╨┤╨╡╤Б╤П╤В╤М ╨╖╨╜╨░╨║╨╛╨▓ ╨╜╨░╨┐╤А╤П╨╝╤Г╤О ╨╜╨╡╨╗╤М╨╖╤П тАФ ╨┐╤А╨╕ ╨╛╤В╤А╨╕╤Ж╨░╤В╨╡╨╗╤М╨╜╨╛╨╝
		 * ╤Б╨╝╨╡╤Й╨╡╨╜╨╕╨╕ ╤З╨░╤Б╨╛╨▓╨╛╨│╨╛ ╨┐╨╛╤П╤Б╨░ ╨┤╨░╤В╨░ ╤Г╨╡╤Е╨░╨╗╨░ ╨▒╤Л ╨╜╨░ ╤Б╤Г╤В╨║╨╕ ╨╜╨░╨╖╨░╨┤.
		 */
		...(expiration ? { expirationDate: localDayOf(expiration) } : {}),
	};
}

/** ╨Ъ╨░╨╗╨╡╨╜╨┤╨░╤А╨╜╤Л╨╣ ╨┤╨╡╨╜╤М ╨╖╨╜╨░╤З╨╡╨╜╨╕╤П ╨┤╨░╤В╤Л ╨┐╨╛ ╨╝╨╡╤Б╤В╨╜╨╛╨╝╤Г ╨▓╤А╨╡╨╝╨╡╨╜╨╕, ╨▓ ╨▓╨╕╨┤╨╡ ┬л╨У╨У╨У╨У-╨Ь╨Ь-╨Ф╨Ф┬╗. */
function localDayOf(value: string): string {
	if (/^\d{4}-\d{2}-\d{2}$/.test(value)) return value;
	const parsed = new Date(value);
	if (Number.isNaN(parsed.getTime())) return value.slice(0, 10);
	const month = String(parsed.getMonth() + 1).padStart(2, "0");
	const day = String(parsed.getDate()).padStart(2, "0");
	return `${parsed.getFullYear()}-${month}-${day}`;
}

