				);
				showToast("╨Ю╤И╨╕╨▒╨║╨░ ╨╖╨░╨│╤А╤Г╨╖╨║╨╕ ╨┐╤А╨░╨▓╨╕╨╗", "error");
			} finally {
				setIsLoadingRules(false);
			}
		},
		[organizationId, getHeaders],
	);

	useEffect(() => {
		if (activeSubTab === "rules" && selectedServiceId) {
			fetchRules(selectedServiceId);
		}
