		return "╨Т╤Л╨▒╤А╨░╨╜╨╜╤Л╨╣ ╨▓╤А╨░╤З ╨▒╨╛╨╗╤М╤И╨╡ ╨╜╨╡ ╤А╨░╨▒╨╛╤В╨░╨╡╤В ╨▓ ╨║╨╗╨╕╨╜╨╕╨║╨╡: ╨▓╤Л╨▒╨╡╤А╨╕╤В╨╡ ╨┤╤А╤Г╨│╨╛╨│╨╛ ╨▓ ╤Б╨┐╨╕╤Б╨║╨╡.";
	}
	if (code === "ChairNotFound") {
		return "╨Т╤Л╨▒╤А╨░╨╜╨╜╨╛╨╡ ╨║╤А╨╡╤Б╨╗╨╛ ╤Г╨┤╨░╨╗╨╡╨╜╨╛ ╨╕╨╖ ╨╜╨░╤Б╤В╤А╨╛╨╡╨║ ╨║╨╗╨╕╨╜╨╕╨║╨╕: ╨▓╤Л╨▒╨╡╤А╨╕╤В╨╡ ╨┤╤А╤Г╨│╨╛╨╡.";
