	const handleConvertSubmit = async (e: React.FormEvent) => {
		e.preventDefault();
		if (!convertingLeadId || isBooking) return;

		if (!visitMinutes) {
			showToast(
				"╨Э╨░╤Б╤В╤А╨╛╨╣╨║╨╕ ╨║╨╗╨╕╨╜╨╕╨║╨╕ ╨╡╤Й╤С ╨╜╨╡ ╨╖╨░╨│╤А╤Г╨╢╨╡╨╜╤Л: ╨┤╨╗╨╕╤В╨╡╨╗╤М╨╜╨╛╤Б╤В╤М ╨┐╤А╨╕╨╡╨╝╨░ ╨╜╨╡╨╕╨╖╨▓╨╡╤Б╤В╨╜╨░. ╨Ю╨▒╨╜╨╛╨▓╨╕╤В╨╡ ╤Б╤В╤А╨░╨╜╨╕╤Ж╤Г ╨╕ ╨┐╨╛╨▓╤В╨╛╤А╨╕╤В╨╡.",
