			if (!res.ok) {
				/*
				 * ╨С╨л╨Ы╨Ю: ╨╗╤О╨▒╨░╤П ╨╜╨╡╤Г╨┤╨░╤З╨░ ╨┐╤А╨╡╨▓╤А╨░╤Й╨░╨╗╨░╤Б╤М ╨▓ ┬л╨Ю╤И╨╕╨▒╨║╨░ ╨╖╨░╨┐╨╕╤Б╨╕ ╨╗╨╕╨┤╨░┬╗. ╨б╨╡╤А╨▓╨╡╤А ╨┐╤А╨╕
				 * ╤Н╤В╨╛╨╝ ╨╜╨░╨╖╤Л╨▓╨░╨╡╤В ╨┐╤А╨╕╤З╨╕╨╜╤Г тАФ ╨╖╨░╨╜╤П╤В╨╛╨╡ ╨║╤А╨╡╤Б╨╗╨╛, ╤Г╨▓╨╛╨╗╨╡╨╜╨╜╤Л╨╣ ╨▓╤А╨░╤З, ╤З╤Г╨╢╨░╤П
				 * ╨╛╤А╨│╨░╨╜╨╕╨╖╨░╤Ж╨╕╤П, тАФ ╨╕ ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А╤Г ╨╜╤Г╨╢╨╜╨░ ╨╕╨╝╨╡╨╜╨╜╨╛ ╨╛╨╜╨░, ╨╕╨╜╨░╤З╨╡ ╨╛╨╜ ╨╢╨╝╨╡╤В
				 * ╨║╨╜╨╛╨┐╨║╤Г ╨┐╨╛╨▓╤В╨╛╤А╨╜╨╛ ╨┤╨╛ ╨┐╨╛╤В╨╡╤А╨╕ ╨┤╨╛╨▓╨╡╤А╨╕╤П ╨║ ╤А╨░╨╖╨┤╨╡╨╗╤Г.
				 */
				showToast(await bookingFailureMessage(res), "error");
				return;
			}
			showToast(
				"╨Ю╨▒╤А╨░╤Й╨╡╨╜╨╕╨╡ ╨╖╨░╨┐╨╕╤Б╨░╨╜╨╛ ╨╜╨░ ╨┐╤А╨╕╨╡╨╝, ╨║╨░╤А╤В╨╛╤З╨║╨░ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░ ╤Б╨╛╨╖╨┤╨░╨╜╨░",
