				}}
			>
				╨Ч╨░╨│╤А╤Г╨╖╨║╨░ ╨║╨╛╨╜╨▓╨╡╨╣╨╡╤А╨░...
			</div>
		);
	}

	const boardBg = "var(--paper-strong)";
	const colBg = "var(--paper-soft)";
	const cardBg = "var(--paper)";
	const borderColor = "var(--line)";

	return (
