					<h2 className="m-0 text-2xl font-semibold text-[var(--ink)] flex items-center gap-3">
						╨Т╨╛╤А╨╛╨╜╨║╨░ ╨Я╨░╤Ж╨╕╨╡╨╜╤В╨╛╨▓
						<span className="text-[10px] font-bold px-2 py-0.5 bg-[var(--brand-500,#0f766e)] text-white rounded-full uppercase tracking-wider">
							PRO
						</span>
