/*
 * dictationToothUpdates.test.ts тАФ ╨┤╨╕╨║╤В╨╛╨▓╨║╨░ ╨╜╨░ ╤Б╤Е╨╡╨╝╤Г ╨╖╤Г╨▒╨░ ╨╜╨╡ ╨▓╤А╤С╤В ╨╛╨▒ ╤Г╤Б╨┐╨╡╤Е╨╡.
 *
 * ╨з╨в╨Ю ╨н╨в╨Ш ╨Я╨а╨Ю╨Т╨Х╨а╨Ъ╨Ш ╨Ф╨Х╨а╨Ц╨Р╨в. ╨Ю╨▒╤А╨░╨▒╨╛╤В╤З╨╕╨║ ╨┤╨╕╨║╤В╨╛╨▓╨║╨╕ ╨▓ OdontogramModule.tsx ╤З╨╕╤В╨░╨╗
 * `const { code, state } = data.payload`, ╨░ ╤Б╨╡╤А╨▓╨╡╤А ╨║╨╗╨░╨┤╤С╤В ╤Н╤В╨╕ ╨┐╨╛╨╗╤П ╨╜╨╡ ╨▓
 * `payload`, ╨░ ╨▓ ╨║╨░╨╢╨┤╤Г╤О ╤Б╤В╤А╨╛╨║╤Г `payload.toothUpdates`. ╨Я╨╛╤Н╤В╨╛╨╝╤Г ╨┐╨╡╤А╨▓╨░╤П ╨▓╨╡╤В╨║╨░
 * ╤Б╨╛╨▓╨┐╨░╨┤╨░╨╗╨░ ╨▓╤Б╨╡╨│╨┤╨░, `parseInt(undefined)` ╨┤╨░╨▓╨░╨╗ NaN, ╨╕ ╨▓╤А╨░╤З ╨▓╨╕╨┤╨╡╨╗ ╨╖╨╡╨╗╤С╨╜╨╛╨╡
 * ┬лAI: ╨Ч╤Г╨▒ undefined ╨╛╨▒╨╜╨╛╨▓╨╗╨╡╨╜ (undefined)┬╗ ╨┐╤А╨╕ ╨┐╤Г╤Б╤В╨╛╨╣ ╨║╨░╤А╤В╨╡.
 *
 * ╨Я╨╡╤А╨▓╨░╤П ╨┐╤А╨╛╨▓╨╡╤А╨║╨░ ╨╜╨╕╨╢╨╡ тАФ ╤А╨╛╨▓╨╜╨╛ ╨╜╨░ ╤Н╤В╨╛ ╤В╨╡╨╗╨╛ ╨╛╤В╨▓╨╡╤В╨░: ╨╛╨╜╨░ ╨╜╨╡ ╨┐╤А╨╛╤И╨╗╨░ ╨▒╤Л ╨╜╨╕ ╨╜╨░
 * ╨┐╤А╨╡╨╢╨╜╨╡╨╝ ╤З╤В╨╡╨╜╨╕╨╕ `payload.code`, ╨╜╨╕ ╨╜╨░ ╨╜╨╡╨┤╨╛╤Б╤В╨╕╨╢╨╕╨╝╨╛╨╣ ╨▓╨╡╤В╨║╨╡ `data.toothUpdates`.
 */

import assert from "node:assert/strict";
import test from "node:test";
import {
	dictationApplyMessage,
	dictationApplyPlanFromResponseBody,
} from "./dictationToothUpdates";

/** ╨Ю╤В╨▓╨╡╤В ╨╝╨╡╤Б╤В╨╜╨╛╨│╨╛ ╤А╨░╨╖╨▒╨╛╤А╨░ ╨┐╤А╨╕╤С╨╝╨░: localDictationParser.ts:404. */
function localVisitBody(toothUpdates: unknown): string {
	return JSON.stringify({
		action: "update_tooth",
		payload: { toothUpdates, emkUpdates: { diagnosis: "╨║╨░╤А╨╕╨╡╤Б" } },
	});
}

test("╤Б╤В╤А╨╛╨║╨╕ ╨╗╨╡╨╢╨░╤В ╨▓ payload.toothUpdates, ╨╕ ╨╛╨╜╨╕ ╨╜╨░╤Е╨╛╨┤╤П╤В╤Б╤П", () => {
	const plan = dictationApplyPlanFromResponseBody(
		localVisitBody([
			{ code: "26", state: "missing" },
			{ code: "36", state: "implant" },
			{ code: "16", state: "planned" },
		]),
	);
	assert.ok(plan !== null);
	assert.deepEqual(plan.applied, [
		{ toothNumber: 26, state: "Missing" },
		{ toothNumber: 36, state: "Implant" },
		{ toothNumber: 16, state: "Planned_Implant" },
	]);
	assert.deepEqual(plan.manual, []);
});

test("╤А╨░╨╖╨▒╨╛╤А ╤П╨╖╤Л╨║╨╛╨▓╨╛╨╣ ╨╝╨╛╨┤╨╡╨╗╤М╤О ╨║╨╗╨░╨┤╤С╤В ╤Б╤В╤А╨╛╨║╨╕ ╨▓ ╨║╨╛╤А╨╡╨╜╤М тАФ ╤В╨╛╨╢╨╡ ╨╜╨░╤Е╨╛╨┤╤П╤В╤Б╤П", () => {
	// dictationParser.ts:39 ╨╛╤В╨┤╨░╤С╤В toothUpdates ╨▒╨╡╨╖ ╨╛╨▒╤С╤А╤В╨║╨╕ payload.
	const plan = dictationApplyPlanFromResponseBody(
		JSON.stringify({
			toothUpdates: [{ code: "48", state: "missing" }],
			emkUpdates: {},
		}),
	);
	assert.ok(plan !== null);
	assert.deepEqual(plan.applied, [{ toothNumber: 48, state: "Missing" }]);
});

test("╨╜╨╡╨╛╨┤╨╜╨╛╨╖╨╜╨░╤З╨╜╨╛╨╡ ╤Б╨╗╨╛╨▓╨╛ ╨┤╨╕╨║╤В╨╛╨▓╨║╨╕ ╨╜╨╡ ╨┐╤А╨╡╨▓╤А╨░╤Й╨░╨╡╤В╤Б╤П ╨▓ ╨┤╨╕╨░╨│╨╜╨╛╨╖", () => {
	// "treatment" тАФ ╤Н╤В╨╛ ╨╕ ╨║╨░╤А╨╕╨╡╤Б, ╨╕ ╨┐╤Г╨╗╤М╨┐╨╕╤В, ╨╕ ╨┐╨╗╨╛╨╝╨▒╨░: ╤Б╨╡╤А╨▓╨╡╤А ╨┐╨╛╨▓╨╛╨┤ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╤П╨╡╤В.
	const plan = dictationApplyPlanFromResponseBody(
		localVisitBody([
			{ code: "26", state: "treatment" },
			{ code: "27", state: "done" },
			{ code: "28", state: "prosthetics" },
			{ code: "35", state: "watch" },
			{ code: "37", state: "calculus" },
		]),
	);
	assert.ok(plan !== null);
	assert.deepEqual(plan.applied, [], "╨┤╨╕╨░╨│╨╜╨╛╨╖ ╨╜╨░╤Г╨│╨░╨┤ ╤Б╤В╨░╨▓╨╕╤В╤М ╨╜╨╡╨╗╤М╨╖╤П");
	assert.equal(plan.manual.length, 5);
	assert.deepEqual(
		plan.manual.map((item) => item.toothNumber),
		[26, 27, 28, 35, 37],
	);
});

test("╨╜╨╡╤З╨╕╤В╨░╨╡╨╝╤Л╨╣ ╨╜╨╛╨╝╨╡╤А ╨╖╤Г╨▒╨░ ╨╜╨░╨╖╨▓╨░╨╜, ╨░ ╨╜╨╡ ╨▓╤Л╨▒╤А╨╛╤И╨╡╨╜ ╨╝╨╛╨╗╤З╨░", () => {
	const plan = dictationApplyPlanFromResponseBody(
		localVisitBody([
			{ code: "╨▓╨╡╤А╤Е╨╜╨╕╨╣", state: "missing" },
			{ code: "99", state: "missing" },
			{ code: "26╨░╨▒╨▓", state: "missing" },
			{ code: "36", state: "missing" },
		]),
	);
	assert.ok(plan !== null);
	// ╨С╨л╨Ы╨Ю: parseInt("╨▓╨╡╤А╤Е╨╜╨╕╨╣") = NaN ╤Г╤Е╨╛╨┤╨╕╨╗ ╨▓ ╤В╨╡╨╗╨╛ ╨╖╨░╨┐╤А╨╛╤Б╨░ ╨║╨░╨║ null, ╨░
	// parseInt("26╨░╨▒╨▓") ╨╝╨╛╨╗╤З╨░ ╨┐╤А╨╡╨▓╤А╨░╤Й╨░╨╗╤Б╤П ╨▓ ╨╖╤Г╨▒ 26.
	assert.deepEqual(plan.applied, [{ toothNumber: 36, state: "Missing" }]);
	assert.deepEqual(plan.unreadableCodes, ["╨▓╨╡╤А╤Е╨╜╨╕╨╣", "99", "26╨░╨▒╨▓"]);
});

test("╨╜╨╡╨╖╨╜╨░╨║╨╛╨╝╨╛╨╡ ╤Б╨╛╤Б╤В╨╛╤П╨╜╨╕╨╡ ╨╜╨╡ ╨┐╨╕╤И╨╡╤В╤Б╤П ╨▓ ╤Д╨╛╤А╨╝╤Г╨╗╤Г", () => {
	const plan = dictationApplyPlanFromResponseBody(
		localVisitBody([{ code: "26", state: "caries" }]),
