/* тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА 2. ╨Я╤Г╤Б╤В╨╛╨╣ ╨┐╤А╨░╨╣╤Б: ╨╜╨╕ ╤Ж╨╡╨╜╤Л, ╨╜╨╕ ╨▓╤Л╨┤╤Г╨╝╨░╨╜╨╜╨╛╨│╨╛ ╨╕╨┤╨╡╨╜╤В╨╕╤Д╨╕╨║╨░╤В╨╛╤А╨░ тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА */

test("╨┐╤Г╤Б╤В╨╛╨╣ ╨┐╤А╨░╨╣╤Б ╨╜╨╡ ╨┤╨░╤С╤В ╨╜╨╕ ╤Ж╨╡╨╜╤Л, ╨╜╨╕ ╨▓╤Л╨┤╤Г╨╝╨░╨╜╨╜╨╛╨│╨╛ ╨╕╨┤╨╡╨╜╤В╨╕╤Д╨╕╨║╨░╤В╨╛╤А╨░ ╤Г╤Б╨╗╤Г╨│╨╕", () => {
	const items = build(
		[tooth(11, "Caries"), tooth(21, "Crown"), tooth(16, "Planned_Implant")],
		EMPTY_CATALOG,
	);

	// ╨Ъ╨╗╨╕╨╜╨╕╤З╨╡╤Б╨║╨░╤П ╨╜╨░╤Е╨╛╨┤╨║╨░ ╨Э╨Х ╨┐╨╛╤В╨╡╤А╤П╨╜╨░: ╨╖╤Г╨▒ ╨╜╤Г╨╢╨┤╨░╨╡╤В╤Б╤П ╨▓ ╨╗╨╡╤З╨╡╨╜╨╕╨╕, ╨╕ ╤Н╤В╨╛ ╨▓╨╕╨┤╨╜╨╛.
	assert.equal(items.length, 4, "╨║╨░╤А╨╕╨╡╤Б, ╨║╨╛╤А╨╛╨╜╨║╨░, ╨╕╨╝╨┐╨╗╨░╨╜╤В╨░╤В ╨╕ ╤И╨░╨▒╨╗╨╛╨╜");
	assert.deepEqual(
		items.map((row) => row.toothNumber),
		[11, 21, 16, 16],
	);

	for (const row of items) {
		assert.equal(row.price, null, `╤Г ┬л${row.name}┬╗ ╨┐╨╛╤П╨▓╨╕╨╗╨░╤Б╤М ╤Ж╨╡╨╜╨░ ╨╕╨╖ ╨▓╨╛╨╖╨┤╤Г╤Е╨░`);
		assert.equal(row.priceId, null, `╤Г ┬л${row.name}┬╗ ╨┐╨╛╤П╨▓╨╕╨╗╤Б╤П ╨╕╨┤╨╡╨╜╤В╨╕╤Д╨╕╨║╨░╤В╨╛╤А`);
		assert.ok(row.issue, `╤Г ┬л${row.name}┬╗ ╨╜╨╡ ╨╜╨░╨╖╨▓╨░╨╜╨░ ╨┐╤А╨╕╤З╨╕╨╜╨░ ╨╛╤В╤Б╤Г╤В╤Б╤В╨▓╨╕╤П ╤Ж╨╡╨╜╤Л`);
		assert.equal(row.issue?.kind, "catalog_empty");
		// ╨Э╨╛╨╗╤М ╨▓╨╝╨╡╤Б╤В╨╛ ╨╜╨╡╨╕╨╖╨▓╨╡╤Б╤В╨╜╨╛╨╣ ╤Ж╨╡╨╜╤Л ╨╖╨░╨┐╤А╨╡╤Й╤С╨╜ ╤В╨░╨║ ╨╢╨╡, ╨║╨░╨║ ╨▓╤Л╨┤╤Г╨╝╨░╨╜╨╜╨░╤П ╤Б╤Г╨╝╨╝╨░.
		assert.notEqual(row.price as number | null, 0);
		assert.ok(
			!INVENTED_PRICES_RUB.includes(row.price as unknown as number),
			"╨▓╨╡╤А╨╜╤Г╨╗╨░╤Б╤М ╨╛╨┤╨╜╨░ ╨╕╨╖ ╨▓╨╛╤Б╤М╨╝╨╕ ╨▓╤Л╨┤╤Г╨╝╨░╨╜╨╜╤Л╤Е ╤Ж╨╡╨╜",
		);
		assert.ok(
			!INVENTED_SERVICE_IDS.includes(row.priceId as unknown as string),
			"╨▓╨╡╤А╨╜╤Г╨╗╤Б╤П ╨╛╨┤╨╕╨╜ ╨╕╨╖ ╨▓╤Л╨┤╤Г╨╝╨░╨╜╨╜╤Л╤Е ╨╕╨┤╨╡╨╜╤В╨╕╤Д╨╕╨║╨░╤В╨╛╤А╨╛╨▓ ╤Г╤Б╨╗╤Г╨│",
		);
	}

	// ╨Э╨░╨╖╨▓╨░╨╜╨╕╤П тАФ ╤З╨╡╨╗╨╛╨▓╨╡╤З╨╡╤Б╨║╨╕╨╡ ╤Б╨╗╨╛╨▓╨░ ╨╛ ╨╗╨╡╤З╨╡╨╜╨╕╨╕, ╨░ ╨╜╨╡ ╨┐╨╛╨╖╨╕╤Ж╨╕╨╕ ╨╜╨╡╤Б╤Г╤Й╨╡╤Б╤В╨▓╤Г╤О╤Й╨╡╨│╨╛ ╨┐╤А╨░╨╣╤Б╨░.
	assert.deepEqual(
		items.map((row) => row.name),
		[
			"╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░",
			"╨Ъ╨╛╤А╨╛╨╜╨║╨░",
			"╨г╤Б╤В╨░╨╜╨╛╨▓╨║╨░ ╨╕╨╝╨┐╨╗╨░╨╜╤В╨░╤В╨░",
			"╨е╨╕╤А╤Г╤А╨│╨╕╤З╨╡╤Б╨║╨╕╨╣ ╤И╨░╨▒╨╗╨╛╨╜",
		],
	);
});

test("╤З╨╡╨╗╨╛╨▓╨╡╨║╤Г ╨╜╨░╨╖╨▓╨░╨╜╨╛, ╨║╨░╨║╨╛╨│╨╛ ╨╗╨╡╤З╨╡╨╜╨╕╤П ╨╜╨╡ ╤Е╨▓╨░╤В╨░╨╡╤В ╨▓ ╨┐╤А╨░╨╣╤Б╨╡ ╨╕ ╨║╤Г╨┤╨░ ╨╕╨┤╤В╨╕", () => {
	const items = build([tooth(11, "Caries"), tooth(21, "Crown")], EMPTY_CATALOG);
	const messages = estimatorIssueMessages(items);

	// ╨Я╤Г╤Б╤В╨╛╨╣ ╨┐╤А╨░╨╣╤Б тАФ ╨╛╨┤╨╜╨░ ╨╜╨╛╨▓╨╛╤Б╤В╤М ╨╜╨░ ╨▓╨╡╤Б╤М ╨┐╨╗╨░╨╜, ╨░ ╨╜╨╡ ╨┐╨╛ ╤Д╤А╨░╨╖╨╡ ╨╜╨░ ╨║╨░╨╢╨┤╨╛╨╡ ╨╗╨╡╤З╨╡╨╜╨╕╨╡:
	// ╨╕╨╜╨░╤З╨╡ ╨▓ ╤Б╨┐╨╕╤Б╨║╨╡ ╨╛╨║╨░╨╖╤Л╨▓╨░╨╗╨╕╤Б╤М ╨┐╨╛╨▒╤Г╨║╨▓╨╡╨╜╨╜╨╛ ╨╛╨┤╨╕╨╜╨░╨║╨╛╨▓╤Л╨╡ ╤Б╤В╤А╨╛╨║╨╕ (╨╕ ╨╛╨┤╨╕╨╜╨░╨║╨╛╨▓╤Л╨╡
	// ╨║╨╗╤О╤З╨╕ React).
	assert.equal(messages.length, 1, messages.join(" | "));
	const [message] = messages;
	assert.ok(message);
	assert.equal(new Set(messages).size, messages.length);

	assert.match(message, /╨┐╤А╨░╨╣╤Б/i);
	assert.match(message, /╨Э╨░╤Б╤В╤А╨╛╨╣╨║╨╕ тЖТ ╨Я╤А╨░╨╣╤Б/);
	// ╨Э╨░╨╖╨▓╨░╨╜╨╛ ╨Ъ╨Р╨Ц╨Ф╨Ю╨Х ╨╗╨╡╤З╨╡╨╜╨╕╨╡, ╨║╨╛╤В╨╛╤А╨╛╨╝╤Г ╨╜╨╡ ╤Е╨▓╨░╤В╨░╨╡╤В ╤Ж╨╡╨╜╤Л, ╨╕ ╨╜╨░ ╨║╨░╨║╨╕╤Е ╨╖╤Г╨▒╨░╤Е.
	assert.match(message, /╨╗╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░ \(╨╖╤Г╨▒ 11\)/);
	assert.match(message, /╨║╨╛╤А╨╛╨╜╨║╨░ \(╨╖╤Г╨▒ 21\)/);
	assert.match(message, /╨╜╨╡ ╨╕╤Б╤З╨╡╨╖╨╗╨╛/);
	// ╨Э╨╕ ╨╛╨┤╨╜╨╛╨╣ ╨╗╨░╤В╨╕╨╜╤Б╨║╨╛╨╣ ╨▒╤Г╨║╨▓╤Л ╨╕ ╨╜╨╕ ╨╛╨┤╨╜╨╛╨│╨╛ ╤В╨╡╤Е╨╜╨╕╤З╨╡╤Б╨║╨╛╨│╨╛ ╤Б╨╗╨╛╨▓╨░.
	assert.doesNotMatch(message, /[A-Za-z]/);
});

