/* тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА 3. ╨Я╤А╨░╨╣╤Б ╨╡╤Б╤В╤М, ╨╜╨╛ ╨▓╤Л╨▒╨╛╤А ╨╖╨░ ╨▓╤А╨░╤З╨░ ╨┐╤А╨╛╨│╤А╨░╨╝╨╝╨░ ╨╜╨╡ ╨┤╨╡╨╗╨░╨╡╤В тФАтФАтФАтФАтФАтФАтФАтФАтФАтФАтФА */

test("╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╛ ╨┐╨╛╨┤╤Е╨╛╨┤╤П╤Й╨╕╤Е ╤Г╤Б╨╗╤Г╨│ тАФ ╤Ж╨╡╨╜╤Л ╨╜╨╡╤В, ╨╕ ╨▓╤Л╨▒╨╛╤А ╨╛╤Б╤В╨░╨▓╨╗╨╡╨╜ ╨▓╤А╨░╤З╤Г", () => {
	const catalog = [
		service("svc-1", "╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░ I ╨║╨╗╨░╤Б╤Б╨░", "therapy", 3000),
		service("svc-2", "╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░ II ╨║╨╗╨░╤Б╤Б╨░", "therapy", 4200),
	];
	const items = build([tooth(11, "Caries")], catalog);

	assert.equal(items[0]?.price, null);
	assert.equal(items[0]?.priceId, null);
	assert.equal(items[0]?.issue?.kind, "ambiguous");
	assert.equal(items[0]?.issue?.matches, 2);

	const [message] = estimatorIssueMessages(items);
	assert.ok(message);
	assert.match(message, /╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╛ ╨┐╨╛╨┤╤Е╨╛╨┤╤П╤Й╨╕╤Е ╤Г╤Б╨╗╤Г╨│ \(2\)/);
	// ╨Ъ╨╜╨╛╨┐╨║╨╕ ╨▓╤Л╨▒╨╛╤А╨░ ╤Г╤Б╨╗╤Г╨│╨╕ ╨▓ ╤Б╤В╤А╨╛╨║╨╡ ╤Б╨╝╨╡╤В╤Л ╨╜╨╡╤В тАФ ╨╛╨▒╨╡╤Й╨░╤В╤М ╨╡╤С ╨╜╨╡╨╗╤М╨╖╤П.
	assert.doesNotMatch(message, /╨▓╤Л╨▒╨╡╤А╨╕╤В╨╡ ╨╜╤Г╨╢╨╜╤Г╤О ╨▓ ╤Б╤В╤А╨╛╨║╨╡/i);
});

/*
 * ╨Ч╨┤╨╡╤Б╤М ╨╛╨╢╨╕╨┤╨░╨╜╨╕╨╡ ╨▒╤Л╨╗╨╛ "catalog_empty", ╨╕ ╨╛╨╜╨╛ ╤Г╤Б╤В╨░╤А╨╡╨╗╨╛.
 *
 * ╨Я╤А╨░╨╣╤Б ╨▓ ╤Н╤В╨╛╨╝ ╨╜╨░╨▒╨╛╤А╨╡ ╨Э╨Х ╨┐╤Г╤Б╤В: ╨▓ ╨╜╤С╨╝ ╨╗╨╡╨╢╨╕╤В ┬л╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░┬╗ ╨╖╨░ 2500 тВ╜, ╨┐╤А╨╛╤Б╤В╨╛
 * ╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨╜╨░╤П. ╨б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╨╡ ┬л╨┐╤А╨░╨╣╤Б ╨╡╤Й╤С ╨╜╨╡ ╨╖╨░╨┐╨╛╨╗╨╜╨╡╨╜┬╗ ╨╛╤В╨┐╤А╨░╨▓╨╕╨╗╨╛ ╨▒╤Л ╨▓╤А╨░╤З╨░ ╨┤╨╛╨▒╨░╨▓╨╗╤П╤В╤М
 * ╤Г╤Б╨╗╤Г╨│╤Г, ╨║╨╛╤В╨╛╤А╨░╤П ╤Г ╨╜╨╡╨│╨╛ ╤Г╨╢╨╡ ╨╡╤Б╤В╤М, ╨░ ┬л╤Г╤Б╨╗╤Г╨│╨░ ╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨░ ╨▓ ╨┐╤А╨░╨╣╤Б╨╡┬╗ ╨╛╤В╨┐╤А╨░╨▓╨╗╤П╨╡╤В
 * ╨▓╨║╨╗╤О╤З╨╕╤В╤М ╨╡╤С ╨╛╨▒╤А╨░╤В╨╜╨╛ тАФ ╨╛╨┤╨╜╨╛ ╨╜╨░╨╢╨░╤В╨╕╨╡ ╨▓╨╝╨╡╤Б╤В╨╛ ╨╖╨░╨▓╨╡╨┤╨╡╨╜╨╕╤П ╨┤╤Г╨▒╨╗╤П. ╨б╨░╨╝╨╛ ╨╜╨░╨╖╨▓╨░╨╜╨╕╨╡
 * ╤В╨╡╤Б╤В╨░ ╨│╨╛╨▓╨╛╤А╨╕╤В ┬л╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨╜╨░╤П ╤Г╤Б╨╗╤Г╨│╨░┬╗, ╤В╨╛ ╨╡╤Б╤В╤М ╤В╨╛╤З╨╜╤Л╨╣ ╤А╨░╨╖╨▒╨╛╤А ╤Б╨╛╨▓╨┐╨░╨┤╨░╨╡╤В ╤Б
 * ╨╖╨░╨╝╤Л╤Б╨╗╨╛╨╝ ╤В╨╡╤Б╤В╨░ ╨╗╤Г╤З╤И╨╡, ╤З╨╡╨╝ ╨╡╨│╨╛ ╨┐╤А╨╡╨╢╨╜╨╡╨╡ ╤Г╤В╨▓╨╡╤А╨╢╨┤╨╡╨╜╨╕╨╡.
 *
 * ╨Я╨╛╤Н╤В╨╛╨╝╤Г ╨╕╤Б╨┐╤А╨░╨▓╨╗╨╡╨╜ ╨в╨Х╨б╨в, ╨░ ╨╜╨╡ ╨║╨╛╨┤, ╨╕ ╤Г╤В╨▓╨╡╤А╨╢╨┤╨╡╨╜╨╕╨╡ ╨┐╤А╨╕ ╤Н╤В╨╛╨╝ ╤Г╤Б╨╕╨╗╨╡╨╜╨╛: ╨┐╤А╨╛╨▓╨╡╤А╤П╨╡╤В╤Б╤П
 * ╨╜╨╡ ╤В╨╛╨╗╤М╨║╨╛ ╨▓╨╕╨┤ ╨╛╤В╨║╨░╨╖╨░, ╨╜╨╛ ╨╕ ╤В╨╛, ╤З╤В╨╛ ╤З╨╡╨╗╨╛╨▓╨╡╨║╤Г ╨╜╨░╨╖╨▓╨░╨╜╨░ ╨║╨╛╨╜╨║╤А╨╡╤В╨╜╨░╤П ╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨╜╨░╤П
 * ╤Г╤Б╨╗╤Г╨│╨░. ╨Ю╤Б╨╗╨░╨▒╨╗╨╡╨╜╨╜╤Л╨╣ ╤В╨╡╤Б╤В ╨┐╤А╨╕╨╜╤П╨╗ ╨▒╤Л ╨╕ ╤А╨░╤Б╨┐╨╗╤Л╨▓╤З╨░╤В╤Л╨╣ ╨╛╤В╨▓╨╡╤В.
 */
test("╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨╜╨░╤П ╤Г╤Б╨╗╤Г╨│╨░ ╨╜╨╡ ╨┐╨╛╨┐╨░╨┤╨░╨╡╤В ╨▓ ╨┐╨╛╨┤╨┐╨╕╤Б╤Л╨▓╨░╨╡╨╝╤Г╤О ╤Б╨╝╨╡╤В╤Г", () => {
	const catalog = [
		service("svc-old", "╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░", "therapy", 2500, false),
	];
