	assert.equal(items[0]?.priceId, null);
	assert.equal(items[0]?.price, null);
	assert.equal(items[0]?.issue?.kind, "service_disabled");
	assert.equal(items[0]?.issue?.catalogTitle, "╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░");
	const message = estimatorIssueMessages(items)[0] ?? "";
	// ╨г╤Б╨╗╤Г╨│╨░ ╨╜╨░╨╖╨▓╨░╨╜╨░ ╨┐╨╛ ╨╕╨╝╨╡╨╜╨╕: ╨▒╨╡╨╖ ╤Н╤В╨╛╨│╨╛ ╤Б╨╛╨▓╨╡╤В ┬л╨▓╨║╨╗╤О╤З╨╕╤В╨╡ ╨╡╤С┬╗ ╨╜╨╡╨║╤Г╨┤╨░ ╨┐╤А╨╕╨╝╨╡╨╜╨╕╤В╤М.
	assert.match(message, /┬л╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░┬╗/);
	assert.match(message, /╨╛╨╜╨░ ╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨░/);
	// ╨б╨░╨╝╨╛╨╡ ╤Ж╨╡╨╜╨╜╨╛╨╡ ╨▓ ╤Н╤В╨╛╨╝ ╤В╨╡╨║╤Б╤В╨╡ тАФ ╨╖╨░╨┐╤А╨╡╤В ╨╜╨░ ╨┤╤Г╨▒╨╗╤М. ╨Я╤А╨╡╨╢╨╜╨╕╨╣ ╤Б╨╛╨▓╨╡╤В ┬л╨┤╨╛╨▒╨░╨▓╤М╤В╨╡
	// ╤Г╤Б╨╗╤Г╨│╤Г┬╗ ╨╖╨░╤Б╤В╨░╨▓╨╗╤П╨╗ ╨▓╤А╨░╤З╨░ ╨╖╨░╨▓╨╡╤Б╤В╨╕ ╨▓ ╨┐╤А╨░╨╣╤Б╨╡ ╨Т╨в╨Ю╨а╨г╨о ╤В╨░╨║╤Г╤О ╨╢╨╡.
	assert.match(message, /╨▓╤В╨╛╤А╤Г╤О ╤В╨░╨║╤Г╤О ╨╢╨╡ ╤Г╤Б╨╗╤Г╨│╤Г ╨╜╨╡ ╨╜╤Г╨╢╨╜╨╛/);
});

