test("╤Б╨╜╤П╤В╨░╤П ╨║╨╛╤А╨╖╨╕╨╜╨╛╨╣ ╤Б╤В╤А╨╛╨║╨░ ╨╜╨╡ ╨▓╨╛╨╖╨▓╤А╨░╤Й╨░╨╡╤В╤Б╤П ╨▓ ╤Б╨╝╨╡╤В╤Г ╨┐╤А╨╕ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╡╨╣ ╨╛╤В╨╝╨╡╤В╨║╨╡ ╨╖╤Г╨▒╨░", () => {
	/*
	 * ╨С╨л╨Ы╨Ю: ╨┐╨╛╨┤╨▒╨╛╤А ╤Б╨╝╨╛╤В╤А╨╕╤В ╤В╨╛╨╗╤М╨║╨╛ ╨╜╨░ ╨╖╤Г╨▒╨╜╤Г╤О ╤Д╨╛╤А╨╝╤Г╨╗╤Г, ╨░ ╤Д╨╛╤А╨╝╤Г╨╗╨░ ╨┐╤А╨╛ ╤Б╨╜╤П╤В╨╕╨╡ ╨╜╨╡
	 * ╨╖╨╜╨░╨╡╤В. ╨Т╤А╨░╤З ╤Б╨╜╨╕╨╝╨░╨╗ ╨║╨╛╤А╨╖╨╕╨╜╨╛╨╣ ╨║╨╛╤А╨╛╨╜╨║╤Г ╨╜╨░ 26, ╨╛╤В╨╝╨╡╤З╨░╨╗ ╨╗╤О╨▒╨╛╨╣ ╨┤╤А╤Г╨│╨╛╨╣ ╨╖╤Г╨▒ тАФ ╨╕
	 * ╨║╨╛╤А╨╛╨╜╨║╨░ ╤Б ╤Ж╨╡╨╜╨╛╨╣ ╨▓╨╛╨╖╨▓╤А╨░╤Й╨░╨╗╨░╤Б╤М ╨▓ ╨┤╨╛╨║╤Г╨╝╨╡╨╜╤В ╨┤╨╗╤П ╨┐╨╛╨┤╨┐╨╕╤Б╨╕ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨╛╨╝.
	 */
	const catalog = [
		service("svc-crown", "╨Ъ╨╛╤А╨╛╨╜╨║╨░ ╨║╨╡╤А╨░╨╝╨╕╤З╨╡╤Б╨║╨░╤П", "prosthetics", 25000),
		service("svc-caries", "╨Ы╨╡╤З╨╡╨╜╨╕╨╡ ╨║╨░╤А╨╕╨╡╤Б╨░", "therapy", 2000),
	];
	const teeth = [tooth(26, "Crown")];
	const first = reconcileAutoSuggestions([], teeth, catalog);
	assert.equal(first.items.length, 1);
	const removed = first.items[0];
	assert.ok(removed);

	// ╨Т╤А╨░╤З ╤Б╨╜╤П╨╗ ╤Б╤В╤А╨╛╨║╤Г ╨║╨╛╤А╨╖╨╕╨╜╨╛╨╣: ╨┐╨░╨╜╨╡╨╗╤М ╨╖╨░╨┐╨╛╨╝╨╕╨╜╨░╨╡╤В ╨║╨╗╤О╤З╨╕ ╤Б╨╜╤П╤В╨╕╤П.
	const dismissed = new Set(estimatorDismissalKeys(removed));
	assert.ok(dismissed.size > 0, "╤Б╨╜╤П╤В╨╕╨╡ ╨╛╨▒╤П╨╖╨░╨╜╨╛ ╤З╨╡╨╝-╤В╨╛ ╨╖╨░╨┐╨╛╨╝╨╕╨╜╨░╤В╤М╤Б╤П");

	// ╨в╨╛╤В ╨╢╨╡ ╨╖╤Г╨▒ ╨▓ ╤В╨╛╨╣ ╨╢╨╡ ╤Д╨╛╤А╨╝╤Г╨╗╨╡ ╨┐╨╗╤О╤Б ╨╛╤В╨╝╨╡╤В╨║╨░ ╨╜╨░ ╨┤╤А╤Г╨│╨╛╨╝ ╨╖╤Г╨▒╨╡.
	const afterAnotherTooth = reconcileAutoSuggestions(
		[],
		[tooth(26, "Crown"), tooth(11, "Caries")],
		catalog,
		dismissed,
	);
	assert.deepEqual(
