function measuredSingleChairClinic(): MeasuredInsight[] {
	return [
		...repeat(2, { nextBestAction: MISSING_DOCUMENTS, riskLevel: "watch" }),
		...repeat(1, { nextBestAction: CHECK_IMAGE, riskLevel: "high" }),
	];
}

