/**
 * ╨а╨░╨╖╨▒╨╛╤А ╤А╨░╤Б╨┐╨╕╤Б╨░╨╜╨╕╤П ╨┐╨╛ ╨┤╨╜╤П╨╝. ╨Я╤А╨╛╨▓╨╡╤А╤П╨╡╤В╤Б╤П ╤В╨╛, ╨╕╨╖-╨╖╨░ ╤З╨╡╨│╨╛ ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А ╨╛╤И╨╕╨▒╨░╨╗╤Б╤П:
 * ╨║╨░╨║╨╛╨╣ ╤Н╤В╨╛ ╨┤╨╡╨╜╤М, ╨│╨┤╨╡ ╨▓ ╨┤╨╜╨╡ ╤Б╨▓╨╛╨▒╨╛╨┤╨╜╨╛╨╡ ╨╛╨║╨╜╨╛ ╨╕ ╨│╨┤╨╡ ╨┤╨▓╨░ ╤З╨╡╨╗╨╛╨▓╨╡╨║╨░ ╤Б╨╕╨┤╤П╤В ╨╜╨░ ╨╛╨┤╨╜╨╛╨╝
 * ╨▓╤А╨░╤З╨╡ ╨╕╨╗╨╕ ╨▓ ╨╛╨┤╨╜╨╛╨╝ ╨║╤А╨╡╤Б╨╗╨╡.
 *
 * ╨з╨░╤Б╨╛╨▓╨╛╨╣ ╨┐╨╛╤П╤Б ╨╖╨░╨┤╨░╤С╤В╤Б╤П ╨┐╨╛╨┤╤Б╤В╨░╨▓╨╜╤Л╨╝ ╨┐╨╡╤А╨╡╨▓╨╛╨┤╤З╨╕╨║╨╛╨╝: ╨╜╨░╤Б╤В╨╛╤П╤Й╨╕╨╣ toDateTimeLocalValue
 * ╨╢╨╕╨▓╤С╤В ╨▓ AppHelpers ╨╕ ╤Г╨╢╨╡ ╨┐╤А╨╛╨▓╨╡╤А╨╡╨╜ ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛, ╨░ ╨╖╨┤╨╡╤Б╤М ╨▓╨░╨╢╨╜╨╛, ╤З╤В╨╛ ╨╝╨╛╨┤╤Г╨╗╤М ╨▒╨╡╤А╤С╤В
 * ╨┤╨╡╨╜╤М ╨Ш╨Ч ╨Э╨Х╨У╨Ю, ╨░ ╨╜╨╡ ╤Б╤З╨╕╤В╨░╨╡╤В ╤Б╤Г╤В╨║╨╕ ╨┐╨╛ UTC ╤Б╨▓╨╛╨╕╨╝╨╕ ╤А╤Г╨║╨░╨╝╨╕.
 */

/** ╨Я╨╡╤А╨╡╨▓╨╛╨┤╤З╨╕╨║ ┬л╨║╨░╨║ ╨▓ ╨б╨░╨╝╨░╤А╨╡┬╗: UTC+4, ╨▒╨╡╨╖ ╨┐╨╡╤А╨╡╤Е╨╛╨┤╨░ ╨╜╨░ ╨╗╨╡╤В╨╜╨╡╨╡ ╨▓╤А╨╡╨╝╤П. */
const samaraLocal = (iso: string) => {
	const shifted = new Date(Date.parse(iso) + 4 * 60 * 60_000);
	return shifted.toISOString().slice(0, 16);
};

const appointment = (
	patch: Partial<DayGroupingAppointment> = {},
): DayGroupingAppointment => ({
	id: "a1",
	startsAt: "2026-07-28T05:00:00.000Z",
	endsAt: "2026-07-28T05:30:00.000Z",
	status: "planned",
	doctorUserId: "doc-1",
	chairId: "chair-1",
	patientId: "pat-1",
	...patch,
});

/** ╨Ю╨▒╤А╨░╤Й╨╡╨╜╨╕╨╡ ╨║ ╤Н╨╗╨╡╨╝╨╡╨╜╤В╤Г ╤Б╨┐╨╕╤Б╨║╨░ ╤Б ╨┐╤А╨╛╨▓╨╡╤А╨║╨╛╨╣: ╤Г tsconfig ╨▓╨║╨╗╤О╤З╤С╨╜ noUncheckedIndexedAccess. */
function group(groups: ScheduleDayGroup[], index: number): ScheduleDayGroup {
	const found = groups[index];
	assert.ok(found, `╨╛╨╢╨╕╨┤╨░╨╗╨░╤Б╤М ╨│╤А╤Г╨┐╨┐╨░ ╨┤╨╜╤П тДЦ${index}, ╨░ ╨╡╤С ╨╜╨╡╤В`);
	return found;
}

function rowsOfKind<K extends ScheduleDayRow["kind"]>(
	target: ScheduleDayGroup,
	kind: K,
): Extract<ScheduleDayRow, { kind: K }>[] {
	return target.rows.filter(
		(row): row is Extract<ScheduleDayRow, { kind: K }> => row.kind === kind,
	);
}

function onlyRow<K extends ScheduleDayRow["kind"]>(
	target: ScheduleDayGroup,
	kind: K,
): Extract<ScheduleDayRow, { kind: K }> {
	const found = rowsOfKind(target, kind);
	assert.equal(
		found.length,
		1,
		`╨╛╨╢╨╕╨┤╨░╨╗╨░╤Б╤М ╤А╨╛╨▓╨╜╨╛ ╨╛╨┤╨╜╨░ ╤Б╤В╤А╨╛╨║╨░ ┬л${kind}┬╗, ╨╜╨░╨╣╨┤╨╡╨╜╨╛ ${found.length}`,
	);
	const first = found[0];
	assert.ok(first);
	return first;
}

