function SourcePanel(props: {
	busy: boolean;
	allowLlm: boolean;
	onAllowLlmChange: (value: boolean) => void;
	fileInputRef: React.MutableRefObject<HTMLInputElement | null>;
	onFile: (file: File) => void;
}) {
	const [dragging, setDragging] = useState(false);

	return (
		<div className="mw-panel">
			<section
				aria-label="╨Ч╨╛╨╜╨░ ╨╖╨░╨│╤А╤Г╨╖╨║╨╕ ╤Д╨░╨╣╨╗╨░"
				className={`mw-drop ${dragging ? "is-dragging" : ""}`}
				onDragOver={(event) => {
					event.preventDefault();
					setDragging(true);
				}}
				onDragLeave={() => setDragging(false)}
				onDrop={(event) => {
					event.preventDefault();
					setDragging(false);
					const file = event.dataTransfer.files.item(0);
					if (file) props.onFile(file);
				}}
			>
				<div className="mw-drop-icon" aria-hidden="true">
					тдУ
				</div>
				<p className="mw-drop-title">╨Я╨╡╤А╨╡╤В╨░╤Й╨╕╤В╨╡ ╤Д╨░╨╣╨╗ ╨▓╤Л╨│╤А╤Г╨╖╨║╨╕ ╤Б╤О╨┤╨░</p>
				<p className="mw-drop-hint">
					DBF (FoxPro, dBASE, ╤Б memo-╤Д╨░╨╣╨╗╨░╨╝╨╕), SQLite, CSV ╨╕ TSV ╨▓ ╨╗╤О╨▒╨╛╨╣
					╨║╨╛╨┤╨╕╤А╨╛╨▓╨║╨╡, XLSX, JSON, XML
				</p>
				<button
					type="button"
					className="mw-btn mw-btn-primary"
					disabled={props.busy}
					onClick={() => props.fileInputRef.current?.click()}
				>
					{props.busy ? "╨Ч╨░╨│╤А╤Г╨╖╨║╨░тАж" : "╨Т╤Л╨▒╤А╨░╤В╤М ╤Д╨░╨╣╨╗"}
				</button>
				<input
					ref={props.fileInputRef}
					type="file"
					className="mw-file-input"
					onChange={(event) => {
						const file = event.target.files?.item(0);
						if (file) props.onFile(file);
						event.target.value = "";
					}}
				/>
			</section>

			<label className="mw-toggle">
				<input
					type="checkbox"
					checked={props.allowLlm}
					onChange={(event) => props.onAllowLlmChange(event.target.checked)}
				/>
				<span>
					╨Я╤А╨╕╨▓╨╗╨╡╨║╨░╤В╤М ╨╜╨╡╨╣╤А╨╛╤Б╨╡╤В╤М ╨║ ╨╜╨╡╨╛╨┐╨╛╨╖╨╜╨░╨╜╨╜╤Л╨╝ ╨║╨╛╨╗╨╛╨╜╨║╨░╨╝
					<em className="mw-toggle-note">
						╨Ь╨╛╨┤╨╡╨╗╤М ╨┐╨╛╨╗╤Г╤З╨░╨╡╤В ╤В╨╛╨╗╤М╨║╨╛ ╤Б╤В╨░╤В╨╕╤Б╤В╨╕╨║╤Г ╨║╨╛╨╗╨╛╨╜╨║╨╕ ╨╕ ╨╝╨░╤Б╨║╨╕ ╨▓╨╕╨┤╨░ ┬л99.99.9999┬╗
						тАФ ╨╜╨╕ ╨╛╨┤╨╜╨╛╨│╨╛ ╨╖╨╜╨░╤З╨╡╨╜╨╕╤П ╨╕╨╖ ╨║╨░╤А╤В╨╛╤З╨╡╨║ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨╛╨▓ ╨╡╨╣ ╨╜╨╡ ╨┐╨╡╤А╨╡╨┤╨░╤С╤В╤Б╤П.
					</em>
				</span>
			</label>

			<div className="mw-note">
				<strong>╨Ч╨░╨║╤А╤Л╤В╤Л╨╡ ╤Д╨╛╤А╨╝╨░╤В╤Л.</strong> Firebird (IDENT), MS SQL (DentalPRO),
				Access ╨╕ 1╨б ╤З╨╕╤В╨░╤В╤М ╨╜╨░╨┐╤А╤П╨╝╤Г╤О ╨╜╨╡╨╗╤М╨╖╤П тАФ ╤Н╤В╨╛ ╤Б╤В╤А╨░╨╜╨╕╤З╨╜╤Л╨╡ ╤Д╨╛╤А╨╝╨░╤В╤Л, ╨┐╤А╨╕╨▓╤П╨╖╨░╨╜╨╜╤Л╨╡
				╨║ ╤Б╨▓╨╛╨╡╨╝╤Г ╤Б╨╡╤А╨▓╨╡╤А╤Г. ╨Э╨░╨╢╨╝╨╕╤В╨╡ ┬л╨Э╨░╨╣╤В╨╕ ╨▒╨░╨╖╤Л ╨╜╨░ ╤Б╨╡╤А╨▓╨╡╤А╨╡┬╗: ╨┤╨▓╨╕╨╢╨╛╨║ ╨╛╨┐╨╛╨╖╨╜╨░╨╡╤В ╨╕╤Е ╨╕
				╨┐╨╛╨┤╤Б╨║╨░╨╢╨╡╤В, ╤З╨╡╨╝ ╨╛╤В╨║╤А╤Л╤В╤М ╨╕ ╤З╤В╨╛ ╨▓╤Л╨│╤А╤Г╨╖╨╕╤В╤М.
			</div>
		</div>
	);
}

