	const typedPricelistAnalysis = pricelistAnalysis as any;

	/*
	 * ╨б╨╡╤Б╤Б╨╕╨╛╨╜╨╜╤Л╨╣ ╤Б╨╡╨║╤А╨╡╤В ╨┤╨╛╨╝╨╡╨╜╨░ ╨╜╨░╤Б╤В╤А╨╛╨╡╨║ + ╤В╨╛╨║╨╡╨╜╤Л ╨║╨░╨▒╨╕╨╜╨╡╤В╨░/╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨░.
	 * ╨а╨░╨╜╤М╤И╨╡ ╨╕╨╝╨┐╨╛╤А╤В ╤З╨╕╤В╨░╨╗ dente_clinic_token ╨╕╨╖ localStorage ╨╕ ╨║╨╗╨░╨╗ ╨╡╨│╨╛ ╨▓
	 * x-dente-admin-secret тАФ ╨▓ ╨║╨╗╨╕╨╜╨╕╨║╨╡ ╤Б DENTE_SETTINGS_ADMIN_SECRET ╤Н╤В╨╛ 403,
	 * ╨░ ╨╝╨░╤А╤И╤А╤Г╤В /api/settings/catalog-import ╨╜╨░ ╤Б╨╡╤А╨▓╨╡╤А╨╡ ╨╜╨╡ ╤Б╤Г╤Й╨╡╤Б╤В╨▓╤Г╨╡╤В.
	 */
	const accessHeaders = (
		mergedProps as { auth?: { settingsAccessHeaders?: SettingsAccessHeaders } }
	).auth?.settingsAccessHeaders;

	const filteredCatalog = useMemo(() => {
		let items = [...typedServiceCatalog];
		if (searchQuery.trim()) {
			const q = searchQuery.toLowerCase();
			items = items.filter(
				(s) =>
					s.title.toLowerCase().includes(q) ||
					s.code?.toLowerCase().includes(q),
			);
		}
		return items.sort((a, b) => a.title.localeCompare(b.title));
	}, [typedServiceCatalog, searchQuery]);

	const groupedCatalog = useMemo(() => {
		const groups: Record<string, any[]> = {};
		filteredCatalog.forEach((item) => {
			const cat = item.category || "other";
			if (!groups[cat]) groups[cat] = [];
			groups[cat].push(item);
		});
		return groups;
	}, [filteredCatalog]);

	const handleImportCatalog = async () => {
		if (!typedPricelistAnalysis?.items) return;
		setIsImporting(true);
		setImportResult(null);

		const validItems = typedPricelistAnalysis.items.filter(
			(item: any) => item.priceRub !== null,
		);
		if (validItems.length === 0) {
			setImportResult({ error: "╨Э╨╡╤В ╨┐╨╛╨╖╨╕╤Ж╨╕╨╣ ╤Б ╤Ж╨╡╨╜╨╛╨╣ ╨┤╨╗╤П ╨╕╨╝╨┐╨╛╤А╤В╨░" });
			setIsImporting(false);
			return;
		}

		/*
		 * Bulk-╨╝╨░╤А╤И╤А╤Г╤В╨░ ╨╜╨╡╤В: ╨╜╨░ ╤Б╨╡╤А╨▓╨╡╤А╨╡ ╤В╨╛╨╗╤М╨║╨╛ POST /api/settings/catalog
		 * (╨╛╨┤╨╜╨░ ╤Г╤Б╨╗╤Г╨│╨░). ╨Ш╨╝╨┐╨╛╤А╤В ╨╕╨┤╤С╤В ╨┐╨╛ ╨╛╨┤╨╜╨╛╨╣ ╨┐╨╛╨╖╨╕╤Ж╨╕╨╕ ╤Б ╤В╨╡╨╝╨╕ ╨╢╨╡ ╨╖╨░╨│╨╛╨╗╨╛╨▓╨║╨░╨╝╨╕,
		 * ╤З╤В╨╛ createServiceCatalogItem тАФ settingsAccessHeaders / staffMutationHeaders,
		 * ╨▒╨╡╨╖ ╤А╤Г╤З╨╜╨╛╨│╨╛ localStorage.getItem("dente_clinic_token").
		 */
		const headers = staffMutationHeaders(accessHeaders);
		let imported = 0;
		const failures: string[] = [];

		try {
			for (const item of validItems) {
				const payload = {
					title: String(item.title || "").trim(),
					code: item.code ? String(item.code) : undefined,
					category: item.category || "other",
					specialty: item.specialty || "therapist",
					basePriceRub: item.priceRub,
					durationMinutes:
						typeof item.durationMinutes === "number"
							? item.durationMinutes
							: 30,
					taxDeductible: item.taxDeductible !== false,
					active: true,
				};
				if (!payload.title) {
					failures.push("(╨▒╨╡╨╖ ╨╜╨░╨╖╨▓╨░╨╜╨╕╤П)");
					continue;
				}
				try {
					const res = await fetch("/api/settings/catalog", {
						method: "POST",
						headers,
						body: JSON.stringify(payload),
					});
					const raw = await res.text();
					if (!res.ok) {
						let message = `HTTP ${res.status}`;
						try {
							const parsed = JSON.parse(raw) as { message?: string };
							if (parsed.message) message = parsed.message;
						} catch {
							/* ╤В╨╡╨╗╨╛ ╨╜╨╡ JSON тАФ ╨╛╤Б╤В╨░╨▓╨╗╤П╨╡╨╝ ╨║╨╛╨┤ */
						}
						failures.push(`${payload.title}: ${message}`);
						continue;
					}
					imported += 1;
				} catch (err: unknown) {
					const message =
						err instanceof Error ? err.message : "╤Б╨╡╤В╤М ╨╜╨╡╨┤╨╛╤Б╤В╤Г╨┐╨╜╨░";
					failures.push(`${payload.title}: ${message}`);
				}
			}

			if (imported === 0) {
				setImportResult({
					error:
						failures[0] ||
						"╨Э╨╕ ╨╛╨┤╨╜╨░ ╨┐╨╛╨╖╨╕╤Ж╨╕╤П ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╨░. ╨Я╤А╨╛╨▓╨╡╤А╤М╤В╨╡ ╤Б╨╡╨║╤А╨╡╤В ╨╜╨░╤Б╤В╤А╨╛╨╡╨║.",
				});
				return;
			}

			if (failures.length > 0) {
				setImportResult({
					count: imported,
					error: `╨б╨╛╤Е╤А╨░╨╜╨╡╨╜╨╛ ${imported}, ╤Б ╨╛╤И╨╕╨▒╨║╨╛╨╣ ${failures.length}: ${failures[0]}`,
				});
			} else {
				setImportResult({ count: imported });
			}
			if (failures.length === 0) {
				setTimeout(() => {
					window.location.reload();
				}, 2000);
			}
		} catch (err: unknown) {
			const message = err instanceof Error ? err.message : "╨Ю╤И╨╕╨▒╨║╨░ ╨╕╨╝╨┐╨╛╤А╤В╨░";
			setImportResult({ error: message });
		} finally {
			setIsImporting(false);
		}
	};

	const handleSaveService = async (e: React.FormEvent) => {
		e.preventDefault();
		if (!createServiceCatalogItem || !updateServiceCatalogItem) {
			mergedProps.setError?.("API ╨╜╨╡╨┤╨╛╤Б╤В╤Г╨┐╨╜╨╛");
			return;
		}
		/*
		   ╨а╨░╨╖╨▒╨╛╤А ╤Ж╨╡╨╜╤Л тАФ ╨╛╨▒╤Й╨╡╨╣ normalizeRubAmountInput, ╤В╨╛╨╣ ╨╢╨╡, ╤З╤В╨╛ ╨▓ ╨║╨░╤Б╤Б╨╡, ╨▓
		   ╨╖╨░╨║╨░╨╖╨░╤Е ╨Ч╨в╨Ы ╨╕ ╨▓ ╨┐╨╗╨░╨╜╨╡ ╨╗╨╡╤З╨╡╨╜╨╕╤П. ╨Ю╨╜╨░ ╨┐╨╛╨╜╨╕╨╝╨░╨╡╤В ╨╖╨░╨┐╤П╤В╤Г╤О ╨╕ ╤А╨░╨╖╨┤╨╡╨╗╨╕╤В╨╡╨╗╨╕
		   ╤А╨░╨╖╤А╤П╨┤╨╛╨▓ ╨╕ ╨╛╤В╨║╨░╨╖╤Л╨▓╨░╨╡╤В ╨╜╨░ ╤В╤А╤С╤Е ╨╖╨╜╨░╨║╨░╤Е ╨┐╨╛╤Б╨╗╨╡ ╨╖╨░╨┐╤П╤В╨╛╨╣, ╨░ ╨╜╨╡ ╨╛╨║╤А╤Г╨│╨╗╤П╨╡╤В ╨╖╨░
		   ╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╤В╨╡╨╗╤П. ╨Э╨╡╨┐╨╛╨╜╤П╤В╨╜╨░╤П ╤Ж╨╡╨╜╨░ ╨▒╨╛╨╗╤М╤И╨╡ ╨╜╨╡ ╨┐╤А╨╡╨▓╤А╨░╤Й╨░╨╡╤В╤Б╤П ╨▓ ╨╜╨╛╨╗╤М ╨╝╨╛╨╗╤З╨░:
		   ╤Г╤Б╨╗╤Г╨│╨░ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╤П╨╡╤В╤Б╤П, ╨░ ╨┐╨╛╨╗╨╡ ╨│╨╛╨▓╨╛╤А╨╕╤В, ╤З╤В╨╛ ╨┐╨╛╨┐╤А╨░╨▓╨╕╤В╤М.

		   ╨Э╨╛╨╗╤М ╨┤╨╛╨┐╤Г╤Й╨╡╨╜: ╤Б╨╡╤А╨▓╨╡╤А╨╜╨░╤П ╤Б╤Е╨╡╨╝╨░ basePriceRub тАФ nonNegativeMoneyRubSchema,
		   ╨▒╨╡╤Б╨┐╨╗╨░╤В╨╜╨░╤П ╨┐╨╛╨╖╨╕╤Ж╨╕╤П ╨▓ ╨║╨░╤В╨░╨╗╨╛╨│╨╡ ╨╖╨░╨║╨╛╨╜╨╜╨░. ╨Ч╨░╨┐╤А╨╡╤Й╨╡╨╜╨╛ ╨┤╤А╤Г╨│╨╛╨╡ тАФ ╨Э╨Х╨п╨Т╨Э╨л╨Щ ╨╜╨╛╨╗╤М,
		   ╨║╨╛╤В╨╛╤А╨╛╨│╨╛ ╨╜╨╕╨║╤В╨╛ ╨╜╨╡ ╨▓╨▓╨╛╨┤╨╕╨╗.
		*/
		const basePriceRub = normalizeRubAmountInput(priceRubInput);
		if (basePriceRub === null) {
			setPriceProblem(
				priceRubInput.trim()
					? "╨ж╨╡╨╜╨░ ╨╜╨╡╨┐╨╛╨╜╤П╤В╨╜╨░. ╨Т╨┐╨╕╤И╨╕╤В╨╡ ╤Б╤Г╨╝╨╝╤Г ╤Ж╨╕╤Д╤А╨░╨╝╨╕, ╨║╨╛╨┐╨╡╨╣╨║╨╕ ╨┐╨╛╤Б╨╗╨╡ ╨╖╨░╨┐╤П╤В╨╛╨╣: 1500 ╨╕╨╗╨╕ 1500,50."
					: "╨г╨║╨░╨╢╨╕╤В╨╡ ╤Ж╨╡╨╜╤Г ╤Г╤Б╨╗╤Г╨│╨╕: ╨╜╨░╨┐╤А╨╕╨╝╨╡╤А 1500 ╨╕╨╗╨╕ 1500,50.",
			);
			return;
		}
		setPriceProblem(null);
		setIsSaving(true);
		try {
			const servicePayload = { ...editServiceForm, basePriceRub };
			if (editServiceId === "new") {
				await createServiceCatalogItem(servicePayload);
			} else {
				await updateServiceCatalogItem(editServiceId, servicePayload);
			}
			setEditServiceId(null);
		} catch (error: any) {
			mergedProps.setError?.(error.message || "╨Ю╤И╨╕╨▒╨║╨░ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╨╕╤П");
		} finally {
			setIsSaving(false);
		}
	};

	const handleDeleteService = async (id: string) => {
		if (deletingServiceId === id) return;
		if (
			!window.confirm(
				"╨г╨┤╨░╨╗╨╕╤В╤М ╤Г╤Б╨╗╤Г╨│╤Г ╨╕╨╖ ╨║╨░╤В╨░╨╗╨╛╨│╨░? (╨б╨▓╤П╨╖╨░╨╜╨╜╤Л╨╡ ╤Б╤З╨╡╤В╨░ ╤Б╨╛╤Е╤А╨░╨╜╤П╤В╤Б╤П, ╨╜╨╛ ╤Г╤Б╨╗╤Г╨│╨░ ╤Г╨╣╨┤╨╡╤В ╨▓ ╨░╤А╤Е╨╕╨▓)",
			)
		)
			return;
		if (!deleteServiceCatalogItem) return;
		setDeletingServiceId(id);
		try {
			await deleteServiceCatalogItem(id);
		} catch (error: any) {
			mergedProps.setError?.(error.message || "╨Ю╤И╨╕╨▒╨║╨░ ╤Г╨┤╨░╨╗╨╡╨╜╨╕╤П");
		} finally {
			setDeletingServiceId(null);
		}
	};

	return (
