	const rows: RowState[] = useMemo(() => {
		const result: RowState[] = [];
		const seen = new Set<string>();
		for (const member of staff) {
			const id = typeof member.id === "string" ? member.id : "";
			if (!id || seen.has(id)) continue;
			if (member.active === false) continue;
			seen.add(id);
			const nameRaw =
				typeof member.fullName === "string" ? member.fullName.trim() : "";
			const name = nameRaw.length > 0 ? nameRaw : id;
			const role = String(member.role ?? "");
			const fromDash = flagsFromMember(member);
			const ov = overrides[id];
			result.push({
				staffId: id,
				name,
				role: ov?.role ?? role,
				roleDerived: ov?.roleDerived ?? fromDash,
				effective: ov?.effective ?? fromDash,
				grants: ov?.grants ?? null,
			});
		}
		result.sort((a, b) => a.name.localeCompare(b.name, "ru"));
		return result;
	}, [staff, overrides]);

	const refreshDashboard = useCallback(async () => {
		if (typeof loadDashboard === "function") {
			try {
				await loadDashboard();
			} catch {
				/* ╨┤╨░╤И╨▒╨╛╤А╨┤ ╨╛╨▒╨╜╨╛╨▓╨╕╤В ╤Б╨╛╤Б╨╡╨┤╨╜╤П╤П ╨▓╨║╨╗╨░╨┤╨║╨░; ╨┐╨░╨╜╨╡╨╗╤М ╨╢╨╕╨▓╤С╤В ╨╜╨░ overrides */
			}
		}
	}, [loadDashboard]);

	const setFlag = async (
		row: RowState,
		flag: StaffAuthorityFlagKey,
		nextValue: boolean,
	) => {
		/*
		 * ╨б╨╜╤П╤В╤М ╤В╨╛, ╤З╤В╨╛ ╨┤╨░╤С╤В ╤А╨╛╨╗╤М, ╤Б╨╡╤А╨▓╨╡╤А ╨╛╤В╨▓╨╡╤А╨│╨╜╨╡╤В 409. ╨Э╨╡ ╤И╨╗╤С╨╝ ╨╖╨░╨▓╨╡╨┤╨╛╨╝╤Л╨╣ ╨╛╤В╨║╨░╨╖:
		 * ╨│╨░╨╗╨╛╤З╨║╨░ ┬л╤А╨╛╨╗╤М┬╗ ╤Г╨╢╨╡ disabled, ╨╜╨╛ ╨╜╨░ ╨▓╤Б╤П╨║╨╕╨╣ ╤Б╨╗╤Г╤З╨░╨╣.
		 */
		if (!nextValue && row.roleDerived[flag]) {
			const msg =
				`╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╨╡ ┬л${FLAG_TITLES[flag]}┬╗ ╨┤╨░╤С╤В ╤А╨╛╨╗╤М ┬л${staffRoleTitle(row.role)}┬╗. ` +
				"╨Ю╤В╨┤╨╡╨╗╤М╨╜╨╛╨╣ ╨│╨░╨╗╨╛╤З╨║╨╛╨╣ ╤Б╨╜╤П╤В╤М ╨╡╨│╨╛ ╨╜╨╡╨╗╤М╨╖╤П тАФ ╨╕╨╖╨╝╨╡╨╜╨╕╤В╨╡ ╤А╨╛╨╗╤М ╨▓ ╨║╨░╤А╤В╨╛╤З╨║╨╡ ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨░.";
			setSave({ kind: "failed", message: msg });
			showToast(msg, "warning");
			return;
		}
		if (row.effective[flag] === nextValue) return;

		setSave({ kind: "saving", staffId: row.staffId, flag });
		try {
			const body: Partial<Record<StaffAuthorityFlagKey, boolean>> = {
				[flag]: nextValue,
			};
			const response = await fetch(
				`/api/settings/staff/${row.staffId}/authority`,
				{
					method: "PUT",
					headers: denteAdminSecretRequestHeaders({
						"Content-Type": "application/json",
					}),
					body: JSON.stringify(body),
				},
			);
			const payload = (await response.json().catch((err) => {
				showToast(actionFailureToast("╨Ю╤И╨╕╨▒╨║╨░ ╨╛╤В╨▓╨╡╤В╨░ ╤Б╨╡╤А╨▓╨╡╤А╨░", (err as { status?: number })?.status ?? null), "error");
				return null;
			})) as unknown;
			if (!response.ok) {
				const refused = refusedFlagsOf(payload);
				const msg =
					serverMessageOf(payload) ??
					(response.status === 401 || response.status === 403
						? "╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╤Л: ╨▓╨╛╨╣╨┤╨╕╤В╨╡ ╨║╨░╨║ ╨▓╨╗╨░╨┤╨╡╨╗╨╡╤Ж ╨║╨╗╨╕╨╜╨╕╨║╨╕ ╨╕ ╨┐╤А╨╛╨▓╨╡╤А╤М╤В╨╡ ╤Б╨╡╨║╤А╨╡╤В ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А╨░."
						: actionFailureToast(
								`╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ┬л${row.name}┬╗ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╤Л`,
								response.status,
							));
				setSave({ kind: "failed", message: msg });
				showToast(msg, "error");
				/*
				 * 409 role_grants_authority: ╤Б╨╡╤А╨▓╨╡╤А ╨┐╨╡╤А╨╡╤З╨╕╤Б╨╗╨╕╨╗ ╨┐╨╛╨╗╤П тАФ ╨┐╨╛╨┤╤В╤П╨╜╨╡╨╝
				 * roleDerived, ╤З╤В╨╛╨▒╤Л disabled ╤Б╨╛╨▓╨┐╨░╨╗ ╤Б ╤Д╨░╨║╤В╨╛╨╝.
				 */
				if (response.status === 409 && refused.length > 0) {
					setOverrides((prev) => {
						const cur = prev[row.staffId];
						const roleDerived = {
							...(cur?.roleDerived ?? row.roleDerived),
						};
						for (const key of refused) roleDerived[key] = true;
						const effective = {
							...(cur?.effective ?? row.effective),
							...roleDerived,
						};
						return {
							...prev,
							[row.staffId]: {
								role: cur?.role ?? row.role,
								roleDerived,
								grants: cur?.grants ?? emptyFlags(false),
								effective,
							},
						};
					});
				}
				return;
			}
			const state = parseAuthorityState(payload);
			if (!state) {
				const msg =
					"╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╤Л, ╨╜╨╛ ╨╛╤В╨▓╨╡╤В ╤Б╨╡╤А╨▓╨╡╤А╨░ ╨╜╨╡ ╤А╨░╨╖╨╛╨▒╤А╨░╨╜. ╨Ю╨▒╨╜╨╛╨▓╨╕╤В╨╡ ╤Б╤В╤А╨░╨╜╨╕╤Ж╤Г.";
				setSave({ kind: "failed", message: msg });
				showToast(msg, "warning");
				await refreshDashboard();
				return;
			}
			setOverrides((prev) => ({
				...prev,
				[row.staffId]: {
					role: state.role,
					roleDerived: state.roleDerived,
					grants: state.grants,
					effective: state.effective,
				},
			}));
			const label = nextValue ? "╨▓╤Л╨┤╨░╨╜╨╛" : "╤Б╨╜╤П╤В╨╛";
			showToast(
				`┬л${row.name}┬╗: ${FLAG_TITLES[flag].toLowerCase()} тАФ ${label}.`,
				"success",
			);
			setSave({ kind: "idle" });
			await refreshDashboard();
		} catch {
			const msg = actionFailureToast(
				`╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ┬л${row.name}┬╗ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╤Л`,
				null,
			);
			setSave({ kind: "failed", message: msg });
			showToast(msg, "error");
		}
	};

	const clinicLoaded = Boolean(clinicSettings);

	return (
		<article
			className="settings-card col-span-full"
			aria-label="╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨╛╨▓"
			data-testid="staff-authority-panel"
		>
			<div
				className="settings-card-header"
				style={{
					display: "flex",
					justifyContent: "space-between",
					alignItems: "center",
					gap: "0.75rem",
					flexWrap: "wrap",
				}}
			>
				<div>
					<h4 className="m-0">╨Я╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨╛╨▓</h4>
					<p className="text-xs text-slate-500 dark:text-slate-400 m-0 mt-1">
						╨Э╨░╨┤╨▒╨░╨▓╨║╨░ ╨║ ╤А╨╛╨╗╨╕: ╨┐╨╛╨┤╨┐╨╕╤Б╤М ╨н╨Ь╨Ъ, ╨║╨░╤Б╤Б╨░, ╨┐╨╡╤А╨╡╨╜╨╛╤Б ╨┤╨░╨╜╨╜╤Л╤Е. ╨в╨╛, ╤З╤В╨╛ ╨┤╨░╤С╤В
						╤А╨╛╨╗╤М, ╤Б╨╜╤П╤В╤М ╨│╨░╨╗╨╛╤З╨║╨╛╨╣ ╨╜╨╡╨╗╤М╨╖╤П тАФ ╤Б╨╝╨╡╨╜╨╕╤В╨╡ ╤А╨╛╨╗╤М ╨▓ ╨║╨░╤А╤В╨╛╤З╨║╨╡. ╨б╨╡╨▒╨╡
						╨┐╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╤П ╨╜╨╡ ╨▓╤Л╨┤╨░╤О╤В.
					</p>
				</div>
				<button
					type="button"
					className="secondary-button text-xs"
					onClick={() => {
						setOverrides({});
						setSave({ kind: "idle" });
						void refreshDashboard();
					}}
					data-testid="staff-authority-refresh"
				>
					╨Ю╨▒╨╜╨╛╨▓╨╕╤В╤М
				</button>
			</div>

			<div className="settings-card-body">
				{!clinicLoaded ? (
					<p
						className="text-sm text-slate-500 m-0"
						data-testid="staff-authority-waiting"
					>
						╨Ф╨░╨╜╨╜╤Л╨╡ ╨║╨╗╨╕╨╜╨╕╨║╨╕ ╨╡╤Й╤С ╨╜╨╡ ╨┐╤А╨╛╤З╨╕╤В╨░╨╜╤Л тАФ ╤Б╨┐╨╕╤Б╨╛╨║ ╨┐╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╨╣ ╨┐╨╛╤П╨▓╨╕╤В╤Б╤П ╨┐╨╛╤Б╨╗╨╡
						╨╖╨░╨│╤А╤Г╨╖╨║╨╕.
					</p>
				) : null}

				{clinicLoaded && rows.length === 0 ? (
					<p
						className="text-sm text-slate-500 m-0"
						data-testid="staff-authority-empty"
					>
						╨Р╨║╤В╨╕╨▓╨╜╤Л╤Е ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨╛╨▓ ╨╜╨╡╤В. ╨Ф╨╛╨▒╨░╨▓╤М╤В╨╡ ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨░ ╨╜╨╕╨╢╨╡ тАФ ╨╖╨┤╨╡╤Б╤М ╨┐╨╛╤П╨▓╤П╤В╤Б╤П
						╨┐╨╡╤А╨╡╨║╨╗╤О╤З╨░╤В╨╡╨╗╨╕ ╨┐╨╛╨╗╨╜╨╛╨╝╨╛╤З╨╕╨╣.
					</p>
				) : null}

				{rows.length > 0 ? (
					<ul
						className="m-0 p-0 list-none flex flex-col gap-2"
						data-testid="staff-authority-list"
					>
						{rows.map((row) => {
							const open = expandedId === row.staffId;
							const grantCount = staffAuthorityFlagKeys.filter(
								(k) => row.effective[k],
							).length;
							return (
								<li
									key={row.staffId}
									className="border border-slate-200 dark:border-slate-800 rounded-xl bg-white dark:bg-slate-900"
									data-testid={`staff-authority-row-${row.staffId}`}
								>
									<button
										type="button"
										className="w-full text-left px-3 py-2.5 flex flex-wrap items-center justify-between gap-2 bg-transparent border-0 cursor-pointer"
										onClick={() => setExpandedId(open ? null : row.staffId)}
										aria-expanded={open}
										data-testid={`staff-authority-toggle-${row.staffId}`}
									>
										<span>
											<span className="text-sm font-semibold text-slate-900 dark:text-white">
												{row.name}
											</span>
											<span className="text-xs text-slate-500 ml-2">
												{staffRoleTitle(row.role)}
											</span>
										</span>
										<span className="text-xs text-slate-500">
											{grantCount} ╨╕╨╖ 3 ┬╖ {open ? "╨б╨▓╨╡╤А╨╜╤Г╤В╤М" : "╨Э╨░╤Б╤В╤А╨╛╨╕╤В╤М"}
										</span>
									</button>

									{open ? (
										<div
											className="px-3 pb-3 pt-0 border-t border-slate-100 dark:border-slate-800"
											data-testid={`staff-authority-editor-${row.staffId}`}
										>
											<div className="flex flex-col gap-3 mt-3">
												{staffAuthorityFlagKeys.map((flag) => {
													const on = row.effective[flag];
													const byRole = row.roleDerived[flag];
													const byGrant = row.grants
														? row.grants[flag] && !byRole
														: false;
													const isSaving =
														save.kind === "saving" &&
														save.staffId === row.staffId &&
														save.flag === flag;
													/*
													 * ╨У╨░╨╗╨╛╤З╨║╤Г ┬л╨┤╨░╤С╤В ╤А╨╛╨╗╤М┬╗ ╨╜╨╡╨╗╤М╨╖╤П ╤Б╨╜╤П╤В╤М: disabled +
													 * ╨┐╨╛╤П╤Б╨╜╨╡╨╜╨╕╨╡. ╨Т╨║╨╗╤О╤З╨╕╤В╤М ╨╜╨░╨┤╨▒╨░╨▓╨║╤Г ╨┐╨╛╨▓╨╡╤А╤Е false ╤А╨╛╨╗╨╕ тАФ
													 * ╨╝╨╛╨╢╨╜╨╛.
													 */
													const lockedOn = byRole;
													return (
														<label
															key={flag}
															className="flex items-start gap-3 text-sm cursor-pointer"
															data-testid={`staff-authority-flag-${row.staffId}-${flag}`}
														>
															<input
																type="checkbox"
																className="mt-1"
																checked={on}
																disabled={lockedOn || isSaving}
																onChange={(e) => {
																	void setFlag(row, flag, e.target.checked);
																}}
																aria-label={`${FLAG_TITLES[flag]} тАФ ${row.name}`}
																data-testid={`staff-authority-check-${row.staffId}-${flag}`}
															/>
															<span className="flex-1 min-w-0">
																<span className="font-medium text-slate-900 dark:text-white block">
																	{FLAG_TITLES[flag]}
																	{isSaving ? (
																		<span className="text-xs text-slate-400 font-normal ml-2">
																			╤Б╨╛╤Е╤А╨░╨╜╤П╨╡╨╝тАж
																		</span>
																	) : null}
																</span>
																<span className="text-xs text-slate-500 block mt-0.5">
																	{FLAG_HINTS[flag]}
																</span>
																{lockedOn ? (
																	<span
																		className="text-xs text-amber-700 dark:text-amber-300 block mt-0.5"
																		data-testid={`staff-authority-role-lock-${row.staffId}-${flag}`}
																	>
																		╨Ф╨░╤С╤В ╤А╨╛╨╗╤М ┬л{staffRoleTitle(row.role)}┬╗ тАФ
																		╤Б╨╜╤П╤В╤М ╨╝╨╛╨╢╨╜╨╛ ╤В╨╛╨╗╤М╨║╨╛ ╤Б╨╝╨╡╨╜╨╛╨╣ ╤А╨╛╨╗╨╕.
																	</span>
																) : null}
																{byGrant && on ? (
																	<span className="text-xs text-emerald-700 dark:text-emerald-300 block mt-0.5">
																		╨Т╤Л╨┤╨░╨╜╨╛ ╨┐╨╡╤А╤Б╨╛╨╜╨░╨╗╤М╨╜╨╛ (╨╜╨░╨┤╨▒╨░╨▓╨║╨░ ╨║ ╤А╨╛╨╗╨╕).
																	</span>
																) : null}
															</span>
														</label>
													);
												})}
											</div>
										</div>
									) : null}
								</li>
							);
						})}
					</ul>
				) : null}

				{save.kind === "failed" ? (
					<p
						className="text-sm text-rose-700 dark:text-rose-300 m-0 mt-3"
						role="alert"
						data-testid="staff-authority-error"
					>
						{save.message}
					</p>
				) : null}
			</div>
		</article>
	);
};

export default StaffAuthorityPanel;

/**
 * ╨Ф╨╡╨╣╤Б╤В╨▓╤Г╤О╤Й╨╕╨╡ ╤Б╤В╨░╨▓╨║╨╕ ╨▓╤А╨░╤З╨╡╨╣ (GET /api/settings/staff/commissions).
 *
 * ╨С╨л╨Ы╨Ю: ╨╝╨░╤А╤И╤А╤Г╤В ╨╛╤В╨┤╨░╨▓╨░╨╗ ╤Б╨┐╨╕╤Б╨╛╨║ `{ userId, commissionPct, materialCostDeductionPct,
 * effectiveFrom }` ╨╕╨╖ `doctor_commissions`, ╨░ PUT
 * `/api/settings/staff/:staffId/commission` ╤Г╨╢╨╡ ╨╢╨╕╨╗ ╨▓ DoctorPayoutDashboard тАФ
 * ╨╜╨╛ **zero web callers** ╨╜╨░ GET. ╨Т╨╗╨░╨┤╨╡╨╗╨╡╤Ж ╨▓╨╕╨┤╨╡╨╗ ╤Б╤В╨░╨▓╨║╤Г ╤В╨╛╨╗╤М╨║╨╛ ╨▓╨╜╤Г╤В╤А╨╕ ╨╝╨╡╤Б╤П╤З╨╜╨╛╨│╨╛
 * ╨╛╤В╤З╤С╤В╨░ ╨▓╤Л╨┐╨╗╨░╤В; ╨╜╨░ ╨▓╨║╨╗╨░╨┤╨║╨╡ ┬л╨Я╨╡╤А╤Б╨╛╨╜╨░╨╗┬╗ ╨┐╤А╨╛╤Ж╨╡╨╜╤В╨░ ╨╜╨╡ ╨▒╤Л╨╗╨╛, ╨╕ ╨▓╤А╨░╤З╨╕ ╨▒╨╡╨╖ ╨┐╤А╨╕╤С╨╝╨╛╨▓
 * ╨▓ ╨▓╤Л╨▒╤А╨░╨╜╨╜╨╛╨╝ ╨╝╨╡╤Б╤П╤Ж╨╡ ╨▓╤Л╨│╨╗╤П╨┤╨╡╨╗╨╕ ┬л╨▒╨╡╨╖ ╤Б╤В╨░╨▓╨║╨╕┬╗, ╤Е╨╛╤В╤П ╤Б╤В╤А╨╛╨║╨░ ╨▓ ╨▒╨░╨╖╨╡ ╤Г╨╢╨╡ ╨╡╤Б╤В╤М.
 *
 * ╨в╨Х╨Я╨Х╨а╨м: ╤Б╨░╨╝╨╛╨┤╨╛╤Б╤В╨░╤В╨╛╤З╨╜╨░╤П ╨┐╨░╨╜╨╡╨╗╤М ╨╜╨░ Settings тЖТ ╨Я╨╡╤А╤Б╨╛╨╜╨░╨╗. ╨У╤А╤Г╨╖╨╕╤В GET list,
 * ╤Б╨╛╨┐╨╛╤Б╤В╨░╨▓╨╗╤П╨╡╤В userId ╤Б ╨д╨Ш╨Ю ╨╕╨╖ ╨┤╨░╤И╨▒╨╛╤А╨┤╨░, ╨┤╨░╤С╤В ╨╖╨░╨┤╨░╤В╤М/╨╕╨╖╨╝╨╡╨╜╨╕╤В╤М ╨┐╤А╨╛╤Ж╨╡╨╜╤В ╤З╨╡╤А╨╡╨╖
 * ╤В╨╛╤В ╨╢╨╡ PUT ╨╕ `auth.settingsAccessHeaders`, ╤З╤В╨╛ ╨╕ ╨╛╤Б╤В╨░╨╗╤М╨╜╤Л╨╡ ╨▓╨║╨╗╨░╨┤╨║╨╕ ╨╜╨░╤Б╤В╤А╨╛╨╡╨║
 * (requireSettingsAccess + settingsAdminSecretSession тЖТ x-dente-admin-secret).
 *
 * BYLO: denteAdminSecretRequestHeaders() ╨▒╨╡╨╖ ╨▓╤В╨╛╤А╨╛╨│╨╛ ╨░╤А╨│╤Г╨╝╨╡╨╜╤В╨░ тАФ ╤Б╨╡╨║╤А╨╡╤В ╨╜╨╡
 * ╤Г╤Е╨╛╨┤╨╕╨╗. ╨Ы╨╛╨║╨░╨╗╤М╨╜╨╛ ╨╖╨╡╨╗╤С╨╜╨╛ (unguarded), ╤Г ╨╖╨░╨║╨░╨╖╤З╨╕╨║╨░ 403 ╨╜╨░ GET list ╨╕ PUT rate.
 */

import type React from "react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useAppLogicContext } from "../../contexts/AppLogicContext";
import { denteAdminSecretRequestHeaders } from "../../lib/denteRequestHeaders";
import { actionFailureToast } from "../../lib/panelStateText";
import { showToast } from "../GlobalToast";

type CommissionRate = {
	userId: string;
	commissionPct: string;
	materialCostDeductionPct: string;
	effectiveFrom: string;
};

type StaffMemberLite = {
	id?: string;
	fullName?: string;
	role?: string;
	active?: boolean;
};

type LoadState =
	| { kind: "idle" }
	| { kind: "loading" }
	| { kind: "ready"; rates: CommissionRate[] }
	| { kind: "failed"; message: string };

type SaveState =
	| { kind: "idle" }
	| { kind: "saving"; userId: string }
	| { kind: "failed"; message: string };

function serverMessageOf(payload: unknown): string | null {
	if (!payload || typeof payload !== "object") return null;
	const record = payload as { message?: unknown };
	if (typeof record.message === "string" && record.message.trim()) {
		return record.message.trim();
	}
	return null;
}

/** ╨У╤А╨░╨╜╨╕╤Ж╤Л ╨║╨░╨║ ╤Г doctor_commissions.commission_pct тАФ numeric(5,2). */
function parseCommissionInput(raw: string): number | null {
	const normalized = raw.trim().replace(",", ".");
	if (!normalized) return null;
	const n = Number(normalized);
	if (!Number.isFinite(n) || n < 0 || n > 100) return null;
	return Math.round(n * 100) / 100;
}

function percentLabel(pct: string | number): string {
	const n = typeof pct === "number" ? pct : Number(pct);
	if (!Number.isFinite(n)) return String(pct);
	return `${n.toLocaleString("ru-RU", { maximumFractionDigits: 2 })} %`;
}

function formatEffectiveFrom(iso: string): string {
	const d = new Date(iso);
	if (Number.isNaN(d.getTime())) return iso;
	return d.toLocaleDateString("ru-RU", {
		day: "numeric",
		month: "long",
		year: "numeric",
	});
}

function isDoctorLikeRole(role: string): boolean {
	// staffRoleSchema: owner | doctor | administrator | assistant | manager
	// ╨б╤В╨░╨▓╨║╤Г ╨┐╨╗╨░╤В╤П╤В ╨▓╤А╨░╤З╤Г; owner ╤З╨░╤Б╤В╨╛ ╤Б╨░╨╝ ╨┐╤А╨╕╨╜╨╕╨╝╨░╨╡╤В. assistant/admin тАФ ╨╜╨╡╤В.
	return role === "doctor" || role === "owner";
}

export const StaffCommissionsPanel: React.FC = () => {
	const appLogic = useAppLogicContext();
	/*
	 * authRef: useAppLogic returns a new auth object each render. Keep the
	 * settings secret fresh inside loadRates/saveRate without thrashing deps.
	 */
	const authRef = useRef(appLogic?.auth);
	authRef.current = appLogic?.auth;
	// dashboard ╨╢╨╕╨▓╤С╤В ╨╜╨░ ╨║╨╛╤А╨╜╨╡ useAppLogic; ╤В╨╛╤З╨╜╤Л╨╣ ╤В╨╕╨┐ тАФ ReturnType, ╤З╨╕╤В╨░╨╡╨╝ ╨╝╤П╨│╨║╨╛.
	const dashboardUnknown = (appLogic as { dashboard?: unknown } | null)
		?.dashboard;

	const clinicSettings =
		dashboardUnknown &&
		typeof dashboardUnknown === "object" &&
		dashboardUnknown !== null &&
		"clinicSettings" in dashboardUnknown
			? (dashboardUnknown as { clinicSettings?: { staff?: StaffMemberLite[] } })
					.clinicSettings
			: undefined;
	const staff: StaffMemberLite[] = Array.isArray(clinicSettings?.staff)
		? clinicSettings?.staff
		: [];

	const staffNameById = useMemo(() => {
		const map = new Map<string, string>();
		for (const member of staff) {
			const id = typeof member.id === "string" ? member.id : "";
			if (!id) continue;
			const name =
				typeof member.fullName === "string" ? member.fullName.trim() : "";
			map.set(id, name.length > 0 ? name : id);
		}
		return map;
	}, [staff]);

	const doctors = useMemo(() => {
		return staff.filter((m) => {
			const role = String(m.role ?? "");
			const active = m.active !== false;
			return active && isDoctorLikeRole(role);
		});
	}, [staff]);

	const [load, setLoad] = useState<LoadState>({ kind: "idle" });
	const [save, setSave] = useState<SaveState>({ kind: "idle" });
	const [editingUserId, setEditingUserId] = useState<string | null>(null);
	const [draft, setDraft] = useState("");

	const rateByUserId = useMemo(() => {
		const map = new Map<string, CommissionRate>();
		if (load.kind !== "ready") return map;
		for (const rate of load.rates) {
			if (!map.has(rate.userId)) map.set(rate.userId, rate);
		}
		return map;
	}, [load]);

	const loadRates = useCallback(async () => {
		setLoad({ kind: "loading" });
		try {
			const response = await fetch("/api/settings/staff/commissions", {
				method: "GET",
				headers: denteAdminSecretRequestHeaders(
					undefined,
					(authRef.current as any)?.settingsAdminSecretSession,
				),
			});
			const payload = (await response.json().catch((err) => {
				showToast(actionFailureToast("╨Ю╤И╨╕╨▒╨║╨░ ╨╛╤В╨▓╨╡╤В╨░ ╤Б╨╡╤А╨▓╨╡╤А╨░", (err as { status?: number })?.status ?? null), "error");
				return null;
			})) as unknown;
			if (!response.ok) {
				const msg =
					serverMessageOf(payload) ??
					(response.status === 401 || response.status === 403
						? "╨Э╨╡╤В ╨┐╤А╨░╨▓ ╤Б╨╝╨╛╤В╤А╨╡╤В╤М ╤Б╤В╨░╨▓╨║╨╕ ╨▓╤А╨░╤З╨╡╨╣: ╨▓╨╛╨╣╨┤╨╕╤В╨╡ ╨║╨░╨║ ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А ╨║╨╗╨╕╨╜╨╕╨║╨╕."
						: `╨б╤В╨░╨▓╨║╨╕ ╨╜╨╡ ╨╖╨░╨│╤А╤Г╨╢╨╡╨╜╤Л (╨╛╤В╨▓╨╡╤В ${response.status}).`);
				setLoad({ kind: "failed", message: msg });
				return;
			}
			const body = payload as { commissions?: unknown };
			const list = Array.isArray(body.commissions) ? body.commissions : [];
			const rates: CommissionRate[] = [];
			for (const row of list) {
				if (!row || typeof row !== "object") continue;
				const r = row as Record<string, unknown>;
				const userId = typeof r.userId === "string" ? r.userId : "";
				const commissionPct =
					typeof r.commissionPct === "string"
						? r.commissionPct
						: typeof r.commissionPct === "number"
							? String(r.commissionPct)
							: "";
				if (!userId || !commissionPct) continue;
				const materialCostDeductionPct =
					typeof r.materialCostDeductionPct === "string"
						? r.materialCostDeductionPct
						: typeof r.materialCostDeductionPct === "number"
							? String(r.materialCostDeductionPct)
							: "0";
				const effectiveFrom =
					typeof r.effectiveFrom === "string" ? r.effectiveFrom : "";
				rates.push({
					userId,
					commissionPct,
					materialCostDeductionPct,
					effectiveFrom,
				});
			}
			setLoad({ kind: "ready", rates });
		} catch {
			setLoad({
				kind: "failed",
				message: "╨б╤В╨░╨▓╨║╨╕ ╨╜╨╡ ╨╖╨░╨│╤А╤Г╨╢╨╡╨╜╤Л: ╨╜╨╡╤В ╤Б╨▓╤П╨╖╨╕ ╤Б ╨┐╤А╨╛╨│╤А╨░╨╝╨╝╨╛╨╣ ╨║╨╗╨╕╨╜╨╕╨║╨╕.",
			});
		}
	}, []);

	useEffect(() => {
		void loadRates();
	}, [loadRates]);

	const beginEdit = (userId: string, currentPct: string | null) => {
		setEditingUserId(userId);
		setDraft(currentPct ?? "");
		setSave({ kind: "idle" });
	};

	const cancelEdit = () => {
		setEditingUserId(null);
		setDraft("");
		setSave({ kind: "idle" });
	};

	const saveRate = async (userId: string) => {
		const pct = parseCommissionInput(draft);
		if (pct === null) {
			setSave({
				kind: "failed",
				message:
					"╨Я╤А╨╛╤Ж╨╡╨╜╤В ╨╛╤В ╨║╨░╤Б╤Б╤Л ╤Г╨║╨░╨╖╤Л╨▓╨░╨╡╤В╤Б╤П ╤З╨╕╤Б╨╗╨╛╨╝ ╨╛╤В 0 ╨┤╨╛ 100. ╨б╤В╨░╨▓╨║╨░ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╨░.",
			});
			return;
		}
		const name = staffNameById.get(userId) ?? "╨▓╤А╨░╤З╨░";
		setSave({ kind: "saving", userId });
		try {
			const response = await fetch(`/api/settings/staff/${userId}/commission`, {
				method: "PUT",
				headers: denteAdminSecretRequestHeaders(
					{
						"Content-Type": "application/json",
					},
					authRef.current?.settingsAdminSecretSession,
				),
				body: JSON.stringify({ commissionPct: pct }),
			});
			const payload = (await response.json().catch((err) => {
				showToast(actionFailureToast("╨Ю╤И╨╕╨▒╨║╨░ ╨╛╤В╨▓╨╡╤В╨░ ╤Б╨╡╤А╨▓╨╡╤А╨░", (err as { status?: number })?.status ?? null), "error");
				return null;
			})) as unknown;
			if (!response.ok) {
				const msg =
					serverMessageOf(payload) ??
					actionFailureToast(`╨б╤В╨░╨▓╨║╨░ ┬л${name}┬╗ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╨░`, response.status);
				setSave({ kind: "failed", message: msg });
				showToast(msg, "error");
				return;
			}
			showToast(`╨б╤В╨░╨▓╨║╨░ ┬л${name}┬╗: ${percentLabel(pct)}`, "success");
			setEditingUserId(null);
			setDraft("");
			setSave({ kind: "idle" });
			await loadRates();
		} catch {
			const msg = actionFailureToast(`╨б╤В╨░╨▓╨║╨░ ┬л${name}┬╗ ╨╜╨╡ ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╨░`, null);
			setSave({ kind: "failed", message: msg });
			showToast(msg, "error");
		}
	};

	const rows = useMemo(() => {
		const seen = new Set<string>();
		const result: Array<{
			userId: string;
			name: string;
			rate: CommissionRate | null;
		}> = [];
		for (const d of doctors) {
			const id = typeof d.id === "string" ? d.id : "";
			if (!id || seen.has(id)) continue;
			seen.add(id);
			result.push({
				userId: id,
				name: staffNameById.get(id) ?? id,
				rate: rateByUserId.get(id) ?? null,
			});
		}
		if (load.kind === "ready") {
			for (const rate of load.rates) {
				if (seen.has(rate.userId)) continue;
				seen.add(rate.userId);
				result.push({
					userId: rate.userId,
					name: staffNameById.get(rate.userId) ?? rate.userId,
					rate,
				});
			}
		}
		result.sort((a, b) => a.name.localeCompare(b.name, "ru"));
		return result;
	}, [doctors, load, rateByUserId, staffNameById]);

	const withoutRate = rows.filter((r) => r.rate === null).length;

	return (
		<article
			className="settings-card col-span-full"
			aria-label="╨б╤В╨░╨▓╨║╨╕ ╨▓╤А╨░╤З╨╡╨╣"
			data-testid="staff-commissions-panel"
		>
			<div
				className="settings-card-header"
				style={{
					display: "flex",
					justifyContent: "space-between",
					alignItems: "center",
					gap: "0.75rem",
					flexWrap: "wrap",
				}}
			>
				<div>
					<h4 className="m-0">╨б╤В╨░╨▓╨║╨╕ ╨▓╤А╨░╤З╨╡╨╣ (% ╨╛╤В ╨║╨░╤Б╤Б╤Л)</h4>
					<p className="text-xs text-slate-500 dark:text-slate-400 m-0 mt-1">
						╨Я╤А╨╛╤Ж╨╡╨╜╤В, ╨┐╨╛ ╨║╨╛╤В╨╛╤А╨╛╨╝╤Г ╨║╨╗╨╕╨╜╨╕╨║╨░ ╨┐╨╗╨░╤В╨╕╤В ╨▓╤А╨░╤З╤Г ╨╖╨░ ╨╗╨╡╤З╨╡╨╜╨╕╨╡. ╨Э╨╛╨╗╤М ╨┤╨╛╨┐╤Г╤Б╤В╨╕╨╝
						(╨╛╨║╨╗╨░╨┤). ╨Ф╨╡╨╣╤Б╤В╨▓╤Г╤О╤Й╨╕╨╡ ╨╖╨╜╨░╤З╨╡╨╜╨╕╤П ╨╕╨╖ ╤В╨░╨▒╨╗╨╕╤Ж╤Л ╤Б╤В╨░╨▓╨╛╨║, ╨╜╨╡ ╨╕╨╖ ╨╛╤В╤З╤С╤В╨░ ╨╖╨░
						╨╝╨╡╤Б╤П╤Ж.
					</p>
				</div>
				<button
					type="button"
					className="secondary-button text-xs"
					onClick={() => void loadRates()}
					disabled={load.kind === "loading"}
					data-testid="staff-commissions-refresh"
				>
					{load.kind === "loading" ? "╨Ч╨░╨│╤А╤Г╨╖╨║╨░тАж" : "╨Ю╨▒╨╜╨╛╨▓╨╕╤В╤М"}
				</button>
			</div>

			<div className="settings-card-body">
				{load.kind === "failed" ? (
					<p
						className="text-sm text-rose-700 dark:text-rose-300 m-0"
						role="alert"
						data-testid="staff-commissions-error"
					>
						{load.message}
					</p>
				) : null}

				{load.kind === "loading" && rows.length === 0 ? (
					<p
						className="text-sm text-slate-500 m-0"
						data-testid="staff-commissions-loading"
					>
						╨Ч╨░╨│╤А╤Г╨╢╨░╨╡╨╝ ╤Б╤В╨░╨▓╨║╨╕тАж
					</p>
				) : null}

				{load.kind === "ready" && rows.length === 0 ? (
					<p
						className="text-sm text-slate-500 m-0"
						data-testid="staff-commissions-empty"
					>
						╨Т╤А╨░╤З╨╡╨╣ ╨▓ ╤И╤В╨░╤В╨╡ ╨┐╨╛╨║╨░ ╨╜╨╡╤В. ╨Ф╨╛╨▒╨░╨▓╤М╤В╨╡ ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨░ ╤Б ╤А╨╛╨╗╤М╤О ┬л╨Т╤А╨░╤З┬╗ тАФ ╨╖╨┤╨╡╤Б╤М
						╨┐╨╛╤П╨▓╨╕╤В╤Б╤П ╤Б╤В╤А╨╛╨║╨░ ╨┤╨╗╤П ╨╜╨░╨╖╨╜╨░╤З╨╡╨╜╨╕╤П ╨┐╤А╨╛╤Ж╨╡╨╜╤В╨░.
					</p>
				) : null}

				{rows.length > 0 ? (
					<>
						{withoutRate > 0 ? (
							<p
								className="text-xs text-amber-700 dark:text-amber-300 m-0 mb-3"
								role="status"
							>
								╨С╨╡╨╖ ╤Б╤В╨░╨▓╨║╨╕: {withoutRate}. ╨Я╨╛╨║╨░ ╨┐╤А╨╛╤Ж╨╡╨╜╤В ╨╜╨╡ ╨╖╨░╨┤╨░╨╜, ╨╛╤В╤З╤С╤В ╨▓╤Л╨┐╨╗╨░╤В
								╨╜╨╡ ╨▓╨║╨╗╤О╤З╨░╨╡╤В ╤Н╤В╨╛╨│╨╛ ╨▓╤А╨░╤З╨░ ╨▓ ╨╕╤В╨╛╨│ ╨║ ╨▓╤Л╨┐╨╗╨░╤В╨╡.
							</p>
						) : null}
						<div className="overflow-x-auto">
							<table
								className="w-full text-sm"
								data-testid="staff-commissions-table"
							>
								<thead>
