																data-testid={`staff-commission-save-${row.userId}`}
															>
																{isSaving ? "тАж" : "╨б╨╛╤Е╤А╨░╨╜╨╕╤В╤М"}
															</button>
															<button
																type="button"
																className="secondary-button px-3 py-1 text-xs"
																disabled={isSaving}
																onClick={cancelEdit}
															>
																╨Ю╤В╨╝╨╡╨╜╨░
															</button>
														</div>
													) : (
														<button
															type="button"
															className="secondary-button px-3 py-1 text-xs"
															onClick={() =>
																beginEdit(
																	row.userId,
																	row.rate ? row.rate.commissionPct : null,
