describe("╤А╨╛╨╗╨╕, ╨╜╨░ ╨║╨╛╤В╨╛╤А╤Л╨╡ ╨╝╨╛╨╢╨╜╨╛ ╨┐╤А╨╕╨│╨╗╨░╤Б╨╕╤В╤М", () => {
