			assert.doesNotMatch(title, /[A-Za-z]/, `╨╗╨░╤В╨╕╨╜╨╕╤Ж╨░ ╨▓ ╨┐╨╛╨┤╨┐╨╕╤Б╨╕ ┬л${title}┬╗`);
			assert.equal(title, staffRoleLabels[role]);
		}
	});

	/**
	 * ╨в╨╛╤В ╤Б╨░╨╝╤Л╨╣ ╤И╨░╨│, ╨║╨╛╤В╨╛╤А╤Л╨╣ ╨┐╤А╨╡╨▓╤А╨░╤Й╨░╨╗ ╨╛╨┐╨╡╤З╨░╤В╨║╤Г ╨▓ ╨╗╨╕╤И╨╜╨╕╨╡ ╨┐╤А╨░╨▓╨░: ╤Д╨╕╨╗╤М╤В╤А ╤А╨░╨╖╨┤╨╡╨╗╨╛╨▓
	 * ╨┐╨╛ ╨╜╨╡╨╕╨╖╨▓╨╡╤Б╤В╨╜╨╛╨╣ ╤А╨╛╨╗╨╕ ╨┤╨╛╤Е╨╛╨┤╨╕╤В ╨┤╨╛ `return Array.from(appViews)`.
	 */
	test("╤А╨╛╨╗╤М ╨▓╨╜╨╡ ╤Б╤Е╨╡╨╝╤Л ╨┤╨░╨╗╨░ ╨▒╤Л ╨▒╨╛╨╗╤М╤И╨╡ ╤А╨░╨╖╨┤╨╡╨╗╨╛╨▓, ╤З╨╡╨╝ ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А╤Г", () => {
		const asAdministrator = getFilteredAppViews("administrator");
		const asUnknownRole = getFilteredAppViews("admin" as never);
		assert.ok(
			asUnknownRole.length > asAdministrator.length,
			"╨╡╤Б╨╗╨╕ ╤Н╤В╨╛ ╨┐╨╡╤А╨╡╤Б╤В╨░╨╜╨╡╤В ╨▒╤Л╤В╤М ╨▓╨╡╤А╨╜╤Л╨╝, ╨╛╨▒╤К╤П╤Б╨╜╨╡╨╜╨╕╨╡ ╨▓ settingsInviteRoles.ts ╨╜╨░╨┤╨╛ ╨┐╨╡╤А╨╡╨┐╨╕╤Б╨░╤В╤М, ╨░ ╨╜╨╡ ╤Г╨┤╨░╨╗╤П╤В╤М ╨┐╤А╨╛╨▓╨╡╤А╨║╤Г",
		);
		assert.ok(!asAdministrator.includes("visit"));
		assert.ok(asUnknownRole.includes("visit"));
	});
});

describe("╤А╨╛╨╗╨╕, ╨║╨╛╤В╨╛╤А╤Л╨╡ ╨╝╨╛╨╢╨╜╨╛ ╨╖╨░╨▓╨╡╤Б╤В╨╕ ╨║╨░╤А╤В╨╛╤З╨║╨╛╨╣ ╤Б╨╛╤В╤А╤Г╨┤╨╜╨╕╨║╨░", () => {
