	test("╤Г╤Б╨┐╨╡╤Е ╨▒╨╡╨╖ inviteLink тАФ ╤В╨╛╨╢╨╡ ╨╛╤В╨║╨░╨╖, ╨╕╨╜╨░╤З╨╡ ╤Б╨║╨╛╨┐╨╕╤А╤Г╤О╤В .../undefined", () => {
