			if (!res.ok) {
				throw new Error("╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╨╛╨▒╨╜╨╛╨▓╨╕╤В╤М ╤Б╤В╨░╤В╤Г╤Б");
