			setSubmittingId(null);
		}
	}

	if (loading) {
		return <div className="p-4">╨Ч╨░╨│╤А╤Г╨╖╨║╨░ ╨┐╤А╨╕╨╡╨╝╨╛╨▓ ╨╜╨░ ╨┐╤А╨╛╨▓╨╡╤А╨║╤Г...</div>;
	}

	if (error) {
		return <div className="p-4 text-red-600">{error}</div>;
	}

	if (visits.length === 0) {
		return (
			<EmptyState
				icon={<CheckCircle2 size={32} />}
				title="╨Т╤Б╨╡ ╨н╨Ь╨Ъ ╨┐╤А╨╛╨▓╨╡╤А╨╡╨╜╤Л"
				description="╨Э╨╡╤В ╨┐╤А╨╕╨╡╨╝╨╛╨▓, ╨╛╨╢╨╕╨┤╨░╤О╤Й╨╕╤Е ╨║╨╛╨╜╤В╤А╨╛╨╗╤П ╨║╨░╤З╨╡╤Б╤В╨▓╨░."
