					display: "flex",
					alignItems: "center",
					gap: "8px",
				}}
			>
				<Activity size={20} />
				╨Я╤А╨╛╨▓╨╡╤А╨║╨░ ╨╕╤Б╤В╨╛╤А╨╕╨╣ ╨▒╨╛╨╗╨╡╨╖╨╜╨╕ ╨│╨╗╨░╨▓╨▓╤А╨░╤З╨╛╨╝
			</h2>
			<div className="grid gap-4">
				{visits.map((visit) => (
					<div
