describe("╨╜╨╕╤З╤В╨╛ ╨▒╨╛╨╗╤М╤И╨╡ ╨╜╨╡ ╨┐╨╗╨░╨▓╨░╨╡╤В ╨╜╨░╨┤ ╨║╨╛╨╜╤В╨╡╨╜╤В╨╛╨╝", () => {
