describe("╨┐╨╛╤В╤А╨╡╨▒╨╕╤В╨╡╨╗╤М ╨║╨╛╨╜╤В╨╡╨║╤Б╤В╨░ ╨▓╨╜╨╡ ╨┐╤А╨╛╨▓╨░╨╣╨┤╨╡╤А╨░", () => {
	test("╨╢╨╕╨▓╨╛╨╣ ╤Н╨║╤А╨░╨╜ ╨║╨░╤А╤В╨╛╤В╨╡╨║╨╕ ╨▒╨╡╨╖ ╨┐╤А╨╛╨▓╨░╨╣╨┤╨╡╤А╨░ ╨Ю╨в╨Ъ╨Р╨Ч╨л╨Т╨Р╨Х╨в, ╨░ ╨╜╨╡ ╤А╨╕╤Б╤Г╨╡╤В ╨┐╤Г╤Б╤В╨╛╤В╤Г", () => {
		resetPatientStore();

		let thrown: unknown = null;
		let markup: string | null = null;
		try {
			markup = renderToStaticMarkup(patientsViewElement());
		} catch (error) {
			thrown = error;
		}

		assert.ok(
			thrown instanceof Error,
			"╤Н╨║╤А╨░╨╜ ╨║╨░╤А╤В╨╛╤В╨╡╨║╨╕ ╨┐╨╛╨┤╨╜╤П╨╗╤Б╤П ╨Т╨Э╨Х <AppLogicProvider> ╨╕ ╨╜╨╡ ╨╛╤В╨║╨░╨╖╨░╨╗. ╨Ч╨╜╨░╤З╨╕╤В ╨║╨╛╨╜╤В╨╡╨║╤Б╤В ╤Б╨╜╨╛╨▓╨░ " +
				"╨▓╤Л╨┤╨░╤С╤В ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╡ ╨▓╨╝╨╡╤Б╤В╨╛ ╨╛╤В╨║╨░╨╖╨░, ╨╕ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨░╤П ╨▓╨╡╤В╨║╨░, ╤Б╨╛╨▒╤А╨░╨╜╨╜╨░╤П ╨▓╤Л╤И╨╡ ╨┐╤А╨╛╨▓╨░╨╣╨┤╨╡╤А╨░, ╨▒╤Г╨┤╨╡╤В " +
				`╨╝╨╛╨╗╤З╨░ ╨┐╤Г╤Б╤В╨╛╨▓╨░╤В╤М. ╨Ю╤В╤А╨╕╤Б╨╛╨▓╨░╨╜╨╛: ${String(markup).slice(0, 200)}`,
		);
	});

	test("╤В╨╡╨║╤Б╤В ╨╛╤В╨║╨░╨╖╨░ ╨╜╨░╨╖╤Л╨▓╨░╨╡╤В ╤Е╤Г╨║, ╨┐╤А╨╛╨▓╨░╨╣╨┤╨╡╤А╨░ ╨╕ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╕╨╣ ╤И╨░╨│", () => {
		let message = "";
		try {
			renderToStaticMarkup(patientsViewElement());
		} catch (error) {
			message = error instanceof Error ? error.message : String(error);
		}

		// ╨б╨╗╨╛╨▓╨░, ╨▒╨╡╨╖ ╨║╨╛╤В╨╛╤А╤Л╤Е ╨╛╤В╨║╨░╨╖ ╨╜╨╡ ╨┐╨╛╨╝╨╛╨│╨░╨╡╤В: ╨┐╨╛ ╨╜╨╡╨╝╤Г ╨┤╨╛╨╗╨╢╨╜╨╛ ╨▒╤Л╤В╤М ╨▓╨╕╨┤╨╜╨╛, ╨з╨в╨Ю
		// ╤Б╨╗╨╛╨╝╨░╨╜╨╛ ╨╕ ╨з╨Х╨Ь ╨┐╨╛╤З╨╕╨╜╨╕╤В╤М, ╨▒╨╡╨╖ ╤З╤В╨╡╨╜╨╕╤П ╨╕╤Б╤Е╨╛╨┤╨╜╨╕╨║╨╛╨▓ ╨║╨╛╨╜╤В╨╡╨║╤Б╤В╨░.
		for (const needle of ["useAppLogicContext", "AppLogicProvider"]) {
			assert.ok(
				message.includes(needle),
