					`╤А╨░╨╖╤А╨░╨▒╨╛╤В╤З╨╕╨║╨░ ╨╕╤Б╨║╨░╤В╤М ╨┐╤А╨╕╤З╨╕╨╜╤Г ╨▓╤Б╨╗╨╡╨┐╤Г╤О. ╨в╨╡╨║╤Б╤В: ${message}`,
			);
		}
		assert.ok(
			message.length >= 80,
			`╨╛╤В╨║╨░╨╖ ╨╕╨╖ ${message.length} ╤Б╨╕╨╝╨▓╨╛╨╗╨╛╨▓ ╤Б╨╗╨╕╤И╨║╨╛╨╝ ╨║╤А╨░╤В╨╛╨║, ╤З╤В╨╛╨▒╤Л ╨╛╨▒╤К╤П╤Б╨╜╨╕╤В╤М, ╤З╤В╨╛ ╨┤╨╡╨╗╨░╤В╤М: ${message}`,
		);
		// ╨Ю╤В╨║╨░╨╖ ╨╛╨▒╤П╨╖╨░╨╜ ╨▒╤Л╤В╤М ╨╜╨░ ╤П╨╖╤Л╨║╨╡ ╨╛╤Б╤В╨░╨╗╤М╨╜╨╛╨╣ ╤Б╨╕╤Б╤В╨╡╨╝╤Л: ╤Б╨╛╨╛╨▒╤Й╨╡╨╜╨╕╤П ╤З╨╕╤В╨░╨╡╤В ╤В╨╛╤В ╨╢╨╡
		// ╤З╨╡╨╗╨╛╨▓╨╡╨║, ╤З╤В╨╛ ╨╕ ╨╜╨░╨┤╨┐╨╕╤Б╨╕ ╨▓ ╨╕╨╜╤В╨╡╤А╤Д╨╡╨╣╤Б╨╡.
		assert.match(message, /[╨Р-╤П]/, `╤В╨╡╨║╤Б╤В ╨╛╤В╨║╨░╨╖╨░ ╨╜╨╡ ╨┐╨╛-╤А╤Г╤Б╤Б╨║╨╕: ${message}`);
	});

	test("╤В╨╛╤В ╨╢╨╡ ╤Н╨║╤А╨░╨╜ ╨▓╨╜╤Г╤В╤А╨╕ ╨┐╤А╨╛╨▓╨░╨╣╨┤╨╡╤А╨░ ╨┐╨╛╨┤╨╜╨╕╨╝╨░╨╡╤В╤Б╤П", () => {
		resetPatientStore();
		const markup = renderToStaticMarkup(
			<AppLogicProvider value={emptyProviderValue}>
				{patientsViewElement()}
			</AppLogicProvider>,
		);
		assert.ok(
