function patientPhoneDigits(value: string | null | undefined): string {
	const digits = (value ?? "").replace(/\D/g, "");
	if (
		digits.length === 11 &&
		(digits.startsWith("8") || digits.startsWith("7"))
	) {
		return `7${digits.slice(1)}`;
	}
	return digits;
}

