			void loadSpeechRecordingRecovery({ silent: true });
			const applyKey = speechChunkApplyKey(result);
			if (appliedSpeechChunkKeysRef.current.has(applyKey)) {
				setSpeechStatusNote(
					`╨д╤А╨░╨│╨╝╨╡╨╜╤В ${result.chunk.chunkIndex + 1} ╤Г╨╢╨╡ ╤Г╤З╤В╨╡╨╜, ╨┤╤Г╨▒╨╗╤М ╨╜╨╡ ╨┤╨╛╨▒╨░╨▓╨╗╨╡╨╜.`,
