					const missing = assembly.missingChunkIndexes.length
						? ` ┬╖ ╨┐╤А╨╛╨┐╤Г╤Б╨║╨╕ ${assembly.missingChunkIndexes.join(", ")}`
						: "";
					setSpeechStatusNote(
