			if (hasAudioWaitingForServer && !speechGatewayCanUpload(currentGateway)) {
				await refreshPendingSpeechChunkState();
				if (!options.silent) {
					setSpeechStatusNote(
						`╨Ю╤З╨╡╤А╨╡╨┤╤М ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╤П ╤Б╨╛╤Е╤А╨░╨╜╨╡╨╜╨░: ${queue.length} ╤Д╤А╨░╨│╨╝. ╨б╨╡╤А╨▓╨╡╤А╨╜╨╛╨╡ ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╨╡ ╨╡╤Й╨╡ ╨╜╨╡ ╨│╨╛╤В╨╛╨▓╨╛, ╨░╤Г╨┤╨╕╨╛ ╨╜╨╡ ╤Г╨┤╨░╨╗╨╡╨╜╨╛.`,
