/**
 * ╨Ч╨░╨│╤А╤Г╨╖╨║╨░ ╤А╨╡╤Б╤Г╤А╤Б╨░, ╨┐╤А╨╕╨▓╤П╨╖╨░╨╜╨╜╨╛╨│╨╛ ╨║ ╨║╨╛╨╜╨║╤А╨╡╤В╨╜╨╛╨╝╤Г ╨┐╨░╤Ж╨╕╨╡╨╜╤В╤Г.
 *
 * ╨Т╨╕╨┤╨╢╨╡╤В╤Л ╨║╨░╤А╤В╨╛╤З╨║╨╕ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░ ╨┐╨╕╤Б╨░╨╗╨╕ ╨╖╨░╨│╤А╤Г╨╖╨║╤Г ╨▓╤А╤Г╤З╨╜╤Г╤О:
 *
 *     useEffect(() => { fetch(`/api/patients/${patientId}/...`)
 *       .then(r => r.json()).then(setItems); }, [patientId]);
 *
 * ╨г ╤В╨░╨║╨╛╨╣ ╨╖╨░╨│╤А╤Г╨╖╨║╨╕ ╨┤╨▓╨░ ╨┤╨╡╤Д╨╡╨║╤В╨░, ╨╕ ╨╛╨▒╨░ ╨▓╨╛╤Б╨┐╤А╨╛╨╕╨╖╨▓╨╡╨┤╨╡╨╜╤Л ╨▓ ╨╢╨╕╨▓╨╛╨╝ ╨▒╤А╨░╤Г╨╖╨╡╤А╨╡
 * (scratch/verify-patient-widget-race.mjs):
 *
 *   1. ╨б╨╛╤Б╤В╨╛╤П╨╜╨╕╨╡ ╨╜╨╡ ╤Б╨▒╤А╨░╤Б╤Л╨▓╨░╨╡╤В╤Б╤П ╨┐╤А╨╕ ╤Б╨╝╨╡╨╜╨╡ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░. ╨Я╨╛╨║╨░ ╨╕╨┤╤С╤В ╨╖╨░╨┐╤А╨╛╤Б ╨┐╨╛
 *      ╨╜╨╛╨▓╨╛╨╝╤Г ╨┐╨░╤Ж╨╕╨╡╨╜╤В╤Г, ╨╜╨░ ╨╡╨│╨╛ ╨║╨░╤А╤В╨╛╤З╨║╨╡ ╨┐╨╛╨║╨░╨╖╨░╨╜╤Л ╨┤╨░╨╜╨╜╤Л╨╡ ╨┐╤А╨╡╨┤╤Л╨┤╤Г╤Й╨╡╨│╨╛ тАФ ╨╕
 *      ╨▒╨╡╨╖ ╨╕╨╜╨┤╨╕╨║╨░╤В╨╛╤А╨░ ╨╖╨░╨│╤А╤Г╨╖╨║╨╕, ╤В╨╛ ╨╡╤Б╤В╤М ╨║╨░╨║ ╨┤╨╛╤Б╤В╨╛╨▓╨╡╤А╨╜╤Л╨╡. ╨Э╨░ ╨╝╨╡╨┤╨╗╨╡╨╜╨╜╨╛╨╣
 *      ╤Б╨╡╤В╨╕ ╤Н╤В╨╛ ╤Б╨╡╨║╤Г╨╜╨┤╤Л ╤З╤Г╨╢╨╛╨╣ ╨┐╨╡╤А╨╡╨┐╨╕╤Б╨║╨╕ ╨╕ ╤З╤Г╨╢╨╕╤Е ╨╛╤Б╨╗╨╛╨╢╨╜╨╡╨╜╨╕╨╣ ╨╜╨░ ╤З╤Г╨╢╨╛╨╣
 *      ╨║╨░╤А╤В╨╛╤З╨║╨╡.
 *
 *   2. ╨г╤Б╤В╨░╤А╨╡╨▓╤И╨╕╨╣ ╨╛╤В╨▓╨╡╤В ╨╜╨╡ ╨╛╤В╨▒╤А╨░╤Б╤Л╨▓╨░╨╡╤В╤Б╤П. ╨Х╤Б╨╗╨╕ ╨╛╤В╨▓╨╡╤В ╨┐╨╛ ╤А╨░╨╜╨╡╨╡ ╨▓╤Л╨▒╤А╨░╨╜╨╜╨╛╨╝╤Г
 *      ╨┐╨░╤Ж╨╕╨╡╨╜╤В╤Г ╨┐╤А╨╕╤Е╨╛╨┤╨╕╤В ╨┐╨╛╨╖╨╢╨╡ ╨╛╤В╨▓╨╡╤В╨░ ╨┐╨╛ ╤В╨╡╨║╤Г╤Й╨╡╨╝╤Г, ╨╛╨╜ ╨┐╨╡╤А╨╡╤В╨╕╤А╨░╨╡╤В ╤Н╨║╤А╨░╨╜ ╨╕
 *      ╨╛╤Б╤В╨░╤С╤В╤Б╤П ╤В╨░╨╝ ╨┤╨╛ ╤Б╨╗╨╡╨┤╤Г╤О╤Й╨╡╨│╨╛ ╨┐╨╡╤А╨╡╨║╨╗╤О╤З╨╡╨╜╨╕╤П.
 *
 * ╨е╤Г╨║ ╨╖╨░╨║╤А╤Л╨▓╨░╨╡╤В ╨╛╨▒╨░: ╨┤╨░╨╜╨╜╤Л╨╡ ╨╛╨▒╨╜╤Г╨╗╤П╤О╤В╤Б╤П ╤Б╨╕╨╜╤Е╤А╨╛╨╜╨╜╨╛ ╨┐╤А╨╕ ╤Б╨╝╨╡╨╜╨╡ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░, ╨░
 * ╨╖╨░╨┐╤А╨╛╤Б ╨╛╤В╨╝╨╡╨╜╤П╨╡╤В╤Б╤П ╨╕ ╨╡╨│╨╛ ╤А╨╡╨╖╤Г╨╗╤М╤В╨░╤В ╨╕╨│╨╜╨╛╤А╨╕╤А╤Г╨╡╤В╤Б╤П, ╨╡╤Б╨╗╨╕ ╨┐╨░╤Ж╨╕╨╡╨╜╤В ╤Б╨╝╨╡╨╜╨╕╨╗╤Б╤П.
 *
 * `reload` ╨╜╤Г╨╢╨╡╨╜ ╨▓╨╕╨┤╨╢╨╡╤В╨░╨╝, ╨║╨╛╤В╨╛╤А╤Л╨╡ ╨┐╨╡╤А╨╡╤З╨╕╤В╤Л╨▓╨░╤О╤В ╤Б╨┐╨╕╤Б╨╛╨║ ╨┐╨╛╤Б╨╗╨╡ ╤Б╨▓╨╛╨╡╨╣ ╨╢╨╡
 * ╨╝╤Г╤В╨░╤Ж╨╕╨╕ (╤Б╨╛╨╖╨┤╨░╨╗╨╕ ╨╖╨░╨┤╨░╤З╤Г тАФ ╨╛╨▒╨╜╨╛╨▓╨╕╨╗╨╕ ╤Б╨┐╨╕╤Б╨╛╨║).
 *
 * `error` ╨┐╨╛╤П╨▓╨╕╨╗╤Б╤П ╨┐╨╛ ╤В╤А╨╡╤В╤М╨╡╨╣ ╨┐╤А╨╕╤З╨╕╨╜╨╡: ╨╛╤В╨║╨░╨╖ ╤Б╨╡╤А╨▓╨╡╤А╨░ (404 ╨╜╨░ ╨╜╨╡╤Б╤Г╤Й╨╡╤Б╤В╨▓╤Г╤О╤Й╨╕╨╣
 * ╨░╨┤╤А╨╡╤Б, 500 ╨╜╨░ ╤Б╨▒╨╛╨╣ ╨╖╨░╨┐╤А╨╛╤Б╨░) ╤А╨░╨╜╤М╤И╨╡ ╨╛╤Б╤В╨░╨▓╨╗╤П╨╗ ╨┐╤Г╤Б╤В╨╛╨╡ ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╡, ╨╕ ╨▓╨╕╨┤╨╢╨╡╤В
 * ╨┐╨╛╨║╨░╨╖╤Л╨▓╨░╨╗ ┬л╨┤╨░╨╜╨╜╤Л╤Е ╨╜╨╡╤В┬╗. ╨н╤В╨╛ ╨╗╨╛╨╢╤М: ╨┤╨░╨╜╨╜╤Л╨╡ ╨╝╨╛╨│╤Г╤В ╨▒╤Л╤В╤М, ╨╕╤Е ╨╜╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М
 * ╨┐╨╛╨╗╤Г╤З╨╕╤В╤М. ╨Т╨╕╨┤╨╢╨╡╤В ╨╛╨▒╤П╨╖╨░╨╜ ╨┐╨╛╨║╨░╨╖╨░╤В╤М ╨╛╤В╨║╨░╨╖, ╨░ ╨╜╨╡ ╨▓╤Л╨┤╨░╤В╤М ╨╡╨│╨╛ ╨╖╨░ ╨┐╤Г╤Б╤В╨╛╤В╤Г.
 *
 * ╨з╨Х╨в╨Т╨Б╨а╨в╨Р╨п ╨Я╨а╨Ш╨з╨Ш╨Э╨Р, ╨Я╨Ю╨з╨Х╨Ь╨г ╨н╨в╨Ю╨в ╨д╨Р╨Щ╨Ы ╨Я╨а╨Р╨Т╨Ш╨Ы╨б╨п ╨б╨Э╨Ю╨Т╨Р. ╨в╨╡╨║╤Б╤В ╨╛╤В╨║╨░╨╖╨░ ╨▒╤Л╨╗
 * ┬л╨б╨╡╤А╨▓╨╡╤А ╨╛╤В╨▓╨╡╤В╨╕╨╗ ╨╛╤И╨╕╨▒╨║╨╛╨╣ 500. ╨Ф╨░╨╜╨╜╤Л╨╡ ╨╜╨╡ ╨╖╨░╨│╤А╤Г╨╢╨╡╨╜╤Л.┬╗ тАФ ╨╕ ╤В╤А╨╕ ╨▓╨╕╨┤╨╢╨╡╤В╨░ ╨║╨░╤А╤В╨╛╤З╨║╨╕
 * ╨┐╨╡╤З╨░╤В╨░╨╗╨╕ ╨╡╨│╨╛ ╨┤╨╛╤Б╨╗╨╛╨▓╨╜╨╛. ╨У╨╛╨╗╤Л╨╣ ╨║╨╛╨┤ ╤Б╨╛╤Б╤В╨╛╤П╨╜╨╕╤П ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А╤Г ╨╜╨╡ ╨│╨╛╨▓╨╛╤А╨╕╤В ╨╜╨╕ ╤З╤В╨╛
 * ╤Б╨╗╤Г╤З╨╕╨╗╨╛╤Б╤М, ╨╜╨╕ ╤З╤В╨╛ ╨┤╨╡╨╗╨░╤В╤М; ╨╜╨╛╨╝╨╡╤А ╨╜╤Г╨╢╨╡╨╜ ╤А╨░╨╖╤А╨░╨▒╨╛╤В╤З╨╕╨║╤Г ╨╕ ╤Г╤Е╨╛╨┤╨╕╤В ╨▓ console.error.
 * ╨д╨╛╤А╨╝╤Г╨╗╨╕╤А╨╛╨▓╨║╨╕ ╨╢╨╕╨▓╤Г╤В ╨▓ ╨╛╨┤╨╜╨╛╨╝ ╨╝╨╡╤Б╤В╨╡ тАФ lib/panelStateText.ts.
 *
 * `failureStatus` ╨╛╤В╨┤╨░╤С╤В╤Б╤П ╤А╤П╨┤╨╛╨╝ ╤Б `error`, ╤З╤В╨╛╨▒╤Л ╨▓╨╕╨┤╨╢╨╡╤В ╨╝╨╛╨│ ╤Б╨╛╨▒╤А╨░╤В╤М ╤Б╨▓╨╛╤С
 * ╨┐╤А╨╡╨┤╨╗╨╛╨╢╨╡╨╜╨╕╨╡ ╤З╨╡╤А╨╡╨╖ `panelStateText` ╨╕ ╨╜╨░╨╖╨▓╨░╤В╤М ╨┐╨╛╤Б╨╗╨╡╨┤╤Б╤В╨▓╨╕╨╡ ╨╛╤В╨║╨░╨╖╨░ ╨┐╨╛-╤Б╨▓╨╛╨╡╨╝╤Г:
 * ┬л╨╛╤Б╨╗╨╛╨╢╨╜╨╡╨╜╨╕╤П ╨╜╨╡ ╨┐╤А╨╛╤З╨╕╤В╨░╨╜╤Л┬╗ ╨╕ ┬л╨╖╨░╨┤╨░╤З╨╕ ╨╜╨╡ ╨┐╤А╨╛╤З╨╕╤В╨░╨╜╤Л┬╗ тАФ ╤А╨░╨╖╨╜╤Л╨╡ ╨┐╨╛ ╤Ж╨╡╨╜╨╡ ╨▓╨╡╤Й╨╕.
 */
export function usePatientResource<T>(
	patientId: string | null | undefined,
	buildUrl: (patientId: string) => string,
	buildHeaders: () => Record<string, string>,
	emptyValue: T,
): {
	data: T;
	setData: React.Dispatch<React.SetStateAction<T>>;
	isLoading: boolean;
	/** ╨У╨╛╤В╨╛╨▓╨░╤П ╤З╨╡╨╗╨╛╨▓╨╡╤З╨╡╤Б╨║╨░╤П ╨┐╤А╨╕╤З╨╕╨╜╨░ ╨╛╤В╨║╨░╨╖╨░ ╤Б ╤В╨╛╤З╨║╨╛╨╣ ╨╜╨░ ╨║╨╛╨╜╤Ж╨╡, ╨╗╨╕╨▒╨╛ null. */
	error: string | null;
	/** ╨Ъ╨╛╨┤ ╨╛╤В╨▓╨╡╤В╨░ ╤Б╨╡╤А╨▓╨╡╤А╨░ ╨┐╤А╨╕ ╨╛╤В╨║╨░╨╖╨╡; null тАФ ╨┤╨╛ ╤Б╨╡╤А╨▓╨╡╤А╨░ ╨╜╨╡ ╨┤╨╛╤И╨╗╨╕ ╨╕╨╗╨╕ ╨╛╤В╨║╨░╨╖╨░ ╨╜╨╡ ╨▒╤Л╨╗╨╛. */
	failureStatus: number | null;
	reload: () => void;
} {
	const [data, setData] = useState<T>(emptyValue);
	const [isLoading, setIsLoading] = useState<boolean>(Boolean(patientId));
	const [error, setError] = useState<string | null>(null);
	const [failureStatus, setFailureStatus] = useState<number | null>(null);
	const [_reloadToken, setReloadToken] = useState(0);

	// ╨д╤Г╨╜╨║╤Ж╨╕╨╕ ╨┐╤А╨╕╤Е╨╛╨┤╤П╤В ╨╜╨╛╨▓╤Л╨╝╨╕ ╨╜╨░ ╨║╨░╨╢╨┤╨╛╨╝ ╤А╨╡╨╜╨┤╨╡╤А╨╡. ╨Ф╨╡╤А╨╢╨╕╨╝ ╨╕╤Е ╨▓ ref, ╨╕╨╜╨░╤З╨╡
	// ╤Н╤Д╤Д╨╡╨║╤В ╨┐╨╡╤А╨╡╨╖╨░╨┐╤Г╤Б╨║╨░╨╗╤Б╤П ╨▒╤Л ╨┐╨╛╤Б╤В╨╛╤П╨╜╨╜╨╛ ╨╕ ╨▒╨╛╨╝╨▒╨╕╨╗ ╨▒╤Л API.
	const urlRef = useRef(buildUrl);
	urlRef.current = buildUrl;
	const headersRef = useRef(buildHeaders);
	headersRef.current = buildHeaders;
	const emptyRef = useRef(emptyValue);

	useEffect(() => {
		if (!patientId) {
			setData(emptyRef.current);
			setIsLoading(false);
			setError(null);
			setFailureStatus(null);
			return;
		}

		// ╨Ф╨░╨╜╨╜╤Л╨╡ ╨┐╤А╨╡╨┤╤Л╨┤╤Г╤Й╨╡╨│╨╛ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░ ╤Г╨▒╨╕╤А╨░╤О╤В╤Б╤П ╨Ф╨Ю ╨╛╤В╨▓╨╡╤В╨░ ╤Б╨╡╤А╨▓╨╡╤А╨░, ╨░ ╨╜╨╡ ╨┐╨╛╤Б╨╗╨╡.
		setData(emptyRef.current);
		setIsLoading(true);
		setError(null);
		setFailureStatus(null);

		const controller = new AbortController();
		let cancelled = false;

		(async () => {
			try {
				const res = await fetch(urlRef.current(patientId), {
					headers: headersRef.current(),
					signal: controller.signal,
				});
				if (cancelled) return;
				if (!res.ok) {
					// ╨Ъ╨╛╨┤ ╤Б╨╛╤Б╤В╨╛╤П╨╜╨╕╤П ╨╜╤Г╨╢╨╡╨╜ ╨┐╨╛╨┤╨┤╨╡╤А╨╢╨║╨╡, ╨░ ╨╜╨╡ ╨╛╨┐╨╡╤А╨░╤В╨╛╤А╤Г: ╨╛╨╜ ╨▓ ╨║╨╛╨╜╤Б╨╛╨╗╨╕.
					logger.error(
						`[usePatientResource ${patientId}] ╨╛╤В╨▓╨╡╤В ${res.status} ╨╜╨░ ${urlRef.current(patientId)}`,
					);
					setFailureStatus(res.status);
					setError(`${panelFailureCause(res.status)}.`);
					return;
				}
				const parsed = (await res.json()) as T;
				// ╨Я╨╛╨▓╤В╨╛╤А╨╜╨░╤П ╨┐╤А╨╛╨▓╨╡╤А╨║╨░: ╤А╨░╨╖╨▒╨╛╤А ╤В╨╡╨╗╨░ тАФ ╤В╨╛╨╢╨╡ await, ╨╖╨░ ╤Н╤В╨╛ ╨▓╤А╨╡╨╝╤П
				// ╨┐╨░╤Ж╨╕╨╡╨╜╤В ╨╝╨╛╨│ ╤Б╨╝╨╡╨╜╨╕╤В╤М╤Б╤П.
				if (cancelled) return;
				setData(parsed);
			} catch (requestError) {
				showToast(
					actionFailureToast(
						"${panelFailureCause(null)}.",
						(requestError as { status?: number })?.status ?? null,
					),
					"error",
				);
				if (cancelled) return;
				if ((requestError as Error)?.name === "AbortError") return;
				logger.error(`[usePatientResource ${patientId}]`, requestError);
				// null ╨╛╨╖╨╜╨░╤З╨░╨╡╤В ┬л╨┤╨╛ ╤Б╨╡╤А╨▓╨╡╤А╨░ ╨╜╨╡ ╨┤╨╛╤И╨╗╨╕ ╨▓╨╛╨▓╤Б╨╡┬╗ тАФ ╤Н╤В╨╛ ╨┤╤А╤Г╨│╨░╤П ╨┐╤А╨╕╤З╨╕╨╜╨░
				// ╨╕ ╨┤╤А╤Г╨│╨╛╨╡ ╨┤╨╡╨╣╤Б╤В╨▓╨╕╨╡, ╤З╨╡╨╝ ╨╗╤О╨▒╨╛╨╣ ╨╛╤В╨▓╨╡╤В ╤Б╨╡╤А╨▓╨╡╤А╨░.
				setFailureStatus(null);
				setError(`${panelFailureCause(null)}.`);
			} finally {
				if (!cancelled) setIsLoading(false);
			}
		})();

		return () => {
			cancelled = true;
			controller.abort();
		};
	}, [patientId]);

	const reload = useCallback(() => setReloadToken((token) => token + 1), []);

	return { data, setData, isLoading, error, failureStatus, reload };
}

