	SpeechChunkUploadInput,
	SpeechGatewayStatus,
	SpeechTranscriptionSource,
} from "@dental/shared";
import { useCallback, useRef, useState } from "react";
import {
	denteAdminSecretRequestHeaders,
	operatorReadableErrorDetail,
} from "../AppHelpers";
import { showToast } from "../components/GlobalToast";
import { actionFailureToast } from "../lib/panelStateText";
import { useAppStore } from "../store/appStore";
import { useSettingsStore } from "../store/settingsStore";
import { logger } from "../utils/logger";

type ContextType =
	| "schedule"
	| "visit"
	| "patient"
	| "price"
	| "payment"
	| "general";

export function useShortDictation(
	context: ContextType,
	onResult: (text: string) => void,
) {
	const [isRecording, setIsRecording] = useState(false);
	const [isProcessing, setIsProcessing] = useState(false);

	const mediaRecorderRef = useRef<MediaRecorder | null>(null);
	const audioChunksRef = useRef<Blob[]>([]);
	const streamRef = useRef<MediaStream | null>(null);

	const dashboard = useAppStore((state) => state.dashboard);
	const speechGatewayStatus = useAppStore(
		(state) => state.speechGatewayStatus as SpeechGatewayStatus | null,
	);
	// ╨б╨╡╨║╤А╨╡╤В ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А╨░ ╨▒╨╡╤А╤С╤В╤Б╤П ╨╕╨╖ ╤Б╨╡╨░╨╜╤Б╨░, ╨░ ╨╜╨╡ ╨╕╨╖ localStorage: ╨┐╨╛╨┤╤А╨╛╨▒╨╜╨╛╨╡
	// ╨╛╨▒╤К╤П╤Б╨╜╨╡╨╜╨╕╨╡ тАФ ╤Г ╨╝╨╡╤Б╤В╨░ ╨╕╤Б╨┐╨╛╨╗╤М╨╖╨╛╨▓╨░╨╜╨╕╤П ╨╜╨╕╨╢╨╡.
	const clinicalAdminSecretSession = useSettingsStore(
		(state) => state.clinicalAdminSecretSession,
	);

	const cleanupStream = useCallback(() => {
		if (streamRef.current) {
			streamRef.current.getTracks().forEach((track) => {
				track.stop();
			});
			streamRef.current = null;
		}
	}, []);

	const startBrowserNative = useCallback(() => {
		const SpeechRecognition =
			(window as any).SpeechRecognition ||
			(window as any).webkitSpeechRecognition;
		if (!SpeechRecognition) {
			showToast(
				"╨а╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╨╡ ╤А╨╡╤З╨╕ ╨╜╨╡ ╨┐╨╛╨┤╨┤╨╡╤А╨╢╨╕╨▓╨░╨╡╤В╤Б╤П ╨▓ ╤Н╤В╨╛╨╝ ╨▒╤А╨░╤Г╨╖╨╡╤А╨╡.",
				"error",
			);
			return;
		}

		const recognition = new SpeechRecognition();
		recognition.lang = "ru-RU";
		recognition.continuous = false;
		recognition.interimResults = false;

		recognition.onstart = () => setIsRecording(true);

		recognition.onresult = (event: any) => {
			const transcript = event.results[0][0].transcript;
			if (transcript) onResult(transcript);
		};

		recognition.onerror = (e: any) => {
			if (e.error !== "no-speech") {
				showToast(`╨Ю╤И╨╕╨▒╨║╨░ ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╤П: ${e.error}`, "error");
			}
			setIsRecording(false);
		};

		recognition.onend = () => setIsRecording(false);
		recognition.start();
	}, [onResult]);

	const sendToServer = useCallback(
		async (audioBlob: Blob) => {
			setIsProcessing(true);
			try {
				const reader = new FileReader();
				const base64Promise = new Promise<string>((resolve, reject) => {
					reader.onloadend = () => {
						const result = reader.result as string | null;
						if (result) {
							resolve(result.split(",")[1] || "");
						} else {
							reject(new Error("Failed to read blob"));
						}
					};
					reader.onerror = reject;
					reader.readAsDataURL(audioBlob);
				});
				const audioBase64 = await base64Promise;

				const source: SpeechTranscriptionSource =
					context === "visit" || context === "patient" ? "visit" : "document";

				const input: SpeechChunkUploadInput = {
					recordingId: `short_${Date.now()}`,
					chunkIndex: 0,
					mimeType: audioBlob.type || "audio/webm",
					audioBase64,
					durationMs: 3000,
					language: "ru",
					source,
					patientId: dashboard?.activeVisit?.patientId,
					visitId: dashboard?.activeVisit?.id,
					specialty: "universal",
					clientRecordedAt: new Date().toISOString(),
				};

				/*
				 * ╨С╨л╨Ы╨Ю: ╤Б╨╡╨║╤А╨╡╤В ╤З╨╕╤В╨░╨╗╤Б╤П ╨╕╨╖ localStorage ╨┐╨╛ ╨║╨╗╤О╤З╤Г
				 * "dente_clinical_admin_secret_session". ╨н╤В╨╛╤В ╨║╨╗╤О╤З ╨Э╨Ш╨Ъ╨в╨Ю ╨Э╨Ш╨Ъ╨Ю╨У╨Ф╨Р ╨Э╨Х ╨Я╨Ш╨и╨Х╨в тАФ
				 * ╨▓╨╛ ╨▓╤Б╤С╨╝ ╨▓╨╡╨▒╨╡ ╨╡╤Б╤В╤М ╤В╨╛╨╗╤М╨║╨╛ ╤В╤А╨╕ ╤З╤В╨╡╨╜╨╕╤П (╨╖╨┤╨╡╤Б╤М ╨╕ ╨┤╨▓╨░╨╢╨┤╤Л ╨▓ useVoiceAssistant)
				 * ╨╕ ╨╜╨╕ ╨╛╨┤╨╜╨╛╨╣ ╨╖╨░╨┐╨╕╤Б╨╕. ╨Ч╨╜╨░╤З╨╕╤В secret ╨▓╤Б╨╡╨│╨┤╨░ ╨▒╤Л╨╗ undefined, ╨╖╨░╨│╨╛╨╗╨╛╨▓╨╛╨║ ╤Б╨╡╨║╤А╨╡╤В╨░
				 * ╨╜╨╡ ╤Г╤Е╨╛╨┤╨╕╨╗, ╨╕ ╨╜╨░ ╤Н╤В╨╛╨╣ ╨╝╨░╤И╨╕╨╜╨╡ ╤Н╤В╨╛ ╨╜╨╡ ╨▒╤Л╨╗╨╛ ╨▓╨╕╨┤╨╜╨╛: ╨▓ ╨║╨╛╤А╨╜╨╡╨▓╨╛╨╝ .env ╨▓╨║╨╗╤О╤З╨╡╨╜╤Л
				 * ╨╗╨░╨╖╨╡╨╣╨║╨╕ DENTE_CLINICAL_ALLOW_UNGUARDED_READS/MUTATIONS, ╨│╨░╤Б╤П╤Й╨╕╨╡ ╨╛╤Е╤А╨░╨╜╤Г.
				 * ╨Ы╨░╨╖╨╡╨╣╨║╨╕ ╨╢╨╕╨▓╤Г╤В ╤В╨╛╨╗╤М╨║╨╛ ╨┐╨╛╨║╨░ NODE_ENV !== "production".
				 *
				 * ╨Я╤А╨╛╨▓╨╡╤А╨╡╨╜╨╛ ╨╢╨╕╨▓╤М╤С╨╝ ╨╜╨░ ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╨╝ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨╡ API ╤Б ╨╖╨░╨┤╨░╨╜╨╜╤Л╨╝ ╤Б╨╡╨║╤А╨╡╤В╨╛╨╝ ╨╕
				 * ╨▓╤Л╨║╨╗╤О╤З╨╡╨╜╨╜╤Л╨╝╨╕ ╨╗╨░╨╖╨╡╨╣╨║╨░╨╝╨╕: /api/speech/status ╨╛╤В╨▓╨╡╤З╨░╨╡╤В 403
				 * (┬лspeech gateway status┬╗). ╨в╨╛ ╨╡╤Б╤В╤М ╤Г ╨╜╨░╤Б╤В╨╛╤П╤Й╨╡╨│╨╛ ╨╖╨░╨║╨░╨╖╤З╨╕╨║╨░ ╨┤╨╕╨║╤В╨╛╨▓╨║╨░ ╨▓╤А╨░╤З╨░
				 * ╨╜╨╡ ╤А╨░╨▒╨╛╤В╨░╨╗╨░ ╨▓╨╛╨▓╤Б╨╡, ╨░ ╨▓╤А╨░╤З ╨▓╨╕╨┤╨╡╨╗ ╤В╨╛╨╗╤М╨║╨╛ ╤В╨╛, ╤З╤В╨╛ ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╨╡ ┬л╤Е╤Г╨╢╨╡
				 * ╨╛╨╢╨╕╨┤╨░╨╡╨╝╨╛╨│╨╛┬╗.
				 *
				 * ╨Э╨░╤Б╤В╨╛╤П╤Й╨╡╨╡ ╨╝╨╡╤Б╤В╨╛ ╤Б╨╡╨║╤А╨╡╤В╨░ тАФ ╤Б╨╡╨░╨╜╤Б ╨▓ store/settingsStore.ts, ╨║╤Г╨┤╨░ ╨╡╨│╨╛ ╨▓╨▓╨╛╨┤╨╕╤В
				 * ╨░╨┤╨╝╨╕╨╜╨╕╤Б╤В╤А╨░╤В╨╛╤А ╨╜╨░ ╤Н╨║╤А╨░╨╜╨╡ ╤А╨░╨╖╨▒╨╗╨╛╨║╨╕╤А╨╛╨▓╨║╨╕; ╨╛╤В╤В╤Г╨┤╨░ ╨╢╨╡ ╨╡╨│╨╛ ╨▒╨╡╤А╤С╤В
				 * hooks/domains/useAuthLogic.ts (`adminSecretOverride ?? clinicalAdminSecretSession`).
				 */
				const secret = clinicalAdminSecretSession.trim() || undefined;
				const headers = denteAdminSecretRequestHeaders(
					{ "Content-Type": "application/json" },
					secret,
				);

				const response = await fetch("/api/speech/transcribe-chunk", {
					method: "POST",
					headers,
					body: JSON.stringify(input),
				});

				const payload = await response.json();

				if (!response.ok || payload.chunk?.status === "failed") {
					throw new Error(
						operatorReadableErrorDetail(payload.message || payload.error) ||
							"╨Ю╤И╨╕╨▒╨║╨░ ╤Б╨╡╤А╨▓╨╡╤А╨░",
					);
				}

				if (payload.chunk?.transcript) {
					onResult(payload.chunk.transcript);
				} else {
					showToast("╨Э╨╡ ╤Г╨┤╨░╨╗╨╛╤Б╤М ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╤В╤М ╤А╨╡╤З╤М", "warning");
				}
			} catch (err: any) {
				logger.error("Server STT Error:", err);
				showToast(
					"╨б╨▒╨╛╨╣ ╤Б╨╡╤А╨▓╨╡╤А╨░ ╤А╨░╤Б╨┐╨╛╨╖╨╜╨░╨▓╨░╨╜╨╕╤П. ╨Я╨╡╤А╨╡╨║╨╗╤О╤З╨░╨╡╨╝ ╨╜╨░ ╨▓╨▓╨╛╨┤ ╤В╨╡╨║╤Б╤В╨╛╨╝.",
					"error",
				);
			} finally {
				setIsProcessing(false);
			}
		},
		[context, dashboard, onResult, clinicalAdminSecretSession.trim],
	);

	const toggleRecording = useCallback(async () => {
		if (isRecording) {
			if (
				mediaRecorderRef.current &&
				mediaRecorderRef.current.state === "recording"
			) {
				mediaRecorderRef.current.stop();
			}
			return;
		}

		if (!navigator.onLine || !speechGatewayStatus?.serverTranscriptionEnabled) {
			startBrowserNative();
			return;
		}

		try {
			const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
			streamRef.current = stream;
			const mediaRecorder = new MediaRecorder(stream);
			mediaRecorderRef.current = mediaRecorder;
			audioChunksRef.current = [];

			mediaRecorder.ondataavailable = (e) => {
				if (e.data.size > 0) {
					audioChunksRef.current.push(e.data);
				}
			};

			mediaRecorder.onstop = () => {
				setIsRecording(false);
				cleanupStream();
				const audioBlob = new Blob(audioChunksRef.current, {
					type: mediaRecorder.mimeType,
				});
				if (audioBlob.size > 0) {
					sendToServer(audioBlob);
				}
			};

			mediaRecorder.start();
			setIsRecording(true);

			setTimeout(() => {
				if (mediaRecorder.state === "recording") {
					mediaRecorder.stop();
				}
			}, 10000);
		} catch (err) {
			showToast(
				actionFailureToast(
					"╨Ю╤И╨╕╨▒╨║╨░ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜╨╕╤П ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╕",
					(err as { status?: number })?.status ?? null,
				),
				"error",
			);
			logger.error("Microphone access denied or error:", err);
			startBrowserNative();
		}
	}, [
		isRecording,
		speechGatewayStatus,
		startBrowserNative,
		sendToServer,
		cleanupStream,
	]);

	return {
		isRecording,
		isProcessing,
		toggleRecording,
	};
}

