		} catch (err) {
			showToast(
				actionFailureToast(
					"╨Ю╤И╨╕╨▒╨║╨░ ╨▓╤Л╨┐╨╛╨╗╨╜╨╡╨╜╨╕╤П ╨╛╨┐╨╡╤А╨░╤Ж╨╕╨╕",
					(err as { status?: number })?.status ?? null,
				),
				"error",
			);
			console.error("Failed to start listening:", err);
			setIsListening(false);
			playBeep("error");
		}
	}, [
		isListening,
		updateVolume,
		speechGatewayStatus,
		startBrowserNative,
		processAudioOnServer,
		playBeep,
	]);

