describe("inspectBrowserContinuity", () => {
	test("adds warning when navigator.storage.estimate throws an error", async () => {
		const originalWindowDescriptor = Object.getOwnPropertyDescriptor(
			globalThis,
			"window",
		);
		const originalNavigatorDescriptor = Object.getOwnPropertyDescriptor(
			globalThis,
			"navigator",
		);

		try {
			Object.defineProperty(globalThis, "window", {
				value: {},
				configurable: true,
				writable: true,
			});

			Object.defineProperty(globalThis, "navigator", {
				value: {
					storage: {
						estimate: async () => {
							throw new Error("Simulated storage estimate error");
						},
					},
				},
				configurable: true,
				writable: true,
			});

			const status = await inspectBrowserContinuity();

			assert.ok(
				status.warnings.includes("╨Ю╤Ж╨╡╨╜╨║╨░ ╤Е╤А╨░╨╜╨╕╨╗╨╕╤Й╨░ ╨▒╤А╨░╤Г╨╖╨╡╤А╨░ ╨╜╨╡╨┤╨╛╤Б╤В╤Г╨┐╨╜╨░"),
			);
		} finally {
			if (originalWindowDescriptor) {
				Object.defineProperty(globalThis, "window", originalWindowDescriptor);
			} else {
				delete (globalThis as any).window;
			}
			if (originalNavigatorDescriptor) {
				Object.defineProperty(
					globalThis,
					"navigator",
					originalNavigatorDescriptor,
				);
			} else {
				delete (globalThis as any).navigator;
			}
		}
	});
});

describe("formatMegabytes", () => {
	test('returns "╨╜/╨┤" when value is null', () => {
		assert.strictEqual(formatMegabytes(null), "╨╜/╨┤");
	});

	test("formats regular integers correctly with ru-RU locale", () => {
		assert.strictEqual(formatMegabytes(0), "0 ╨Ь╨С");
		assert.strictEqual(formatMegabytes(10), "10 ╨Ь╨С");
		assert.strictEqual(formatMegabytes(999), "999 ╨Ь╨С");
	});

	test("formats numbers > 999 with thousand separators", () => {
		// Check against dynamically generated localized strings for cross-environment resilience
		assert.strictEqual(
			formatMegabytes(1000),
			`${(1000).toLocaleString("ru-RU")} ╨Ь╨С`,
		);
		assert.strictEqual(
			formatMegabytes(1234567),
			`${(1234567).toLocaleString("ru-RU")} ╨Ь╨С`,
		);
	});

	test("formats negative numbers", () => {
		assert.strictEqual(formatMegabytes(-5), "-5 ╨Ь╨С");
		assert.strictEqual(
			formatMegabytes(-1000),
			`${(-1000).toLocaleString("ru-RU")} ╨Ь╨С`,
		);
	});

	test("formats decimal numbers", () => {
		assert.strictEqual(formatMegabytes(1.5), "1,5 ╨Ь╨С");
		assert.strictEqual(
			formatMegabytes(1234.56),
			`${(1234.56).toLocaleString("ru-RU")} ╨Ь╨С`,
		);
	});
});

describe("formatByteSize", () => {
	test('returns "╨╜/╨┤" for non-numbers, null, and undefined', () => {
		assert.strictEqual(formatByteSize(null), "╨╜/╨┤");
		assert.strictEqual(formatByteSize(undefined), "╨╜/╨┤");
		assert.strictEqual(formatByteSize("100" as any), "╨╜/╨┤");
	});

	test('returns "╨╜/╨┤" for non-finite numbers', () => {
		assert.strictEqual(formatByteSize(Infinity), "╨╜/╨┤");
		assert.strictEqual(formatByteSize(-Infinity), "╨╜/╨┤");
		assert.strictEqual(formatByteSize(NaN), "╨╜/╨┤");
	});

	test('returns "0 ╨Ь╨С" for 0 or negative values', () => {
		assert.strictEqual(formatByteSize(0), "0 ╨Ь╨С");
		assert.strictEqual(formatByteSize(-100), "0 ╨Ь╨С");
		assert.strictEqual(formatByteSize(-1024 * 1024), "0 ╨Ь╨С");
	});

	test('returns "<0,1 ╨Ь╨С" for values between 0 and 0.1 MB (exclusive)', () => {
		assert.strictEqual(formatByteSize(1), "<0,1 ╨Ь╨С");
		assert.strictEqual(formatByteSize(1024), "<0,1 ╨Ь╨С");
		// 0.099 MB
		assert.strictEqual(formatByteSize(0.099 * 1024 * 1024), "<0,1 ╨Ь╨С");
	});

	test("formats values >= 0.1 MB correctly rounded to 1 decimal place", () => {
		// 0.1 MB -> 0,1 ╨Ь╨С
		assert.strictEqual(formatByteSize(0.1 * 1024 * 1024), "0,1 ╨Ь╨С");
		// 0.15 MB -> 0.2 MB (rounded) -> 0,2 ╨Ь╨С
		assert.strictEqual(formatByteSize(0.15 * 1024 * 1024), "0,2 ╨Ь╨С");
		// 1 MB -> 1 ╨Ь╨С
		assert.strictEqual(formatByteSize(1 * 1024 * 1024), "1 ╨Ь╨С");
		// 1.5 MB -> 1,5 ╨Ь╨С
		assert.strictEqual(formatByteSize(1.5 * 1024 * 1024), "1,5 ╨Ь╨С");
	});

	test("formats large values using ru-RU locale formatting", () => {
		// 1234.5 MB -> 1 234,5 ╨Ь╨С
		assert.strictEqual(
			formatByteSize(1234.5 * 1024 * 1024),
			`${(1234.5).toLocaleString("ru-RU")} ╨Ь╨С`,
		);
		// 99999.9 MB -> 99 999,9 ╨Ь╨С
		assert.strictEqual(
			formatByteSize(99999.94 * 1024 * 1024),
			`${(99999.9).toLocaleString("ru-RU")} ╨Ь╨С`,
		);
	});
});

describe("browserIndexedDbWritable", () => {
	const originalWindow = global.window;

	afterEach(() => {
		global.window = originalWindow;
	});

	test("returns false when window is undefined", async () => {
		global.window = undefined as any;
		assert.strictEqual(await browserIndexedDbWritable(), false);
	});

	test("returns false when indexedDB is not in window", async () => {
		global.window = {} as any;
		assert.strictEqual(await browserIndexedDbWritable(), false);
	});

	test("returns false when indexedDB open triggers onerror", async () => {
		global.window = {
			indexedDB: {
				open: (_name: string, _version: number) => {
					const request: any = {};
					setTimeout(() => {
						if (request.onerror) {
							request.error = new Error("Simulated IndexedDB error");
							request.onerror();
						}
					}, 0);
					return request;
				},
			},
		} as any;

		assert.strictEqual(await browserIndexedDbWritable(), false);
	});

	test("returns true when indexedDB operations succeed", async () => {
		global.window = {
			indexedDB: {
				open: (_name: string, _version: number) => {
					const request: any = {};
					setTimeout(() => {
						if (request.onsuccess) {
							request.result = {
								close: () => {},
							};
							request.onsuccess();
						}
					}, 0);
					return request;
				},
				deleteDatabase: (_name: string) => {},
			},
		} as any;

		const result = await browserIndexedDbWritable();
		assert.strictEqual(result, true);
	});
});

