 * ╨║╨░╨║╨╕╨╡ ╤П ╨┐╨╛╨╝╨╜╨╕╨╗, ╨║╨╛╨│╨┤╨░ ╨┐╨╕╤Б╨░╨╗ ╤В╨╡╤Б╤В┬╗.
 */
const ALL_MODES: readonly ClinicMode[] = clinicModes;

test("╨┐╨╡╤А╨╡╤З╨╕╤Б╨╗╨╡╨╜╨╕╨╡ ╤А╨╡╨╢╨╕╨╝╨╛╨▓ ╨╜╨╡ ╤А╨░╤Б╤Е╨╛╨┤╨╕╤В╤Б╤П ╤Б╨╛ ╤Б╤Е╨╡╨╝╨╛╨╣ ╤Б╨╡╤А╨▓╨╡╤А╨░", () => {
	/*
	 * ╨Т ╤Н╤В╨╛╨╝ ╤Д╨░╨╣╨╗╨╡ ╨╗╨╡╨╢╨░╨╗╨░ ╤Б╨▓╨╛╤П ╨║╨╛╨┐╨╕╤П ╨╛╨▒╤К╨╡╨┤╨╕╨╜╨╡╨╜╨╕╤П ╨╕╨╖ ╤З╨╡╤В╤Л╤А╤С╤Е ╤Б╤В╤А╨╛╨║, ╨░ ╤А╤П╨┤╨╛╨╝ тАФ ╨╡╤Й╤С
	 * ╨╛╨┤╨╕╨╜ ╤В╨░╨║╨╛╨╣ ╨╢╨╡ ╤Б╨┐╨╕╤Б╨╛╨║ ╨┤╨╗╤П ╨┐╤А╨╛╨▓╨╡╤А╨║╨╕ ╤З╤Г╨╢╨╛╨│╨╛ ╨╖╨╜╨░╤З╨╡╨╜╨╕╤П. ╨Э╨░╤Б╤В╨╛╤П╤Й╨╡╨╡ ╨┐╨╡╤А╨╡╤З╨╕╤Б╨╗╨╡╨╜╨╕╨╡
	 * ╨┐╤А╨╕ ╤Н╤В╨╛╨╝ ╨╢╨╕╨▓╤С╤В ╨▓ packages/shared (clinicModeSchema), ╨╕ ╨┐╨╛ ╨╜╨╡╨╝╤Г ╤Б╨╡╤А╨▓╨╡╤А
	 * ╤А╨░╨╖╨▒╨╕╤А╨░╨╡╤В ╨║╨╛╨╗╨╛╨╜╨║╤Г organizations.clinic_mode. ╨в╤А╨╕ ╨║╨╛╨┐╨╕╨╕ ╨╛╨┤╨╜╨╛╨│╨╛ ╨┐╨╡╤А╨╡╤З╨╕╤Б╨╗╨╡╨╜╨╕╤П
	 * ╤А╨░╤Б╤Е╨╛╨┤╤П╤В╤Б╤П ╨╝╨╛╨╗╤З╨░: ╤А╤Г╨║╨╛╨┐╨╕╤Б╨╜╨░╤П ╨║╨╛╨┐╨╕╤П ╤Б╨┐╨╕╤Б╨║╨░ ╤А╨░╨╖╨┤╨╡╨╗╨╛╨▓ appViews ╨▓ ╤Н╤В╨╛╨╝ ╨┐╤А╨╛╨╡╨║╤В╨╡
	 * ╤Г╨╢╨╡ ╤А╨░╨╖╤К╨╡╤Е╨░╨╗╨░╤Б╤М ╨╕ ╤Г╤А╨╛╨╜╨╕╨╗╨░ ╤Б╨▒╨╛╤А╨║╤Г.
	 */
	assert.deepEqual([...clinicModes], [...clinicModeSchema.options]);
	console.log(`  ╤А╨╡╨╢╨╕╨╝╤Л ╨╕╨╖ ╤Б╤Е╨╡╨╝╤Л ╤Б╨╡╤А╨▓╨╡╤А╨░: ${clinicModes.join(", ")}`);
	for (const mode of clinicModeSchema.options) {
		assert.equal(
			resolveClinicMode(mode),
			mode,
			`╤А╨╡╨╢╨╕╨╝ ${mode} ╨╜╨╡ ╨┐╤А╨╕╨╖╨╜╨░╨╜ ╤Б╨▓╨╛╨╕╨╝`,
		);
		assert.ok(
			clinicCapabilities(mode).length > 0,
			`${mode}: ╨┐╤Г╤Б╤В╨╛╨╣ ╨╜╨░╨▒╨╛╤А ╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╨╡╨╣`,
		);
		assert.ok(
			visibleStaffRoles(
				["doctor", "administrator", "assistant", "manager", "owner"],
				mode,
			).length > 0,
			`${mode}: ╨╜╨╕ ╨╛╨┤╨╜╨╛╨╣ ╤А╨╛╨╗╨╕`,
		);
	}
});

