test("╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╨╝╤Г ╨▓╤А╨░╤З╤Г ╨╜╨╡ ╨┐╨╛╨║╨░╨╖╤Л╨▓╨░╤О╤В╤Б╤П ╤А╨░╤Б╤Б╤Л╨╗╨║╨╕ ╨┐╨╛ ╨▒╨░╨╖╨╡", () => {
	// ╨Х╨│╨╛ ╤А╨╡╨╢╨╕╨╝ ╨╛╨┐╨╕╤Б╨░╨╜ ╨▓ ╨╕╨╜╤В╨╡╤А╤Д╨╡╨╣╤Б╨╡ ╨║╨░╨║ ┬л╨╝╨╕╨╜╨╕╨╝╤Г╨╝ ╤Н╨║╤А╨░╨╜╨╛╨▓┬╗. ╨Ь╨░╤А╨║╨╡╤В╨╕╨╜╨│╨░ ╤Г ╨╜╨╡╨│╨╛ ╨╜╨╡╤В,
	// ╨░ ╨╗╨╕╤И╨╜╨╕╨╣ ╤А╨░╨╖╨┤╨╡╨╗ ╤Б╤В╨╛╨╕╤В ╨┤╨╛╤А╨╛╨╢╨╡ ╨╛╤В╤Б╤Г╤В╤Б╤В╨▓╤Г╤О╤Й╨╡╨╣ ╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╨╕.
