test("╨╜╨╡╨╕╨╖╨▓╨╡╤Б╤В╨╜╤Л╨╣ ╤А╨╡╨╢╨╕╨╝ ╨╜╨╡ ╨╛╤В╨╜╨╕╨╝╨░╨╡╤В ╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╨╡╨╣", () => {
	// ╨б╨┐╤А╤П╤В╨░╤В╤М ╤А╨░╨╖╨┤╨╡╨╗ ╤Г ╨║╨╗╨╕╨╜╨╕╨║╨╕, ╨║╨╛╤В╨╛╤А╨░╤П ╨╡╤Й╤С ╨╜╨╡ ╨┐╤А╨╛╤И╨╗╨░ ╨╜╨░╤Б╤В╤А╨╛╨╣╨║╤Г, ╨╖╨╜╨░╤З╨╕╤В ╨╛╤В╨╜╤П╤В╤М
	// ╤А╨░╨▒╨╛╤В╨░╤О╤Й╤Г╤О ╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╤М ╨▒╨╡╨╖ ╨╛╨▒╤К╤П╤Б╨╜╨╡╨╜╨╕╤П. ╨Ы╨╕╤И╨╜╨╕╨╣ ╤А╨░╨╖╨┤╨╡╨╗ ╨╖╨░╨╝╨╡╤В╤П╤В ╨╕ ╨╜╨░╤Б╤В╤А╨╛╤П╤В,
	// ╨┐╤А╨╛╨┐╨░╨▓╤И╨╕╨╣ ╨▒╤Г╨┤╤Г╤В ╨╕╤Б╨║╨░╤В╤М.
	const capabilities: ClinicCapability[] = [
		"callList",
		"messaging",
		"massCampaigns",
		"managerReports",
		"doctorBreakdown",
		"chairUtilisation",
	];
	for (const capability of capabilities) {
		assert.equal(
			hasCapability(null, capability),
			true,
			`null: ╨╜╨╡╤В ${capability}`,
		);
		assert.equal(
			hasCapability(undefined, capability),
			true,
			`undefined: ╨╜╨╡╤В ${capability}`,
		);
		// ╨Ч╨╜╨░╤З╨╡╨╜╨╕╨╡ ╨╕╨╖ ╤Б╤В╨░╤А╨╛╨╣ ╨╖╨░╨┐╨╕╤Б╨╕ ╨▓ ╨▒╨░╨╖╨╡, ╨║╨╛╤В╨╛╤А╨╛╨│╨╛ ╨╜╨╡╤В ╨▓ ╨┐╨╡╤А╨╡╤З╨╕╤Б╨╗╨╡╨╜╨╕╨╕.
		assert.equal(
			hasCapability("legacy_mode" as ClinicMode, capability),
			true,
			`╨╜╨╡╨╕╨╖╨▓╨╡╤Б╤В╨╜╤Л╨╣ ╤А╨╡╨╢╨╕╨╝: ╨╜╨╡╤В ${capability}`,
		);
	}
});

test("╨╜╨░╨▒╨╛╤А ╨▓╨╛╨╖╨╝╨╛╨╢╨╜╨╛╤Б╤В╨╡╨╣ ╤А╨░╤Б╤В╤С╤В ╨╛╤В ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╨│╨╛ ╨▓╤А╨░╤З╨░ ╨║ ╤Б╨╡╤В╨╕", () => {
	// ╨б╨▓╨╛╨╣╤Б╤В╨▓╨╛ ╤В╨░╨▒╨╗╨╕╤Ж╤Л: ╤З╨╡╨╝ ╨║╤А╤Г╨┐╨╜╨╡╨╡ ╨║╨╗╨╕╨╜╨╕╨║╨░, ╤В╨╡╨╝ ╨▒╨╛╨╗╤М╤И╨╡ ╨┤╨╛╤Б╤В╤Г╨┐╨╜╨╛. ╨Э╨░╤А╤Г╤И╨╡╨╜╨╕╨╡
	// ╨╛╨╖╨╜╨░╤З╨░╨╡╤В, ╤З╤В╨╛ ╨│╨┤╨╡-╤В╨╛ ╨▓ ╨┐╤А╨░╨▓╨╕╨╗╨░╤Е ╨╛╨┐╨╡╤З╨░╤В╨║╨░.
	const sizes = ALL_MODES.map((mode) => clinicCapabilities(mode).length);
	for (let index = 1; index < sizes.length; index += 1) {
		const previous = sizes[index - 1] ?? 0;
		const current = sizes[index] ?? 0;
		assert.ok(
			current >= previous,
			`${ALL_MODES[index]} ╨┤╨╛╤Б╤В╤Г╨┐╨╜╨╛ ╨╝╨╡╨╜╤М╤И╨╡, ╤З╨╡╨╝ ${ALL_MODES[index - 1]}`,
		);
	}
});

