test("╤А╨░╨╖╨┤╨╡╨╗ ╨┐╤А╨╛╨┤╨▓╨╕╨╢╨╡╨╜╨╕╤П ╤Б╨║╤А╤Л╤В ╤В╨╛╨╗╤М╨║╨╛ ╤Г ╨╛╤В╨┤╨╡╨╗╤М╨╜╨╛╨│╨╛ ╨▓╤А╨░╤З╨░", () => {
