/** ╨б╨▓╨╡╨╢╨░╤П ╤Б╤Б╤Л╨╗╨║╨░ `useRef` ╤Б╨╝╨╛╨╜╤В╨╕╤А╨╛╨▓╨░╨╜╨╜╨╛╨│╨╛ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А╨░ ╤Н╤Д╤Д╨╡╨║╤В╨░. */
function mountComposerEffect(): TrackedComposerPatientRef {
	return { current: PAYMENT_COMPOSER_PATIENT_UNTRACKED };
}

/**
 * ╨Я╤А╨╛╨│╨╛╨╜╤П╨╡╤В ╨╛╨┤╨╕╨╜ ╤Б╨╝╨╛╨╜╤В╨╕╤А╨╛╨▓╨░╨╜╨╜╤Л╨╣ ╤Н╨║╨╖╨╡╨╝╨┐╨╗╤П╤А ╤Н╤Д╤Д╨╡╨║╤В╨░ ╨┐╨╛ ╨┐╨╛╤Б╨╗╨╡╨┤╨╛╨▓╨░╤В╨╡╨╗╤М╨╜╨╛╤Б╤В╨╕
 * ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╣ `documentPatient?.id` ╨╕ ╨▓╨╛╨╖╨▓╤А╨░╤Й╨░╨╡╤В ╤З╨╕╤Б╨╗╨╛ ╨╜╨░╤Б╤В╨╛╤П╤Й╨╕╤Е ╤Б╨▒╤А╨╛╤Б╨╛╨▓.
 *
 * ╨а╨╡╤И╨╡╨╜╨╕╨╡ ╨╛ ╤Б╨▒╤А╨╛╤Б╨╡ ╨┐╤А╨╕╨╜╨╕╨╝╨░╨╡╤В ╨▒╨╛╨╡╨▓╨░╤П `resetPaymentComposerOnPatientChange` тАФ
 * ╨╖╨┤╨╡╤Б╤М ╨╜╨╡ ╨┐╨╡╤А╨╡╤Б╨║╨░╨╖ ╨╡╤С ╨╗╨╛╨│╨╕╨║╨╕, ╨░ ╨╡╤С ╨╕╤Б╨┐╨╛╨╗╨╜╨╡╨╜╨╕╨╡. ╨Я╨╡╤А╨▓╨╛╨╡ ╨╖╨╜╨░╤З╨╡╨╜╨╕╨╡
 * ╨┐╨╛╤Б╨╗╨╡╨┤╨╛╨▓╨░╤В╨╡╨╗╤М╨╜╨╛╤Б╤В╨╕ тАФ ╨╝╨╛╨╜╤В╨╕╤А╨╛╨▓╨░╨╜╨╕╨╡. ╨б╨╜╤П╤В╨╕╨╡ ╨▓╤Л╨▒╨╛╤А╨░ ╨┐╨░╤Ж╨╕╨╡╨╜╤В╨░ ╨┐╨╡╤А╨╡╨┤╨░╤С╤В╤Б╤П ╨║╨░╨║
 * `undefined`, ╨║╨░╨║ ╨╡╨│╨╛ ╨╕ ╨╛╤В╨┤╨░╤С╤В `documentPatient?.id`.
 */
function applyPatientSwitches(
	store: ReturnType<typeof makeStore>,
	patientIds: readonly (string | undefined)[],
	effect: TrackedComposerPatientRef = mountComposerEffect(),
): number {
	let resets = 0;
	for (const patientId of patientIds) {
		if (resetPaymentComposerOnPatientChange(effect, patientId, store.setters)) {
			resets += 1;
		}
	}
	return resets;
}

