		);
		assert.ok(
			!LOOKS_LIKE_AN_INSTANT.test(fromMoscow),
			`╨▓ ╨░╨┤╤А╨╡╤Б ╤Б╨▓╨╛╨┤╨║╨╕ ╨▓╨╡╤А╨╜╤Г╨╗╨╛╤Б╤М ╨╝╨│╨╜╨╛╨▓╨╡╨╜╨╕╨╡ ╨▓╨╝╨╡╤Б╤В╨╛ ╨║╨░╨╗╨╡╨╜╨┤╨░╤А╨╜╨╛╨╣ ╨┤╨░╤В╤Л: ${fromMoscow}`,
		);
