}

/**
 * ╨Ъ╨╛╨┤ ╨▒╨╡╨╖ ╨║╨╛╨╝╨╝╨╡╨╜╤В╨░╤А╨╕╨╡╨▓. ╨Я╨╛╤А╤П╨┤╨╛╨║ ╤В╨╛╤В ╨╢╨╡, ╤З╤В╨╛ ╨▓ documentsViewDecomposition.test.ts,
 * ╨╕ ╨┐╨╛ ╤В╨╛╨╣ ╨╢╨╡ ╨┐╤А╨╕╤З╨╕╨╜╨╡: ╤Б╤В╤А╨╛╤З╨╜╤Л╨╡ ╨║╨╛╨╝╨╝╨╡╨╜╤В╨░╤А╨╕╨╕ ╤Б╨╜╨╕╨╝╨░╤О╤В╤Б╤П ╤А╨░╨╜╤М╤И╨╡ ╨▒╨╗╨╛╤З╨╜╤Л╤Е, ╨╕╨╜╨░╤З╨╡
 * ╨┐╨╛╤Б╨╗╨╡╨┤╨╛╨▓╨░╤В╨╡╨╗╤М╨╜╨╛╤Б╤В╤М `/*` ╨▓╨╜╤Г╤В╤А╨╕ ╤Б╤В╤А╨╛╤З╨╜╨╛╨│╨╛ ╨║╨╛╨╝╨╝╨╡╨╜╤В╨░╤А╨╕╤П ╤Б╤К╨╡╨┤╨░╨╡╤В ╨╢╨╕╨▓╨╛╨╣ ╨║╨╛╨┤ ╨┤╨╛
 * ╨▒╨╗╨╕╨╢╨░╨╣╤И╨╡╨╣ ╨╖╨░╨║╤А╤Л╨▓╨░╤О╤Й╨╡╨╣. ╨С╨╡╨╖ ╤Н╤В╨╛╨│╨╛ ╤И╨░╨│╨░ ╨┐╤А╨╛╨▓╨╡╤А╨║╨░ ╨║╤А╨░╤Б╨╜╨╡╨╗╨░ ╨╜╨░ ╤А╨░╨╖╨▒╨╛╤А╨╡ ╨┤╨╡╤Д╨╡╨║╤В╨░,
 * ╨╖╨░╨┐╨╕╤Б╨░╨╜╨╜╨╛╨╝ ╨▓ ╨║╨╛╨╝╨╝╨╡╨╜╤В╨░╤А╨╕╨╕, тАФ ╤В╨╛ ╨╡╤Б╤В╤М ╨╜╨░ ╤Б╨╛╨▒╤Б╤В╨▓╨╡╨╜╨╜╨╛╨╝ ╨╛╨▒╤К╤П╤Б╨╜╨╡╨╜╨╕╨╕.
 */
function withoutComments(source: string): string {
	return source
		.split(/\r?\n/)
		.filter(
			(line) =>
				!line.trimStart().startsWith("//") && !line.trimStart().startsWith("*"),
		)
		.join("\n")
		.replace(/\/\*[\s\S]*?\*\//g, " ");
}

function webSourceFiles(): string[] {
	const found: string[] = [];
	const walk = (dir: string) => {
		for (const entry of readdirSync(dir)) {
			const full = join(dir, entry);
			if (statSync(full).isDirectory()) {
				if (entry === "tests" || entry === "node_modules") continue;
				walk(full);
				continue;
			}
			if (/\.tsx?$/.test(entry)) found.push(full);
		}
	};
	walk(webSrc);
	return found;
}

