import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { normalizeDentalSlang } from "../lib/stringUtils.js";

describe("normalizeDentalSlang", () => {
	it("should map slang words with fallback quadrant '1' when no context is provided", () => {
		assert.equal(normalizeDentalSlang("╤И╨╡╤Б╤В╨╡╤А╨║╨░"), "16");
		assert.equal(normalizeDentalSlang("╨╡╨┤╨╕╨╜╨╕╤З╨║╨░"), "11");
		assert.equal(normalizeDentalSlang("╨┤╨▓╨╛╨╣╨║╨░"), "12");
	});

	it("should apply explicit quadrant context (both upper/lower and left/right)", () => {
		assert.equal(
			normalizeDentalSlang("╨▓╨╡╤А╤Е╨╜╤П╤П ╨╗╨╡╨▓╨░╤П ╤И╨╡╤Б╤В╨╡╤А╨║╨░"),
			"╨▓╨╡╤А╤Е╨╜╤П╤П ╨╗╨╡╨▓╨░╤П 26",
		);
		assert.equal(
			normalizeDentalSlang("╨▓╨╡╤А╤Е╨╜╤П╤П ╨┐╤А╨░╨▓╨░╤П ╨┤╨▓╨╛╨╣╨║╨░"),
			"╨▓╨╡╤А╤Е╨╜╤П╤П ╨┐╤А╨░╨▓╨░╤П 12",
		);
		assert.equal(
			normalizeDentalSlang("╨╜╨╕╨╢╨╜╤П╤П ╨╗╨╡╨▓╨░╤П ╨▓╨╛╤Б╤М╨╝╨╡╤А╨║╨░"),
			"╨╜╨╕╨╢╨╜╤П╤П ╨╗╨╡╨▓╨░╤П 38",
		);
		assert.equal(
			normalizeDentalSlang("╨╜╨╕╨╢╨╜╤П╤П ╨┐╤А╨░╨▓╨░╤П ╤В╤А╨╛╨╣╨║╨░"),
			"╨╜╨╕╨╢╨╜╤П╤П ╨┐╤А╨░╨▓╨░╤П 43",
		);
	});

	it("should apply explicit single quadrant context", () => {
		assert.equal(normalizeDentalSlang("╨▓╨╡╤А╤Е╨╜╤П╤П ╤И╨╡╤Б╤В╨╡╤А╨║╨░"), "╨▓╨╡╤А╤Е╨╜╤П╤П 16");
		assert.equal(normalizeDentalSlang("╨╜╨╕╨╢╨╜╤П╤П ╤И╨╡╤Б╤В╨╡╤А╨║╨░"), "╨╜╨╕╨╢╨╜╤П╤П 46");
		assert.equal(normalizeDentalSlang("╨┐╤А╨░╨▓╨░╤П ╤И╨╡╤Б╤В╨╡╤А╨║╨░"), "╨┐╤А╨░╨▓╨░╤П 16");
		assert.equal(normalizeDentalSlang("╨╗╨╡╨▓╨░╤П ╤И╨╡╤Б╤В╨╡╤А╨║╨░"), "╨╗╨╡╨▓╨░╤П 26");
	});

	it("should process pure digits accompanied by quadrant words", () => {
		assert.equal(normalizeDentalSlang("╨▓╨╡╤А╤Е╨╜╨╕╨╣ ╨╗╨╡╨▓╤Л╨╣ 6"), "╨▓╨╡╤А╤Е╨╜╨╕╨╣ ╨╗╨╡╨▓╤Л╨╣ 26");
		assert.equal(normalizeDentalSlang("╨╜╨╕╨╢╨╜╤П╤П ╨┐╤А╨░╨▓╨░╤П 3"), "╨╜╨╕╨╢╨╜╤П╤П ╨┐╤А╨░╨▓╨░╤П 43");
