/** ╨в╨╛╨╗╤М╨║╨╛ ╨║╨╛╤А╨╜╨╡╨▓╤Л╨╡ ╤Б╨╡╨╗╨╡╨║╤В╨╛╤А╤Л ╨┐╨░╨╗╨╕╤В╤А╤Л: html, :root, .╨║╨╗╨░╤Б╤Б, [╨░╤В╤А╨╕╨▒╤Г╤В] ╨╕ ╨╕╤Е ╤Б╤Ж╨╡╨┐╨║╨╕. */
const ROOT_SELECTOR = /^(?:html|:root|\.[\w-]+|\[[^\]]*\])+$/;

type Specificity = readonly [number, number];

function rootSelectorMatch(selector: string, theme: Theme): Specificity | null {
	if (!ROOT_SELECTOR.test(selector)) return null;
	let specificity: Specificity = [0, 0];
	for (const part of selector.match(/html|:root|\.[\w-]+|\[[^\]]*\]/g) ?? []) {
		if (part === "html") {
			specificity = [specificity[0], specificity[1] + 1];
			continue;
		}
		if (part === ":root") {
			specificity = [specificity[0] + 1, specificity[1]];
			continue;
		}
		if (part.startsWith(".")) {
			// ╨Ъ╨╗╨░╤Б╤Б ╤В╨╡╨╝╤Л ╨╜╨░ <html> ╤Б╤В╨░╨▓╨╕╤В ThemeController; ╨╖╨┤╨╡╤Б╤М ╤Б╤З╨╕╤В╨░╨╡╤В╤Б╤П ╤В╨╛╨╗╤М╨║╨╛ ╨░╤В╤А╨╕╨▒╤Г╤В,
			// ╨┐╨╛╤Н╤В╨╛╨╝╤Г ╨╗╤О╨▒╨╛╨╣ ╨║╨╗╨░╤Б╤Б ╨┤╨╡╨╗╨░╨╡╤В ╤Б╨╡╨╗╨╡╨║╤В╨╛╤А ╨╜╨╡╨┐╨╛╨┤╤Е╨╛╨┤╤П╤Й╨╕╨╝ ╨┤╨╗╤П ╤З╨╕╤Б╤В╨╛╨│╨╛ ╤Б╨╛╤Б╤В╨╛╤П╨╜╨╕╤П ╤В╨╡╨╝╤Л.
			return null;
		}
		const attribute = /^\[data-theme=["']?([\w-]+)["']?\]$/.exec(part);
		if (!attribute || attribute[1] !== theme) return null;
		specificity = [specificity[0] + 1, specificity[1]];
	}
	return specificity;
}

type TokenDeclaration = {
	readonly selectors: readonly string[];
	readonly value: string;
	readonly order: number;
};

/** ╨Ш╨╜╨┤╨╡╨║╤Б ┬л╨╕╨╝╤П ╤В╨╛╨║╨╡╨╜╨░ -> ╨▓╤Б╨╡ ╨╡╨│╨╛ ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜╨╕╤П ╨▓ ╨┐╨╛╤А╤П╨┤╨║╨╡ ╨║╨░╤Б╨║╨░╨┤╨░┬╗ ╤Б╤В╤А╨╛╨╕╤В╤Б╤П ╨╛╨┤╨╕╨╜ ╤А╨░╨╖. */
const declarationsOf = ((): Map<string, TokenDeclaration[]> => {
	const index = new Map<string, TokenDeclaration[]>();
	let order = 0;
	for (const file of STYLESHEETS) {
		for (const rule of rulesOf.get(file) ?? []) {
			for (const declaration of rule.body.split(";")) {
				const colon = declaration.indexOf(":");
				if (colon < 0) continue;
				const name = declaration.slice(0, colon).trim();
				if (!name.startsWith("--")) continue;
				order += 1;
				const list = index.get(name) ?? [];
				list.push({
					selectors: rule.selectors,
					value: declaration.slice(colon + 1).trim(),
					order,
				});
				index.set(name, list);
			}
		}
	}
	return index;
})();

/** ╨Ч╨╜╨░╤З╨╡╨╜╨╕╨╡ ╤В╨╛╨║╨╡╨╜╨░, ╨║╨╛╤В╨╛╤А╨╛╨╡ ╨┐╨╛╨▒╨╡╨┤╨╕╤В ╨╜╨░ <html> ╨▓ ╤Н╤В╨╛╨╣ ╤В╨╡╨╝╨╡, тАФ ╤В╨░╨║ ╨╢╨╡, ╨║╨░╨║ ╤А╨╡╤И╨░╨╡╤В ╨▒╤А╨░╤Г╨╖╨╡╤А. */
function winningToken(token: string, theme: Theme): string | null {
	let best: { specificity: Specificity; order: number; value: string } | null =
		null;
	for (const declaration of declarationsOf.get(token) ?? []) {
		for (const selector of declaration.selectors) {
			const specificity = rootSelectorMatch(selector, theme);
			if (specificity === null) continue;
			const stronger =
				best === null ||
				specificity[0] > best.specificity[0] ||
				(specificity[0] === best.specificity[0] &&
					(specificity[1] > best.specificity[1] ||
						(specificity[1] === best.specificity[1] &&
							declaration.order >= best.order)));
			if (stronger)
				best = {
					specificity,
					order: declaration.order,
					value: declaration.value,
				};
		}
	}
	return best?.value ?? null;
}

type Rgba = {
	readonly r: number;
	readonly g: number;
	readonly b: number;
	readonly a: number;
};

function parseColor(value: string): Rgba {
	const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(value.trim())?.[1];
	if (hex !== undefined) {
		const digits = hex.length === 3 ? [...hex].map((c) => c + c).join("") : hex;
		return {
			r: Number.parseInt(digits.slice(0, 2), 16),
			g: Number.parseInt(digits.slice(2, 4), 16),
			b: Number.parseInt(digits.slice(4, 6), 16),
			a: 1,
		};
	}
	const rgba =
		/^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)(?:[\s,/]+([\d.]+))?\s*\)$/i.exec(
			value.trim(),
		);
	if (!rgba) throw new Error(`╤Ж╨▓╨╡╤В ╨╜╨╡ ╤А╨░╨╖╨╛╨▒╤А╨░╨╜: ┬л${value}┬╗`);
	const [, r, g, b, a] = rgba;
	if (r === undefined || g === undefined || b === undefined)
		throw new Error(`╤Ж╨▓╨╡╤В ╨╜╨╡ ╤А╨░╨╖╨╛╨▒╤А╨░╨╜: ┬л${value}┬╗`);
	return {
		r: Number(r),
		g: Number(g),
		b: Number(b),
		a: a === undefined ? 1 : Number(a),
	};
}

/** ╨в╨╛╨║╨╡╨╜ -> ╤Ж╨▓╨╡╤В ╤В╨╡╨╝╤Л. ╨Ю╨┤╨╜╨╛ ╨╖╨▓╨╡╨╜╨╛ var() ╤А╨░╨╖╨▓╨╛╤А╨░╤З╨╕╨▓╨░╨╡╤В╤Б╤П: --amber ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜ ╨║╨░╨║ var(--warn-fg). */
function colorOf(token: string, theme: Theme): Rgba {
	const raw = winningToken(token, theme);
	assert.ok(raw, `${token} ╨╜╨╡ ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜ ╨╜╨╕ ╨▓ ╨╛╨┤╨╜╨╛╨╝ ╨╗╨╕╤Б╤В╨╡ ╨┤╨╗╤П ╤В╨╡╨╝╤Л ${theme}`);
	const alias = /^var\(\s*(--[\w-]+)\s*\)$/.exec(raw);
	return parseColor(
		alias?.[1] === undefined ? raw : (winningToken(alias[1], theme) ?? raw),
	);
}

function over(top: Rgba, bottom: Rgba): Rgba {
	return {
		r: top.a * top.r + (1 - top.a) * bottom.r,
		g: top.a * top.g + (1 - top.a) * bottom.g,
		b: top.a * top.b + (1 - top.a) * bottom.b,
		a: 1,
	};
}

const channel = (value: number): number => {
	const scaled = value / 255;
	return scaled <= 0.03928 ? scaled / 12.92 : ((scaled + 0.055) / 1.055) ** 2.4;
};

const luminance = (color: Rgba): number =>
	0.2126 * channel(color.r) +
	0.7152 * channel(color.g) +
	0.0722 * channel(color.b);

function contrast(foreground: Rgba, background: Rgba): number {
	const [high, low] = [luminance(foreground), luminance(background)].sort(
		(a, b) => b - a,
	);
	if (high === undefined || low === undefined)
		throw new Error("╤П╤А╨║╨╛╤Б╤В╤М ╨╜╨╡ ╨┐╨╛╤Б╤З╨╕╤В╨░╨╜╨░");
	return (high + 0.05) / (low + 0.05);
}

