/**
 * ╨Ш╨╝╤П ╤В╨╛╨║╨╡╨╜╨░, ╨║╨╛╤В╨╛╤А╤Л╨╝ ╨┐╤А╨░╨▓╨╕╨╗╨╛ ╤А╨╡╨░╨╗╤М╨╜╨╛ ╨║╤А╨░╤Б╨╕╤В ╤Б╨▓╨╛╨╣╤Б╤В╨▓╨╛. ╨Ъ╨╗╤О╤З╨╡╨▓╨╛╨╣ ╨╝╨╛╨╝╨╡╨╜╤В: ╤Ж╨▓╨╡╤В╨░ ╨▒╨╡╤А╤Г╤В╤Б╤П
 * ╨Ш╨Ч ╨Я╨а╨Р╨Т╨Ш╨Ы╨Р, ╨░ ╨╜╨╡ ╨╕╨╖ ╤Б╨┐╨╕╤Б╨║╨░ ╨▓ ╤В╨╡╤Б╤В╨╡. ╨Ш╨╜╨░╤З╨╡ ╨┐╨╛╨┤╨╝╨╡╨╜╨░ `var(--ink-2)` ╨╛╨▒╤А╨░╤В╨╜╨╛ ╨╜╨░
 * `var(--muted)` ╨▓ CSS ╨╜╨╡ ╤Б╨┤╨▓╨╕╨╜╤Г╨╗╨░ ╨▒╤Л ╨╜╨╕ ╨╛╨┤╨╜╨╛╨│╨╛ ╤З╨╕╤Б╨╗╨░ ╨╖╨┤╨╡╤Б╤М тАФ ╤В╨╡╤Б╤В ╨▒╤Л╨╗ ╨▒╤Л ╤Б╨╗╨╡╨┐╤Л╨╝
 * ╤А╨╛╨▓╨╜╨╛ ╤В╨░╨║ ╨╢╨╡, ╨║╨░╨║ scripts/check-css-tokens.mjs ╤Б╨╗╨╡╨┐ ╨║ ╨│╨╛╨╗╤Л╨╝ ╨╗╨╕╤В╨╡╤А╨░╨╗╨░╨╝.
 */
function tokenOfProperty(
	selector: string,
	properties: readonly string[],
): string {
	// ╨С╨╡╤А╤С╤В╤Б╤П ╨Я╨Ю╨б╨Ы╨Х╨Ф╨Э╨Х╨Х ╨╛╨▒╤К╤П╨▓╨╗╨╡╨╜╨╕╨╡ ╨▓ ╨┐╨╛╤А╤П╨┤╨║╨╡ ╨║╨░╤Б╨║╨░╨┤╨░, ╨░ ╨╜╨╡ ╨┐╨╡╤А╨▓╨╛╨╡: ╤Г ╨╛╨┤╨╜╨╛╨│╨╛ ╨╕ ╤В╨╛╨│╨╛ ╨╢╨╡
	// ╤Б╨╡╨╗╨╡╨║╤В╨╛╤А╨░ ╨▒╤Л╨▓╨░╨╡╤В ╨╜╨╡╤Б╨║╨╛╨╗╤М╨║╨╛ ╨┐╤А╨░╨▓╨╕╨╗, ╨╕ ╨┐╤А╨╕ ╤А╨░╨▓╨╜╨╛╨╣ ╤Б╨┐╨╡╤Ж╨╕╤Д╨╕╤З╨╜╨╛╤Б╤В╨╕ ╨▓╤Л╨╕╨│╤А╤Л╨▓╨░╨╡╤В ╨┐╨╛╨╖╨┤╨╜╨╡╨╡.
	// ╨в╨░╨║, .smart-field input:focus ~ label ╨║╤А╨░╤Б╨╕╤В╤Б╤П var(--brand-600) ╨▓ main.css:16281 ╨╕
	// ╨┐╨╡╤А╨╡╨║╤А╤Л╨▓╨░╨╡╤В╤Б╤П var(--info-fg) ╨▓ contrast-fixes.css:113 тАФ ╤В╨╛╨╗╤М╨║╨╛ ╨┐╨╛╤В╨╛╨╝╤Г, ╤З╤В╨╛
	// contrast-fixes.css ╨╕╨╝╨┐╨╛╤А╤В╨╕╤А╤Г╨╡╤В╤Б╤П ╨┐╨╛╨╖╨╢╨╡ (main.tsx ╤Б╤В╤А╨╛╨║╨░ 21 ╨┐╤А╨╛╤В╨╕╨▓ ╤Б╤В╤А╨╛╨║╨╕ 9).
	let winner: string | null = null;
