		}
	}
	assert.ok(
		winner,
		`╨╜╨╡ ╨╜╨░╨╣╨┤╨╡╨╜╨╛ ╨┐╤А╨░╨▓╨╕╨╗╨╛ ┬л${selector}┬╗ ╤Б╨╛ ╤Б╨▓╨╛╨╣╤Б╤В╨▓╨╛╨╝ ${properties.join("/")}`,
	);
	return winner;
}

/** ╨п╨▓╨╜╨╛╨╡ ╨╕╨╝╤П ╤В╨╛╨║╨╡╨╜╨░ ╨┐╤А╨╛╨┐╤Г╤Б╨║╨░╨╡╤В╤Б╤П ╨║╨░╨║ ╨╡╤Б╤В╤М; ╤Б╨╡╨╗╨╡╨║╤В╨╛╤А тАФ ╤А╨░╨╖╨▓╨╛╤А╨░╤З╨╕╨▓╨░╨╡╤В╤Б╤П ╨▓ ╤В╨╛╨║╨╡╨╜ ╨┐╤А╨░╨▓╨╕╨╗╨░. */
const resolveSide = (
	reference: string,
	properties: readonly string[],
): string =>
	reference.startsWith("--")
		? reference
		: tokenOfProperty(reference, properties);

/** ╨Э╨╛╤А╨╝╨░ WCAG 1.4.3 AA ╨┤╨╗╤П ╨╛╨▒╤Л╤З╨╜╨╛╨│╨╛ ╤В╨╡╨║╤Б╤В╨░. ╨Т╤Б╨╡ ╨┐╤А╨░╨▓╨╕╨╗╨░ ╨▓╤Л╤И╨╡ тАФ 12-16px, ╨║╤А╤Г╨┐╨╜╤Л╨╝╨╕ ╨╜╨╡ ╤Б╤З╨╕╤В╨░╤О╤В╤Б╤П. */
