describe("╨║╨╛╨╜╤В╤А╨░╤Б╤В ╨┐╤А╨░╨▓╨╛╨║ ╤Б╤З╨╕╤В╨░╨╡╤В╤Б╤П ╨┐╨╛ ╨┐╨░╨╗╨╕╤В╤А╨╡, ╨║╨╛╤В╨╛╤А╨░╤П ╨▓╤Л╨╕╨│╤А╤Л╨▓╨░╨╡╤В ╨║╨░╤Б╨║╨░╨┤", () => {
