	test("╨╜╨╛╤З╨╜╨░╤П ╤В╨╡╨╝╨░, ╨║╨╗╨░╤Б╤Б dark ╨╛╤Б╤В╨░╨╗╤Б╤П ╨╜╨░ <html>", () => {
