import assert from "node:assert";
import { describe, test } from "node:test";
import { extractHUZones } from "./boneQualityEngine.js";

describe("extractHUZones", () => {
	test("returns 0 for all zones when array is empty", () => {
		const result = extractHUZones([]);
		assert.deepStrictEqual(result, {
			corticalHU: 0,
			cancellousHU: 0,
			apicalHU: 0,
		});
	});

	test("handles 10 samples correctly (20% cortical, 60% cancellous, 20% apical)", () => {
		// 2 cortical, 6 cancellous, 2 apical
		const samples = [
			1000,
			1000, // cortical: avg 1000
			400,
			500,
			600,
			500,
			400,
			600, // cancellous: sum 3000, avg 500
			800,
			1200, // apical: avg 1000
		];
		const result = extractHUZones(samples);
		assert.deepStrictEqual(result, {
			corticalHU: 1000,
			cancellousHU: 500,
			apicalHU: 1000,
		});
	});

	test("handles 5 samples correctly (1 cortical, 3 cancellous, 1 apical)", () => {
		const samples = [1200, 300, 400, 500, 1000];
		const result = extractHUZones(samples);
		// cortical: 1200
		// cancellous: 300, 400, 500 -> sum 1200, avg 400
		// apical: 1000
		assert.deepStrictEqual(result, {
			corticalHU: 1200,
			cancellousHU: 400,
			apicalHU: 1000,
		});
	});

	test("handles 1 sample correctly", () => {
		const samples = [800];
		const result = extractHUZones(samples);
		// corticalCount = 1, apicalCount = 1
		// cortical: [800] -> avg 800
		// cancellous: empty, falls back to full array -> avg 800
		// apical: [800] -> avg 800
		assert.deepStrictEqual(result, {
			corticalHU: 800,
			cancellousHU: 800,
			apicalHU: 800,
		});
	});

	test("handles 2 samples correctly", () => {
		const samples = [1000, 600];
		const result = extractHUZones(samples);
		// corticalCount = 1, apicalCount = 1
		// cortical: [1000] -> avg 1000
		// apical: [600] -> avg 600
		// cancellous: empty, falls back to full array -> avg 800
		assert.deepStrictEqual(result, {
			corticalHU: 1000,
			cancellousHU: 800,
			apicalHU: 600,
		});
	});

	test("handles array with varying values", () => {
		const samples = [1200, 1100, 300, 200, 150, 400, 800, 900];
		// length 8
		// corticalCount = round(8 * 0.2) = 2 -> [1200, 1100], avg 1150
		// apicalCount = round(8 * 0.2) = 2 -> [800, 900], avg 850
		// cancellous = middle 4 -> [300, 200, 150, 400], sum 1050, avg 262.5
		const result = extractHUZones(samples);
		assert.deepStrictEqual(result, {
			corticalHU: 1150,
			cancellousHU: 262.5,
			apicalHU: 850,
		});
	});
});

import * as assert from "node:assert";
import { beforeEach, describe, it } from "node:test";
import {
	ClinicalStore,
	checkImplantCollision,
	type VirtualImplant,
} from "./clinicalImplants.js";

describe("clinicalImplants - checkImplantCollision", () => {
	beforeEach(() => {
		ClinicalStore.clear();
	});

	it("should return false when no nerves exist", () => {
		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant), false);
	});

	it("should return false when implant is far from nerve", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 20, y: 0, z: 0 }); // Nerve at x=20

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), false);
	});

	it("should return true when implant intersects nerve directly", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 0, y: 0, z: 5 }); // Nerve directly on implant path

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), true);
	});

	it("should return true when implant is dangerously close to nerve", () => {
		// Default collisionDistance = threshold(2.0) + implantRadius(2.0) = 4.0
		// Nerve radius is nerve.diameter / 2 = 2.0 / 2 = 1.0 (by default in addNervePoint it's 2.0)
		// Distance allowed before collision: collisionDistSquared + nerveRadius^2
		// = 4^2 + 1^2 = 16 + 1 = 17 => sqrt(17) ~= 4.12

		ClinicalStore.addNervePoint("nerve-1", { x: 3.5, y: 0, z: 5 }); // Nerve is 3.5 units away from implant axis

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), true);
	});

	it("should return false when implant is just outside danger zone", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 5.0, y: 0, z: 5 }); // Nerve is 5.0 units away from implant axis

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), false);
	});

	it("should return false when nerve is above implant tip but further than length", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 0, y: 0, z: 15 }); // Nerve is above implant, but implant only goes to z=10

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), false);
	});

	it("should return false when nerve is below implant base", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 0, y: 0, z: -5 }); // Nerve is below implant

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 }, // pointing up
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), false);
	});

	it("should respect custom threshold distance", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 6, y: 0, z: 5 });

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 },
			length: 10,
			diameter: 4,
		};

		// collisionDistSquared = (threshold + 2.0)^2
		// nerve is 6.0 away. nerveRadius = 1.0 (from 2.0/2 diameter)
		// distance allowed: (threshold + 2.0)^2 + 1.0
		// actual distance squared is 6^2 = 36
		// If threshold = 2.0, threshold+2 = 4, 16+1 = 17, 36 < 17 is false
		assert.strictEqual(checkImplantCollision(implant, 2.0), false);

		// If threshold = 5.0, threshold+2 = 7, 49+1 = 50, 36 < 50 is true
		assert.strictEqual(checkImplantCollision(implant, 5.0), true);
	});

	it("should use default threshold distance if omitted", () => {
		// Default threshold is 2.0
		ClinicalStore.addNervePoint("nerve-1", { x: 3.5, y: 0, z: 5 });

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 },
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant), true);

		ClinicalStore.clear();
		ClinicalStore.addNervePoint("nerve-1", { x: 5.0, y: 0, z: 5 });

		assert.strictEqual(checkImplantCollision(implant), false);
	});

	it("should correctly detect collision with a non-axis-aligned implant", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 5, y: 5, z: 5 });

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			// 45 degree angle in x-y plane
			direction: { x: Math.sqrt(0.5), y: Math.sqrt(0.5), z: 0 },
			length: 10,
			diameter: 4,
		};

		// The segment goes from (0,0,0) to approx (7.07, 7.07, 0)
		// Nerve is at (5, 5, 5). Shortest distance is to (5, 5, 0), which is dist=5.
		// Allowed distance squared: (2.0 + 2.0)^2 + 1.0 = 17.
		// Actual distance squared is 5^2 = 25. 25 < 17 is false.
		assert.strictEqual(checkImplantCollision(implant, 2.0), false);

		// Now move nerve point closer to the implant
		ClinicalStore.clear();
		ClinicalStore.addNervePoint("nerve-1", { x: 5, y: 5, z: 3.5 });

		// Actual distance squared is 3.5^2 = 12.25. 12.25 < 17 is true.
		assert.strictEqual(checkImplantCollision(implant, 2.0), true);
	});

	it("should detect collision when only one of multiple nerve points is close", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 20, y: 0, z: 5 });
		ClinicalStore.addNervePoint("nerve-1", { x: 15, y: 0, z: 5 });
		ClinicalStore.addNervePoint("nerve-1", { x: 3.5, y: 0, z: 5 }); // close point

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 },
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), true);
	});

	it("should return false if all points in a multi-point nerve are far", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 20, y: 0, z: 5 });
		ClinicalStore.addNervePoint("nerve-1", { x: 15, y: 0, z: 5 });
		ClinicalStore.addNervePoint("nerve-1", { x: 10, y: 0, z: 5 });

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 },
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), false);
	});

	it("should detect collision across multiple nerves", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 20, y: 0, z: 5 }); // Far nerve
		ClinicalStore.addNervePoint("nerve-2", { x: 3.5, y: 0, z: 5 }); // Close nerve

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 },
			length: 10,
			diameter: 4,
		};

		assert.strictEqual(checkImplantCollision(implant, 2.0), true);
	});

	it("should handle zero-length implants correctly", () => {
		ClinicalStore.addNervePoint("nerve-1", { x: 0, y: 0, z: 3.5 });

		const implant: VirtualImplant = {
			id: "implant-1",
			position: { x: 0, y: 0, z: 0 },
			direction: { x: 0, y: 0, z: 1 },
			length: 0, // Zero length
			diameter: 4,
		};

		// The implant is just a point at (0,0,0).
		// Distance to nerve (0,0,3.5) is 3.5. Squared is 12.25.
		// Allowed distance squared is 17.
		assert.strictEqual(checkImplantCollision(implant, 2.0), true);
	});
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { clampMprSlabMm, trilinearInterpolate } from "./mprMath.js";

describe("clampMprSlabMm", () => {
	it("should return the value correctly rounded if within bounds [1, 30]", () => {
		assert.equal(clampMprSlabMm(15), 15);
		assert.equal(clampMprSlabMm(15.1), 15);
		assert.equal(clampMprSlabMm(15.5), 16);
		assert.equal(clampMprSlabMm(1), 1);
		assert.equal(clampMprSlabMm(30), 30);
	});

	it("should clamp values below the minimum bound (1)", () => {
		assert.equal(clampMprSlabMm(0), 1);
		assert.equal(clampMprSlabMm(-10), 1);
		assert.equal(clampMprSlabMm(0.4), 1);
	});

	it("should clamp values above the maximum bound (30)", () => {
		assert.equal(clampMprSlabMm(31), 30);
		assert.equal(clampMprSlabMm(100), 30);
		assert.equal(clampMprSlabMm(30.5), 30);
	});

	it("should handle non-finite values by returning the fallback value (1)", () => {
		assert.equal(clampMprSlabMm(NaN), 1);
		assert.equal(clampMprSlabMm(Infinity), 1);
		assert.equal(clampMprSlabMm(-Infinity), 1);
	});
});

describe("trilinearInterpolate", () => {
	const mockData = new Float32Array([
		10,
		20, // z=0, y=0
		30,
		40, // z=0, y=1
		50,
		60, // z=1, y=0
		70,
		80, // z=1, y=1
	]);
	const dims: [number, number, number] = [2, 2, 2];

	it("should return exact values at integer coordinates", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 0, 0, 0), 10);
		assert.equal(trilinearInterpolate(mockData, dims, 1, 0, 0), 20);
		assert.equal(trilinearInterpolate(mockData, dims, 0, 1, 0), 30);
		assert.equal(trilinearInterpolate(mockData, dims, 1, 1, 0), 40);
		assert.equal(trilinearInterpolate(mockData, dims, 0, 0, 1), 50);
		assert.equal(trilinearInterpolate(mockData, dims, 1, 0, 1), 60);
		assert.equal(trilinearInterpolate(mockData, dims, 0, 1, 1), 70);
		assert.equal(trilinearInterpolate(mockData, dims, 1, 1, 1), 80);
	});

	it("should interpolate correctly along the X axis", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 0.5, 0, 0), 15);
		assert.equal(trilinearInterpolate(mockData, dims, 0.25, 0, 0), 12.5);
	});

	it("should interpolate correctly along the Y axis", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 0, 0.5, 0), 20);
	});

	it("should interpolate correctly along the Z axis", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 0, 0, 0.5), 30);
	});

	it("should interpolate correctly on a 2D face (X and Y)", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 0.5, 0.5, 0), 25);
	});

	it("should trilinearly interpolate correctly exactly in the center", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 0.5, 0.5, 0.5), 45);
	});

	it("should handle boundary values properly without out-of-bounds errors", () => {
		assert.equal(trilinearInterpolate(mockData, dims, 1, 1, 1), 80);
	});
});

