	describe("clinicalRuleSummaryForUi", () => {
		it("calculates summary correctly", () => {
			const evaluations = [
				{ resolved: true, missingRequiredServiceIds: [] },
				{
					resolved: false,
					severity: "blocker",
					missingRequiredServiceIds: ["srv-1"],
				},
				{
					resolved: false,
					severity: "warning",
					missingRequiredServiceIds: ["srv-2", "srv-3"],
				},
				{
					resolved: false,
					severity: "info",
					missingRequiredServiceIds: ["srv-2"],
				},
			] as unknown as Dashboard["clinicalRuleEvaluations"];

			const summary = clinicalRuleSummaryForUi(evaluations, 5);

			assert.deepEqual(summary, {
				activeRules: 5,
				evaluatedRules: 4,
				unresolved: 3,
				blockers: 1,
				warnings: 1,
				requiredServices: 3, // srv-1, srv-2, srv-3
				coveredRules: 1,
			});
		});

		it("handles empty evaluations", () => {
			const summary = clinicalRuleSummaryForUi([], 2);
			assert.deepEqual(summary, {
				activeRules: 2,
				evaluatedRules: 0,
				unresolved: 0,
				blockers: 0,
				warnings: 0,
				requiredServices: 0,
				coveredRules: 0,
			});
		});
	});

